INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语副词，表示程度相当高。"}, {"text": "慢", "is_correct": false, "explanation": "màn（第四声）与 mán（第二声）声调不同，意思是慢。"}, {"text": "难", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是困难。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。"}], "explanations": {"蛮": "正确。蛮 mán 是口语副词，表示程度相当高。", "慢": "màn（第四声）与 mán（第二声）声调不同，意思是慢。", "难": "nán（第二声）与 mán 声母不同（n/m），意思是困难。", "烦": "fán（第二声）与 mán 声母不同（f/m），意思是烦恼。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅，“唱歌只好听的”说不通。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“小王唱歌才好听的”说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“小王唱歌蛮好听的”表示程度相当高，口语中常用。"}, {"text": "更", "is_correct": false, "explanation": "语义：“更好听”需要比较对象，句中没有比较的基准，说不通。"}], "explanations": {"只": "语义：“只”表示仅仅，“唱歌只好听的”说不通。", "才": "语义：“才”表示刚好或仅仅，与程度无关，“小王唱歌才好听的”说不通。", "蛮": "正确。“小王唱歌蛮好听的”表示程度相当高，口语中常用。", "更": "语义：“更好听”需要比较对象，句中没有比较的基准，说不通。"}, "sentence_index": 6, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天很蛮累。", "explanation": "这里不应重复表示程度。“很”与“蛮”都表示程度，只保留其一，应说“我今天蛮累”。"}, {"text": "这个孩子蛮是老师。", "explanation": "这里应该直接说“这个孩子是老师”。“蛮”是程度副词，不能修饰判断动词“是”。"}, {"text": "他蛮扛起箱子就走了。", "explanation": "这里应该用〈一下子〉。“蛮”是程度副词，不能修饰“扛起”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生蛮认真地，老师很喜欢他。", "corrected_sentence": "这个学生蛮认真的，老师很喜欢他。", "error_description": "“地”错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮认真的”，不能说“蛮认真地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小伙子蛮热情地，大家都喜欢他。", "corrected_sentence": "这个小伙子蛮热情的，大家都喜欢他。", "error_description": "的／地错误：“蛮”修饰形容词作谓语时，形容词后应用“的”，说“蛮热情的”；“地”用于修饰动词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
