INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过网络传送图像和声音进行的远程会议。", "primary_collocate": null, "pronunciation": "shì pín huì yì", "ipa": "ʂʐ̩˥˩ pʰin˧˥ xuei˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "公司明天上午有一场视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外，只能参加视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为网络不好，视频会议停了几分钟。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的视频会议有二十多个人参加。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用视频会议和北京的同事谈工作。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频会议开始前，请先打开声音。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天不能出门，所以改成视频会议。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次视频会议开了一个小时，大家都很累。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在视频会议上说了新计划。", "target_word": "视频会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开视频会议比出差便宜多了。", "target_word": "视频会议", "complexity_tier": "T3", "furigana": "kāi shì pín huì yì bǐ chū chāi pián yi duō le", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "視頻會議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "借助网络连接异地人员的远程会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fc151bc-86c4-4f14-a3f6-2b1006de24f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：“场”可以计量会议，“视频会议”是通过网络进行的远程会议，与“明天上午”搭配。"}, {"text": "电子邮件", "is_correct": false, "explanation": "搭配：“场”计量活动、比赛、会议等，不能用来数“电子邮件”，应说“一封电子邮件”。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭通常在中午吃，与“明天上午”的时间矛盾。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“场”不能计量“水果”，应说“一箱水果”或“一盘水果”。"}], "explanations": {"视频会议": "正确：“场”可以计量会议，“视频会议”是通过网络进行的远程会议，与“明天上午”搭配。", "电子邮件": "搭配：“场”计量活动、比赛、会议等，不能用来数“电子邮件”，应说“一封电子邮件”。", "午饭": "语义：午饭通常在中午吃，与“明天上午”的时间矛盾。", "水果": "搭配：“场”不能计量“水果”，应说“一箱水果”或“一盘水果”。"}, "sentence_index": 0, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妈妈每天晚上都有一次视频会议。", "explanation": "这里应该用〈视频通话〉。两人之间的视频聊天叫视频通话，视频会议指多人一起参加的正式会议。"}, {"text": "运动员在视频会议中打破了纪录。", "explanation": "这里应该用〈比赛〉。打破纪录发生在体育比赛中，视频会议是远程开会，不能用于比赛。"}, {"text": "学生在视频会议上游了一百米。", "explanation": "这里应该用〈泳池〉。游一百米要在泳池或海里进行，视频会议是远程开会，不能作为游泳的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视频会议", "is_correct": true, "explanation": "正确：下雨不能出门，只能改成通过网络进行的远程会议。"}, {"text": "郊游", "is_correct": false, "explanation": "语义：郊游需要外出，与“不能出门”直接矛盾。"}, {"text": "雅集", "is_correct": false, "explanation": "语域：“雅集”是文言色彩很浓的词，与口语化的句子不协调。"}, {"text": "游行", "is_correct": false, "explanation": "语义：游行要走上街头，与“不能出门”直接矛盾。"}], "explanations": {"视频会议": "正确：下雨不能出门，只能改成通过网络进行的远程会议。", "郊游": "语义：郊游需要外出，与“不能出门”直接矛盾。", "雅集": "语域：“雅集”是文言色彩很浓的词，与口语化的句子不协调。", "游行": "语义：游行要走上街头，与“不能出门”直接矛盾。"}, "sentence_index": 6, "correct_answer": "视频会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在视频会议里玩了一整天。", "explanation": "这里应该用〈游乐园〉。玩耍的场所是游乐园，视频会议是远程开会，不能作为玩耍的地方。"}, {"text": "我们在视频会议上捡了很多贝壳。", "explanation": "这里应该用〈海边〉。捡贝壳要在海边，视频会议是远程开会，不能作为捡东西的地方。"}, {"text": "我们在视频会议里爬了一座山。", "explanation": "这里应该用〈登山〉。登山要在山上进行，视频会议是远程开会，不能作为户外活动的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天开了一条视频会议。", "corrected_sentence": "我们今天开了一场视频会议。", "error_description": "量词误用：会议应用“场”或“次”计量，“条”用于细长的东西，应说“一场视频会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的视频会议开很顺利。", "corrected_sentence": "今天的视频会议开得很顺利。", "error_description": "补语前漏掉结构助词“得”，“很顺利”作补语要由“得”引出，应说“开得很顺利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
