INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "替别人着想，为别人考虑。", "primary_collocate": null, "pronunciation": "shè xiǎng", "ipa": "ʂɤ˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "做决定时，要多为家人设想。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师处处为学生设想，大家都很感谢他。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他替朋友设想得很周到。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是先为孩子设想，很少想自己。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该替客人设想，把房间收拾干净。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你也替我设想一下，我真的没有时间。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为员工设想，每天提供免费午饭。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事只顾自己，从来不为别人设想。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店为老人设想了很多方便的服务。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友为我设想得这么多，我很感动。", "target_word": "设想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设想了", "label": "体标（了）"}, {"form": "设想过", "label": "体标（过）"}, {"form": "设想着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "为别人考虑、着想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fc151bc-86c4-4f14-a3f6-2b1006de24f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设想", "is_correct": true, "explanation": "正确：“为家人设想”指替家人着想，与“做决定时要多……”的语境搭配。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”与替家人着想相反，与“要多为家人”的语气矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能接“为家人”加宾语。"}, {"text": "出卖", "is_correct": false, "explanation": "语义：“出卖”指背叛别人，与“为家人”的好意相反。"}], "explanations": {"设想": "正确：“为家人设想”指替家人着想，与“做决定时要多……”的语境搭配。", "欺骗": "语义：“欺骗”与替家人着想相反，与“要多为家人”的语气矛盾。", "游泳": "配价：“游泳”是不及物动词，不能接“为家人”加宾语。", "出卖": "语义：“出卖”指背叛别人，与“为家人”的好意相反。"}, "sentence_index": 0, "correct_answer": "设想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈轻声设想哭泣的孩子。", "explanation": "这里应该用〈安慰〉。轻声安慰是直接对人说话使其平静，设想是在心里替人考虑或想象，不能用于安抚哭泣的孩子。"}, {"text": "医生用听诊器设想了病人的胸口。", "explanation": "这里应该用〈检查〉。用听诊器查看胸口是实际动作，设想是心里的思考，不能表示查看身体。"}, {"text": "服务员用托盘设想了菜。", "explanation": "这里应该用〈端〉。用托盘端菜是搬运动作，设想是心里的活动，不能表示搬运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设想", "is_correct": true, "explanation": "正确：“为员工设想”指替员工着想，与“每天提供免费午饭”的福利一致。"}, {"text": "削减", "is_correct": false, "explanation": "语义：“削减”与“每天提供免费午饭”的福利相反，句子前后矛盾。"}, {"text": "搬家", "is_correct": false, "explanation": "配价：“搬家”是不及物动词，不能接“为员工”加宾语。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：“罚款”是对员工的处罚，与“提供免费午饭”的好意矛盾。"}], "explanations": {"设想": "正确：“为员工设想”指替员工着想，与“每天提供免费午饭”的福利一致。", "削减": "语义：“削减”与“每天提供免费午饭”的福利相反，句子前后矛盾。", "搬家": "配价：“搬家”是不及物动词，不能接“为员工”加宾语。", "罚款": "语义：“罚款”是对员工的处罚，与“提供免费午饭”的好意矛盾。"}, "sentence_index": 6, "correct_answer": "设想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师用刀把萝卜设想成了细丝。", "explanation": "这里应该用〈切〉。用刀切萝卜是实际的动作，设想是心里想象，不能表示用刀切开。"}, {"text": "他用抹布认真设想了窗户。", "explanation": "这里应该用〈擦〉。擦窗户是实际的动作，设想是心里的活动，不能表示擦拭。"}, {"text": "工人用锤子设想了一颗钉子。", "explanation": "这里应该用〈钉〉。钉钉子是实际的动作，设想是心里的活动，不能表示钉的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事总是先别人设想。", "corrected_sentence": "他做事总是先为别人设想。", "error_description": "介词漏掉：“为别人设想”中的“为”表示替谁着想，不能省略，应说“先为别人设想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她替同学设想的很周到。", "corrected_sentence": "她替同学设想得很周到。", "error_description": "补语标记错误：表示程度的补语要用“得”连接，“设想的很周到”应为“设想得很周到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
