INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97029, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "最少，不能比这个更少了。", "primary_collocate": null, "pronunciation": "qǐ mǎ", "ipa": "tɕʰi˨˩˦ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "从这里到机场，起码要一个小时。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书起码有五百页。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加这次旅行，起码要带五百块钱。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子很高，起码有一米九。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间里起码住了十个人。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要学会这首歌，起码得练三天。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆人很多，起码要等四十分钟。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这件衣服起码用了两个星期。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班起码有一半的同学去过北京。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这辆车起码要三万块。", "target_word": "起码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "数量、时间上最少也要有这么多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fc151bc-86c4-4f14-a3f6-2b1006de24f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起码", "is_correct": true, "explanation": "正确：“起码”表示数量的下限，“从这里到机场，起码要一个小时”即至少需要一个小时。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示有时、不经常，而从这里到机场是一次具体行程，所需时间不是偶发的。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：已经表示动作已完成或状态已出现，与表示将来需要时间的“要”不相合。"}, {"text": "尤其", "is_correct": false, "explanation": "搭配：尤其用于突出某一方面，需要前文有比较或范围，单独说“尤其要一个小时”不成立。"}], "explanations": {"起码": "正确：“起码”表示数量的下限，“从这里到机场，起码要一个小时”即至少需要一个小时。", "偶尔": "语义：偶尔表示有时、不经常，而从这里到机场是一次具体行程，所需时间不是偶发的。", "已经": "体貌：已经表示动作已完成或状态已出现，与表示将来需要时间的“要”不相合。", "尤其": "搭配：尤其用于突出某一方面，需要前文有比较或范围，单独说“尤其要一个小时”不成立。"}, "sentence_index": 0, "correct_answer": "起码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个电梯起码不能超过十二人。", "explanation": "这里表示上限，应该用〈至多〉。起码表示数量下限，与这里的上限意思相矛盾。"}, {"text": "这本书起码最多五百页。", "explanation": "这里表示上限，应该用〈最多〉单用。起码表示下限，与“最多”的上限义相矛盾。"}, {"text": "这本书起码不到五百页。", "explanation": "起码表示数量下限，与这里的上限意思相矛盾；表示上限应该用〈最多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起码", "is_correct": true, "explanation": "正确：“起码”表示最少要等四十分钟，与前文“人很多”的情况相符。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：幸好表示庆幸，而等待是不便之事，“人很多，幸好要等四十分钟”前后语义相违。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然发生，而“人很多”是持续的情况，二者不相合。"}, {"text": "尚且", "is_correct": false, "explanation": "搭配：尚且需与“更”或“何况”呼应，单句中不能独立使用。"}], "explanations": {"起码": "正确：“起码”表示最少要等四十分钟，与前文“人很多”的情况相符。", "幸好": "语义：幸好表示庆幸，而等待是不便之事，“人很多，幸好要等四十分钟”前后语义相违。", "忽然": "语义：忽然表示突然发生，而“人很多”是持续的情况，二者不相合。", "尚且": "搭配：尚且需与“更”或“何况”呼应，单句中不能独立使用。"}, "sentence_index": 6, "correct_answer": "起码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "买这辆车起码正好要三万块。", "explanation": "这里表示精确数量，与“起码”的下限义相矛盾，应该用〈刚好〉。"}, {"text": "买这辆车起码不超过三万块。", "explanation": "起码表示数量下限，与这里的上限意思相矛盾；表示上限应该用〈最多〉。"}, {"text": "买这辆车起码只花了两万块。", "explanation": "这里表示仅有、最多的数量，应该用〈仅仅〉。起码表示下限，与句中的限定意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路起码有不到两公里。", "corrected_sentence": "这条路起码有两公里。", "error_description": "语义冲突：“起码”表示下限，“不到”表示上限，二者矛盾；应删去“不到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个会议起码要开了一个小时。", "corrected_sentence": "这个会议起码要开一个小时。", "error_description": "体标错误：“要”指将来所需的时间，不能与完成体“了”同用，应说“起码要开一个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
