INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人对你好，你也对他好，还给他。", "primary_collocate": null, "pronunciation": "huán bào", "ipa": "xwan˧˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "别人帮了你，你也要还报他。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我这么好，我一定要还报他。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她照顾过我，我想还报她。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我好，我也用好心还报他。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师这样关心我，我应该好好还报她。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对人好，别人也会还报你。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在我生病时常来照顾，我想好好还报他。", "target_word": "还报", "complexity_tier": "T3", "furigana": "tā zài wǒ shēngbìng shí cháng lái zhàogù, wǒ xiǎng hǎohǎo huán bào tā.", "sentence_source": "generated"}, {"text": "邻居常给我们送菜，妈妈也送水果还报他们。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直对我很好，我什么时候才能还报他呢？", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁对你好，你就要还报谁。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还报了", "label": "体标"}, {"form": "还报过", "label": "体标"}], "register": "书面", "sense_fingerprint": "别人对自己好，自己也用好意回报对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97059, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报 huán bào，意思是别人对你好，你也用好意回报对方，即本词的意思。"}, {"text": "环保", "is_correct": false, "explanation": "环保 huánbǎo 与还报的第二个音节声调不同（bǎo 第三声，bào 第四声），意思是保护环境。"}, {"text": "怀抱", "is_correct": false, "explanation": "怀抱 huáibào 第一个音节韵母不同（huái 与 huán），意思是胸怀，或用手臂抱着。"}, {"text": "汇报", "is_correct": false, "explanation": "汇报 huìbào 第一个音节的韵母和声调都不同（huì 第四声），意思是向上级或集体说明情况。"}], "explanations": {"还报": "还报 huán bào，意思是别人对你好，你也用好意回报对方，即本词的意思。", "环保": "环保 huánbǎo 与还报的第二个音节声调不同（bǎo 第三声，bào 第四声），意思是保护环境。", "怀抱": "怀抱 huáibào 第一个音节韵母不同（huái 与 huán），意思是胸怀，或用手臂抱着。", "汇报": "汇报 huìbào 第一个音节的韵母和声调都不同（huì 第四声），意思是向上级或集体说明情况。"}, "sentence_index": null, "correct_answer": "还报"}, "level_3": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报：别人帮了你，你用好意回报他，符合语境。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出别人的错误，与前句“帮了你”的情境相反。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指对不起别人的好意或期望，与“帮了你”的情境不合。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”指避开不见，与“别人帮了你”的回应相反。"}], "explanations": {"还报": "还报：别人帮了你，你用好意回报他，符合语境。", "批评": "语义：“批评”是指出别人的错误，与前句“帮了你”的情境相反。", "辜负": "语义：“辜负”指对不起别人的好意或期望，与“帮了你”的情境不合。", "躲避": "语义：“躲避”指避开不见，与“别人帮了你”的回应相反。"}, "sentence_index": 0, "correct_answer": "还报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骂了我，我要还报他。", "explanation": "这里应该用〈报复〉。还报只用于回报别人的好意，被人伤害后想伤害对方要用报复。"}, {"text": "这件衣服标价五百，我还报了一百块。", "explanation": "这里应该用〈还价〉。还报是回报别人的好意，买东西时提出较低的价格要用还价。"}, {"text": "我下个月会还报这笔借款。", "explanation": "这里应该用〈偿还〉。还报只用于人情上的回报，借款这类债务要用偿还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报：对方常来照顾我，我用好意回报他，符合语境。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：“疏远”指关系变冷淡，与“常来照顾”的情境相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”指讨厌、看不起，与“常来照顾”的情境不合。"}, {"text": "报以", "is_correct": false, "explanation": "搭配：“报以”后通常接“微笑”“掌声”等，不能直接接“他”。"}], "explanations": {"还报": "还报：对方常来照顾我，我用好意回报他，符合语境。", "疏远": "语义：“疏远”指关系变冷淡，与“常来照顾”的情境相反。", "嫌弃": "语义：“嫌弃”指讨厌、看不起，与“常来照顾”的情境不合。", "报以": "搭配：“报以”后通常接“微笑”“掌声”等，不能直接接“他”。"}, "sentence_index": 6, "correct_answer": "还报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我借了他五百块，下个月会还报给他。", "explanation": "这里应该用〈还钱〉。还报指用好意回报别人的恩情，归还借的钱要用还钱。"}, {"text": "工厂还报了村民的损失。", "explanation": "这里应该用〈赔偿〉。还报只用于回报别人的恩情，对损失进行补偿要用赔偿。"}, {"text": "我的申请交上去一周了，学校还没有还报我。", "explanation": "这里应该用〈答复〉。还报是回报别人的好意，对申请作出书面回复要用答复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直帮我，我一定要好好还报过他。", "corrected_sentence": "他一直帮我，我一定要好好还报他。", "error_description": "错误：“还报过他”；正确：“还报他”。“过”表示曾经有过的经历，与“一定要”表示的将来意愿矛盾，句中应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他帮过我很多次，我一直想好好还报了他。", "corrected_sentence": "他帮过我很多次，我一直想好好还报他。", "error_description": "错误：“想好好还报了他”；正确：“想好好还报他”。“想”表示将来的希望，与“了”表示的完成意义矛盾，句中应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
