INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以行动回报别人的恩惠或做过的事。", "primary_collocate": null, "pronunciation": "huán bào", "ipa": "xwan˧˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他想用工作还报父母的恩情。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生救了她，她长大后当护士还报社会。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人帮过我家，我回村盖了学校还报他们。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会用行动还报大家的帮助。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了医生后，免费为村民看病，还报乡亲们。", "target_word": "还报", "complexity_tier": "T3", "furigana": "tā dāng le yīshēng hòu, miǎnfèi wèi cūnmín kànbìng, huán bào xiāngqīnmen.", "sentence_source": "generated"}, {"text": "她用一生还报了那家人的恩情。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家培养了我，我要还报国家。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱捐给孤儿院，还报当年的帮助。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的好意，我们没有办法还报。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学成回国，用技术还报家乡。", "target_word": "还报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还报了", "label": "体标"}, {"form": "还报过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用实际行动报答他人或社会的恩惠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报 huán bào，意思是以实际行动报答别人的恩惠，即本词的意思。"}, {"text": "环保", "is_correct": false, "explanation": "环保 huánbǎo 与还报的第二个音节声调不同（bǎo 第三声，bào 第四声），意思是保护环境。"}, {"text": "怀抱", "is_correct": false, "explanation": "怀抱 huáibào 第一个音节韵母不同（huái 与 huán），意思是胸怀，或用手臂抱着。"}, {"text": "汇报", "is_correct": false, "explanation": "汇报 huìbào 第一个音节的韵母和声调都不同（huì 第四声），意思是向上级或集体说明情况。"}], "explanations": {"还报": "还报 huán bào，意思是以实际行动报答别人的恩惠，即本词的意思。", "环保": "环保 huánbǎo 与还报的第二个音节声调不同（bǎo 第三声，bào 第四声），意思是保护环境。", "怀抱": "怀抱 huáibào 第一个音节韵母不同（huái 与 huán），意思是胸怀，或用手臂抱着。", "汇报": "汇报 huìbào 第一个音节的韵母和声调都不同（huì 第四声），意思是向上级或集体说明情况。"}, "sentence_index": null, "correct_answer": "还报"}, "level_3": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报：用工作回报父母的养育之恩，符合语境。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指对不起别人的期望或好意，与“想用工作”的回报意图相反。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”指抛开不要，与“想用工作”的意图相反，恩情不能被丢弃。"}, {"text": "发挥", "is_correct": false, "explanation": "搭配：“发挥”后接“作用”“优势”等，不接“恩情”。"}], "explanations": {"还报": "还报：用工作回报父母的养育之恩，符合语境。", "辜负": "语义：“辜负”指对不起别人的期望或好意，与“想用工作”的回报意图相反。", "丢弃": "语义：“丢弃”指抛开不要，与“想用工作”的意图相反，恩情不能被丢弃。", "发挥": "搭配：“发挥”后接“作用”“优势”等，不接“恩情”。"}, "sentence_index": 0, "correct_answer": "还报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把借来的书还报给了图书馆。", "explanation": "这里应该用〈归还〉。还报是回报别人的恩惠，归还借来的书要用归还。"}, {"text": "他在课堂上还报了老师的问题。", "explanation": "这里应该用〈回答〉。还报是回报别人的恩惠，回应问题要用回答。"}, {"text": "他花了十年时间还报那个害他的人。", "explanation": "这里应该用〈报复〉。还报只用于回报恩惠，对伤害自己的人进行报复要用报复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还报", "is_correct": true, "explanation": "还报：国家培养了我，我回报国家，符合语境。"}, {"text": "背叛", "is_correct": false, "explanation": "语义：“背叛”指违背对方的信任，与“国家培养了我”的情境相反。"}, {"text": "批判", "is_correct": false, "explanation": "语义：“批判”指指出错误，与“国家培养了我”的感激语境不合。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”多接节日、胜利等，不接“国家”，单独说“庆祝国家”不通。"}], "explanations": {"还报": "还报：国家培养了我，我回报国家，符合语境。", "背叛": "语义：“背叛”指违背对方的信任，与“国家培养了我”的情境相反。", "批判": "语义：“批判”指指出错误，与“国家培养了我”的感激语境不合。", "庆祝": "搭配：“庆祝”多接节日、胜利等，不接“国家”，单独说“庆祝国家”不通。"}, "sentence_index": 6, "correct_answer": "还报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差的费用可以还报。", "explanation": "这里应该用〈报销〉。还报只用于回报别人的恩惠，费用的核销要用报销。"}, {"text": "他向警察还报了那个小偷。", "explanation": "这里应该用〈举报〉。还报用于回报恩惠，向有关部门告发坏人要用举报。"}, {"text": "学校还报了这次考试的成绩。", "explanation": "这里应该用〈通报〉。还报用于回报恩惠，把情况公开告知大家要用通报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一生的时间还报过父母的养育之恩。", "corrected_sentence": "她用一生的时间还报父母的养育之恩。", "error_description": "错误：“还报过父母的养育之恩”；正确：“还报父母的养育之恩”。“过”表示曾经经历过，与“用一生的时间”这种持续的过程不合，句中应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学成以后，还报用技术家乡。", "corrected_sentence": "他学成以后，用技术还报家乡。", "error_description": "错误：“还报用技术家乡”；正确：“用技术还报家乡”。“用技术”是动词“还报”的状语，须放在“还报”之前，不能放在动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
