INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97063, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能让你看见自己样子的东西。", "primary_collocate": null, "pronunciation": "jìng zi", "ipa": "tɕiŋ˥˩ tsɯ", "syllable_count": 2, "sentences": [{"text": "她在镜子里看自己。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我照镜子，发现脸很脏。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上都照镜子。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "镜子里的我今天很高兴。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她站在镜子前，整理头发。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看看镜子，衣服整齐吗？", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗看着镜子里的自己叫了起来。", "target_word": "镜子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走到镜子前面，看了看自己的脸。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩对着镜子笑个不停。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢镜子里的样子，就不照了。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "鏡子", "label": "繁体"}, {"form": "穿衣镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来照自己、看自己样子的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "镜子", "is_correct": true, "explanation": "正确：“镜子”能映出人影，“她在镜子里看自己”与句意相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书里的字不能映出人影，“在书里看自己”不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能映出人影，句意不通。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能映出人影，“在衣服里看自己”不通。"}], "explanations": {"镜子": "正确：“镜子”能映出人影，“她在镜子里看自己”与句意相符。", "书": "语义：书里的字不能映出人影，“在书里看自己”不通。", "玩具": "语义：玩具不能映出人影，句意不通。", "衣服": "语义：衣服不能映出人影，“在衣服里看自己”不通。"}, "sentence_index": 0, "correct_answer": "镜子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用镜子看书上的小字，看得清清楚楚。", "explanation": "这里应该用〈放大镜〉。能把小字放大看清的是放大镜，镜子是用来映出人影的器物。"}, {"text": "渔民用镜子远望海上的船只。", "explanation": "这里应该用〈望远镜〉。远望景物要用望远镜，镜子是用来映出人影的器物。"}, {"text": "镜子很薄，戴着很舒服。", "explanation": "这里应该用〈镜片〉。戴在眼前的透光片叫镜片，镜子是用来照人影的器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": true, "explanation": "正确：“镜子”能映出人影，“小狗看着镜子里的自己”与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能映出人影，“石头里的自己”不通。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，映不出人影，句意不通。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“笑容”是表情，不是能映照人影的东西，不说笑容里的自己。"}], "explanations": {"镜子": "正确：“镜子”能映出人影，“小狗看着镜子里的自己”与句意相符。", "石头": "语义：石头不能映出人影，“石头里的自己”不通。", "云": "语义：云是天上的水汽，映不出人影，句意不通。", "笑容": "搭配：“笑容”是表情，不是能映照人影的东西，不说笑容里的自己。"}, "sentence_index": 6, "correct_answer": "镜子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴着镜子看书，眼睛很累。", "explanation": "这里应该用〈眼镜〉。戴在脸上帮助看书的是眼镜，镜子是用来照人影的。"}, {"text": "姐姐把镜子当尺子，量了量桌子的长度。", "explanation": "这里应该用〈尺子〉。量长度的是尺子，镜子是用来照人影的器物。"}, {"text": "这台摄像机的镜子脏了，拍出来的画面很模糊。", "explanation": "这里应该用〈镜头〉。摄像机前端的透镜叫镜头，镜子是用来照人影的器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在一只镜子前，系好了领带。", "corrected_sentence": "他站在一面镜子前，系好了领带。", "error_description": "“镜子”是扁平的物品，量词应用“面”，不宜用“只”。“只”多用于动物、成对的物品或某些器皿，不用于扁平的镜子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在镜子整理领带。", "corrected_sentence": "他在镜子里整理领带。", "error_description": "“镜子”表示处所时，后面要加方位词“里”或“前”，应说“在镜子里整理领带”或“在镜子前整理领带”。直接说“在镜子整理”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
