INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97075, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情的经过一句一句说出来。", "primary_collocate": null, "pronunciation": "chén shù", "ipa": "ʈʂʰən˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "警察请他陈述昨晚发生的事情。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢地陈述了事故的经过。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把当时的情况陈述一遍。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人在法官面前陈述了自己看到的一切。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在法庭上从头到尾陈述了那天的经过。", "target_word": "陈述", "complexity_tier": "T3", "furigana": "tā zài fǎtíng shàng cóng tóu dào wěi chénshù le nà tiān de jīngguò", "sentence_source": "generated"}, {"text": "孩子哭着陈述了事情的经过。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机向警察陈述了车祸发生的时间。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先陈述一下事情是怎么开始的。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陈述得很清楚，大家都听明白了。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生向校长陈述了打架的经过。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陈述了", "label": "体标（了）"}, {"form": "陈述过", "label": "体标（过）"}, {"form": "陈述着", "label": "体标（着）"}, {"form": "陈述句", "label": "复合"}], "register": "书面", "sense_fingerprint": "把事情发生的经过说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fc151bc-86c4-4f14-a3f6-2b1006de24f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97075, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：陈述 chén shù，表示把事情的经过一句一句说出来。"}, {"text": "尘世", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），尘世意思是人世间，指世俗的世界。"}, {"text": "陈设", "is_correct": false, "explanation": "shè 与 shù 韵母不同（e 与 u），陈设意思是摆设、布置。"}, {"text": "臣属", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，臣属意思是臣子、下属。"}, {"text": "成束", "is_correct": false, "explanation": "chéng 与 chén 韵尾不同（ng 与 n），成束意思是捆成一束。"}], "explanations": {"陈述": "正确：陈述 chén shù，表示把事情的经过一句一句说出来。", "尘世": "shì 与 shù 韵母不同（i 与 u），尘世意思是人世间，指世俗的世界。", "陈设": "shè 与 shù 韵母不同（e 与 u），陈设意思是摆设、布置。", "臣属": "shǔ（第三声）与 shù（第四声）声调不同，臣属意思是臣子、下属。", "成束": "chéng 与 chén 韵尾不同（ng 与 n），成束意思是捆成一束。"}, "sentence_index": null, "correct_answer": "陈述"}, "level_3": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：“陈述”表示把事情的经过说出来，“请他陈述昨晚发生的事情”即请他叙述昨晚的经过。"}, {"text": "策划", "is_correct": false, "explanation": "语义：策划指事先计划，不能用于已经发生的事情的经过。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝表示以喜悦之情纪念，不能用于泛指的事件经过。"}, {"text": "布置", "is_correct": false, "explanation": "搭配：布置多用于场地、任务，不能与“经过”搭配。"}], "explanations": {"陈述": "正确：“陈述”表示把事情的经过说出来，“请他陈述昨晚发生的事情”即请他叙述昨晚的经过。", "策划": "语义：策划指事先计划，不能用于已经发生的事情的经过。", "庆祝": "语义：庆祝表示以喜悦之情纪念，不能用于泛指的事件经过。", "布置": "搭配：布置多用于场地、任务，不能与“经过”搭配。"}, "sentence_index": 0, "correct_answer": "陈述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她陈述了这幅画的颜色和线条。", "explanation": "这里应该用〈描绘〉。陈述用于事情经过、观点等说明性内容，描绘颜色和线条要用“描绘”。"}, {"text": "他生动地陈述了那片风景。", "explanation": "这里应该用〈描述〉。陈述用于事情的经过，描写风景要用“描述”。"}, {"text": "他给孩子陈述了一首歌。", "explanation": "这里应该用〈唱〉。陈述是把经过或理由说清楚，唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：“陈述”表示把事情的经过说出来，“司机向警察陈述了车祸发生的时间”符合语境。"}, {"text": "预测", "is_correct": false, "explanation": "语义：预测指对未来的推断，车祸已经发生，无法预测其时间。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：推迟指把时间往后延，车祸的发生时间已经确定，不能推迟。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：报销用于费用或开支，不能与“时间”搭配。"}], "explanations": {"陈述": "正确：“陈述”表示把事情的经过说出来，“司机向警察陈述了车祸发生的时间”符合语境。", "预测": "语义：预测指对未来的推断，车祸已经发生，无法预测其时间。", "推迟": "语义：推迟指把时间往后延，车祸的发生时间已经确定，不能推迟。", "报销": "搭配：报销用于费用或开支，不能与“时间”搭配。"}, "sentence_index": 6, "correct_answer": "陈述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法官向被告陈述了判决书。", "explanation": "这里应该用〈宣读〉。陈述指口头说出事情的经过，宣读文件要用“宣读”。"}, {"text": "学生向校长陈述了打架的经过，却一句话也没说。", "explanation": "“陈述”表示把经过说出来，与“却一句话也没说”相矛盾；这里表达的是不说，应该用〈隐瞒〉。"}, {"text": "学生向校长陈述了那首歌的旋律。", "explanation": "这里应该用〈描述〉。陈述用于经过、理由等说明性内容，描述旋律要用“描述”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把事情的经过陈述很清楚。", "corrected_sentence": "他把事情的经过陈述得很清楚。", "error_description": "“陈述”后引出补语要用“得”，写作“陈述得很清楚”；缺少“得”，语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机向警察陈述着了车祸的经过。", "corrected_sentence": "司机向警察陈述了车祸的经过。", "error_description": "“着”与“了”不能叠加在同一个动词后面；陈述已经完成，应只用“了”，写作“陈述了车祸的经过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74b14b3-f983-4a2a-9e22-5747246df360') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
