INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示为了避免不希望发生的情况。", "primary_collocate": null, "pronunciation": "yǐ miǎn", "ipa": "i˨˩˦ mjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "说话小声一点，以免吵醒孩子。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时不要看手机，以免发生危险。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭时别说话，以免噎着。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天出门要穿暖，以免感冒。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重要的事要写下来，以免忘记。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提前给他打了电话，以免他白跑一趟。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开教室前请关灯，以免浪费电。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说话要想清楚，以免让别人不高兴。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过马路时看看左右，以免发生事故。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把药放在高处，以免小孩子拿到。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "连词，表示为避免不希望的情况（目的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词，表示为了避免不希望发生的情况。"}, {"text": "一面", "is_correct": false, "explanation": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。"}, {"text": "椅面", "is_correct": false, "explanation": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。"}, {"text": "意面", "is_correct": false, "explanation": "意面（yì miàn）两个音节的声调都与 yǐ miǎn 不同，意思是意大利面。"}], "explanations": {"以免": "目标词，表示为了避免不希望发生的情况。", "一面": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。", "椅面": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。", "意面": "意面（yì miàn）两个音节的声调都与 yǐ miǎn 不同，意思是意大利面。"}, "sentence_index": null, "correct_answer": "以免"}, "level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示说话小声是为了避免吵醒孩子。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，“吵醒孩子”不能是小声说话的结果，句意相反。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等配套，这里后面没有主句。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示为达到目的，但吵醒孩子不是说话小声要达到的目的。"}], "explanations": {"以免": "目标词：表示说话小声是为了避免吵醒孩子。", "所以": "语义：“所以”引出结果，“吵醒孩子”不能是小声说话的结果，句意相反。", "虽然": "搭配：“虽然”要与“但是”“却”等配套，这里后面没有主句。", "以便": "语义：“以便”表示为达到目的，但吵醒孩子不是说话小声要达到的目的。"}, "sentence_index": 0, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天练琴，以免学好钢琴。", "explanation": "这里应该用〈为了〉。以免引出要避免的情况，而“学好钢琴”是希望达到的目的。"}, {"text": "老师把答案写在黑板上，以免学生看懂题。", "explanation": "这里应该用〈好让〉。以免表示避免，而“学生看懂题”是希望发生的事。"}, {"text": "我们提前订了票，以免买到票。", "explanation": "这里应该用〈以便〉。以免后接的应是要避免的情况，而“买到票”是希望达到的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示关灯是为了避免浪费电。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，“请关灯”的结果却是“浪费电”，与关灯的目的相反。"}, {"text": "好让", "is_correct": false, "explanation": "语义：“好让”表示为了使某事发生，句子却要使“浪费电”发生，与关灯的目的相反。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”要并列同类内容，“请关灯”与“浪费电”不搭配。"}], "explanations": {"以免": "目标词：表示关灯是为了避免浪费电。", "因此": "语义：“因此”引出结果，“请关灯”的结果却是“浪费电”，与关灯的目的相反。", "好让": "语义：“好让”表示为了使某事发生，句子却要使“浪费电”发生，与关灯的目的相反。", "而且": "搭配：“而且”要并列同类内容，“请关灯”与“浪费电”不搭配。"}, "sentence_index": 6, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们认真备课，以免提高了成绩。", "explanation": "这里应该用〈从而〉。以免表示要避免的情况，而“提高成绩”是希望出现的结果。"}, {"text": "这家店服务很好，以免顾客很满意。", "explanation": "这里应该用〈所以〉。以免后面要接要避免的情况，而“顾客很满意”是希望出现的结果。"}, {"text": "他每天坚持跑步，以免身体变好。", "explanation": "这里应该用〈因而〉。以免表示避免，而“身体变好”是希望达到的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天晚上要盖好被子，以免着凉了。", "corrected_sentence": "秋天晚上要盖好被子，以免着凉。", "error_description": "“以免”后接的是尚未发生、要避免的情况，不能加“了”表示已经完成。正确说法：秋天晚上要盖好被子，以免着凉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "关好窗户，以免免得雨水进来。", "corrected_sentence": "关好窗户，以免雨水进来。", "error_description": "“以免”和“免得”意思相同，不能在同一句中叠用，应只用“以免”。正确说法：关好窗户，以免雨水进来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安定", "is_correct": true, "explanation": "“安定”与“动荡”构成反义，指生活或局势稳定、不变动。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”与“动荡”无反义关系，指心里愉快。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“动荡”无反义关系，指明白、分明。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”与“动荡”无反义关系，指排列有序。"}], "correct_answer": "安定", "explanations": {"安定": "“安定”与“动荡”构成反义，指生活或局势稳定、不变动。", "高兴": "“高兴”与“动荡”无反义关系，指心里愉快。", "清楚": "“清楚”与“动荡”无反义关系，指明白、分明。", "整齐": "“整齐”与“动荡”无反义关系，指排列有序。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稳定", "is_correct": true, "explanation": "“稳定”与“动荡”构成反义，指不变动、安稳。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”与“动荡”无反义关系，指场面繁华、人多声杂。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”与“动荡”无反义关系，指清楚分明。"}, {"text": "笔直", "is_correct": false, "explanation": "“笔直”与“动荡”无反义关系，指不弯曲。"}], "correct_answer": "稳定", "explanations": {"稳定": "“稳定”与“动荡”构成反义，指不变动、安稳。", "热闹": "“热闹”与“动荡”无反义关系，指场面繁华、人多声杂。", "清晰": "“清晰”与“动荡”无反义关系，指清楚分明。", "笔直": "“笔直”与“动荡”无反义关系，指不弯曲。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一会儿这样，一会儿那样，不安定。", "primary_collocate": null, "pronunciation": "dòng dàng", "ipa": "tʊŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的生活很动荡，一会儿在北京，一会儿在上海。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年我换了好几份工作，生活很动荡。", "target_word": "动荡", "complexity_tier": "T3", "furigana": "dòng dàng", "sentence_source": "generated"}, {"text": "海面动荡，船摇得很厉害。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活很动荡，搬了好几次家，很难好好睡觉。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的心情动荡，一会儿笑，一会儿哭。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动荡的生活让孩子很不安。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过着动荡的日子，没有一个家。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常搬家，生活太动荡了，我想安定下来。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水动荡，小船在水上晃来晃去。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时过得很动荡，现在才安静下来。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动荡不安", "label": "复合"}], "register": "中性", "sense_fingerprint": "变来变去、不安定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2788c192-8f6e-4f9a-8a24-ddfd2d5e5bc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指生活不安定、一会儿这样一会儿那样，与“一会儿在北京，一会儿在上海”相符。"}, {"text": "稳定", "is_correct": false, "explanation": "语义：“稳定”指不变动，与“一会儿在北京，一会儿在上海”矛盾。"}, {"text": "规律", "is_correct": false, "explanation": "语义：“规律”指有常规、不乱变，与一会儿换城市的说法矛盾。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”多用于物体不动，不用来形容人的生活。"}], "explanations": {"动荡": "正确：动荡指生活不安定、一会儿这样一会儿那样，与“一会儿在北京，一会儿在上海”相符。", "稳定": "语义：“稳定”指不变动，与“一会儿在北京，一会儿在上海”矛盾。", "规律": "语义：“规律”指有常规、不乱变，与一会儿换城市的说法矛盾。", "静止": "搭配：“静止”多用于物体不动，不用来形容人的生活。"}, "sentence_index": 0, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几十年来，这个地区一直很动荡，人们过得很辛苦。", "explanation": "这里的「动荡」指社会、局势不稳定，属于另一义项；本题要的是生活或心情变来变去的义项。"}, {"text": "房间很动荡，我找不到钥匙。", "explanation": "这里应该用〈乱〉。动荡形容生活或局势不安定、变来变去，形容房间杂乱要用乱。"}, {"text": "这个城市的局势很动荡，学校常常停课。", "explanation": "这里的「动荡」指社会局势不稳定，属于另一义项，不是生活或心情变来变去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡修饰“日子”，指生活不安定，与“没有一个家”相符。"}, {"text": "安定", "is_correct": false, "explanation": "语义：“安定”指生活平稳、有固定居所，与“没有一个家”矛盾。"}, {"text": "美满", "is_correct": false, "explanation": "语义：「美满」指生活圆满、家庭幸福，与「没有一个家」矛盾。"}, {"text": "温馨", "is_correct": false, "explanation": "语义：“温馨”指家庭的温暖氛围，与“没有一个家”矛盾。"}], "explanations": {"动荡": "正确：动荡修饰“日子”，指生活不安定，与“没有一个家”相符。", "安定": "语义：“安定”指生活平稳、有固定居所，与“没有一个家”矛盾。", "美满": "语义：「美满」指生活圆满、家庭幸福，与「没有一个家」矛盾。", "温馨": "语义：“温馨”指家庭的温暖氛围，与“没有一个家”矛盾。"}, "sentence_index": 6, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里很动荡，老师说话都听不清。", "explanation": "这里应该用〈嘈杂〉。动荡指生活、局势、心情不安定，教室里声音吵闹要用嘈杂。"}, {"text": "妈妈把厨房收拾得很动荡。", "explanation": "这里应该用〈干净〉。动荡不用于形容整洁，厨房收拾得整齐干净要用干净。"}, {"text": "这块蛋糕很动荡，孩子们都爱吃。", "explanation": "这里应该用〈甜〉。动荡形容生活、局势、心情不安定，食物的味道要用甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那段时间他的工作很动荡地，老是换单位。", "corrected_sentence": "那段时间他的工作很动荡，老是换单位。", "error_description": "“动荡”作谓语时后面不加“地”，「很动荡地」错误，应为「很动荡」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他童年过着动荡地日子，常常转学。", "corrected_sentence": "他童年过着动荡的日子，常常转学。", "error_description": "“动荡”修饰名词“日子”，应用“的”，不用“地”（“地”多用于动词前）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
