INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "社会、局势不稳定，变化不定。", "primary_collocate": null, "pronunciation": "dòng dàng", "ipa": "tʊŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那个国家的局势很动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动荡的年代里，人们过得很辛苦。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年市场很动荡，生意不好做。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个地方变得动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会动荡时，很多人想离开家。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在一个动荡的时代。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说那里的局势越来越动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济动荡，很多工厂关门了。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城市曾经很动荡，现在安全多了。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动荡的局面让商人不敢投资。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动荡不安", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会或局势不稳定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2788c192-8f6e-4f9a-8a24-ddfd2d5e5bc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指社会或局势不稳定，与“那个国家的局势”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或街市，不用来形容局势。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容局势。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情愉快，与局势不稳定的意思矛盾。"}], "explanations": {"动荡": "正确：动荡指社会或局势不稳定，与“那个国家的局势”相符。", "热闹": "搭配：“热闹”形容场面或街市，不用来形容局势。", "清脆": "搭配：“清脆”形容声音，不能用来形容局势。", "甜蜜": "语义：“甜蜜”指感情愉快，与局势不稳定的意思矛盾。"}, "sentence_index": 0, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的颜色很动荡。", "explanation": "这里应该用〈鲜艳〉。动荡指社会、局势不稳定，花朵颜色明亮要用鲜艳。"}, {"text": "这座桥的结构动荡，车不能过。", "explanation": "这里应该用〈不稳定〉。动荡多用于社会、局势、生活，桥梁结构的稳固程度要用不稳定。"}, {"text": "书架上的东西很动荡，找不到书。", "explanation": "这里应该用〈杂乱〉。动荡不用于摆放的东西，东西摆放无序要用杂乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指社会局势不稳定，与“新闻说那里的局势越来越”相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容场所或时节，不用来形容局势。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”指味道刺激，与局势无关。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指快乐，与“越来越”形容的局势变化矛盾。"}], "explanations": {"动荡": "正确：动荡指社会局势不稳定，与“新闻说那里的局势越来越”相符。", "冷清": "搭配：“冷清”多形容场所或时节，不用来形容局势。", "辛辣": "语义：“辛辣”指味道刺激，与局势无关。", "欢乐": "语义：“欢乐”指快乐，与“越来越”形容的局势变化矛盾。"}, "sentence_index": 6, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很动荡，店员说只要三十块。", "explanation": "这里应该用〈便宜〉。动荡指社会、局势不稳定，价格低要用便宜。"}, {"text": "这个问题很动荡，老师讲了半天也没人懂。", "explanation": "这里应该用〈清楚〉。动荡指不安定、变来变去，道理明白要用清楚。"}, {"text": "图书馆里很动荡，同学们都在看书。", "explanation": "这里应该用〈安静〉。动荡指社会、局势不稳，环境清静无声要用安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个地区的局势很动荡地，很多人都搬走了。", "corrected_sentence": "那个地区的局势很动荡，很多人都搬走了。", "error_description": "“动荡”作谓语时后面不加“地”，「很动荡地」错误，应为「很动荡」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那是一个动荡地年代，人们都很辛苦。", "corrected_sentence": "那是一个动荡的年代，人们都很辛苦。", "error_description": "“动荡”修饰名词“年代”，应用“的”，不用“地”（“地”多用于动词前）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
