INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参看；请读者再去看文中另一处相关内容。", "primary_collocate": null, "pronunciation": "cān jiàn", "ipa": "tsʰan˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题在前面讲过，参见第三章。", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这位作者的生活，参见本书第一章。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据的来源，参见文章后面的表三。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前一段已经说明了原因，参见上文。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词的意思，参见下一页的小字。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于唐朝的历史，参见第七章的详细介绍。", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告中提到的方法，参见附件二。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文章里写着：“原因复杂，参见下文。”", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编者在这一条的后面注明：参见“中国历史”一条。", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图的符号很多，意思参见书前的说明。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "參見", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "参看文中另一处相关内容（互见）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参见", "is_correct": true, "explanation": "正确：“参见”表示请读者去文中另一处查看相关内容，这里指向第三章。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”用于搬运实物，章节不能被搬。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、器皿，不能说“洗第三章”。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”指随意游览某个地方，章节不是可以逛的场所。"}], "explanations": {"参见": "正确：“参见”表示请读者去文中另一处查看相关内容，这里指向第三章。", "搬": "语义：“搬”用于搬运实物，章节不能被搬。", "洗": "搭配：“洗”的对象是衣物、器皿，不能说“洗第三章”。", "逛": "语义：“逛”指随意游览某个地方，章节不是可以逛的场所。"}, "sentence_index": 0, "correct_answer": "参见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个方案要参见一下。", "explanation": "这里应该用〈比较〉。“参见”是请读者查看文中别处，比较两个方案要用〈比较〉。"}, {"text": "我在网上参见了很多新闻。", "explanation": "这里应该用〈浏览〉。“参见”指请读者去看文中另一处，在网上快速看新闻要用〈浏览〉。"}, {"text": "请把两份文件参见一下。", "explanation": "这里应该用〈对照〉。“参见”不用于比对两份文件，比对要用〈对照〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参见", "is_correct": true, "explanation": "正确：“参见”指请读者去查看附件，这里表示方法请见附件二。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”用于歌曲、戏曲，不能说“唱附件二”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等，附件是文件，不能说“擦附件二”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，不能说“喝附件二”。"}], "explanations": {"参见": "正确：“参见”指请读者去查看附件，这里表示方法请见附件二。", "唱": "语义：“唱”用于歌曲、戏曲，不能说“唱附件二”。", "擦": "搭配：“擦”的对象是桌面、玻璃等，附件是文件，不能说“擦附件二”。", "喝": "语义：“喝”的对象是液体，不能说“喝附件二”。"}, "sentence_index": 6, "correct_answer": "参见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都参见晨会。", "explanation": "这里应该用〈参加〉。“参见”指请读者去看文中别处，不表示参与活动，每天参加晨会要用〈参加〉。"}, {"text": "学生们去参见了优秀教师的课。", "explanation": "这里应该用〈观摩〉。“参见”不指到现场观看学习，观摩教学要用〈观摩〉。"}, {"text": "他们去参见了工厂。", "explanation": "这里应该用〈参观〉。“参见”不用于到场参观地点，去工厂参观要用〈参观〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想看具体数据，请参见到附录二。", "corrected_sentence": "想看具体数据，请参见附录二。", "error_description": "“参见”是请读者去查看别处内容的动词，后面不能再加结果补语“到”。应说“请参见附录二”，不说“请参见到附录二”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些数字的意思，请参见了下页的附表。", "corrected_sentence": "这些数字的意思，请参见下页的附表。", "error_description": "“参见”用于请人查阅的祈使句，后面不加“了”。应说“请参见下页的附表”，加“了”与请人查阅的语气不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
