INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在房子最外面、靠近门的那一间。", "primary_collocate": null, "pronunciation": "wài jiān", "ipa": "wai̯˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "一进门就是外间，里面才是卧室。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，先请到外间坐。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外间靠近大门，冬天特别冷。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把鞋柜放在外间，进门很方便。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外间的门开着，风吹进来了。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在外间做饭，我在里面写作业。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子的外间很小，只放得下一张桌子。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在外间脱了外衣，才走进屋里。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外间离大门最近，你在那儿等我吧。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外下着雨，我们在外间站了一会儿。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "外间屋", "label": "复合词"}, {"form": "外間", "label": "繁体"}], "register": "口语", "sense_fingerprint": "房子里最靠近门的那间屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0741d1e3-cd5c-4fae-91d1-65d37b98a78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97209, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：wài jiān，指房子最外面、靠近门的那一间屋。"}, {"text": "外交", "is_correct": false, "explanation": "外交 wài jiāo 与 wài jiān 韵母不同（ao 与 an），意思是国家之间的往来。"}, {"text": "外加", "is_correct": false, "explanation": "外加 wài jiā 与 wài jiān 韵母不同（少了 n），意思是另外再加上。"}, {"text": "外迁", "is_correct": false, "explanation": "外迁 wài qiān 与 wài jiān 声母不同（q 与 j），意思是迁往外地居住。"}], "explanations": {"外间": "外间：wài jiān，指房子最外面、靠近门的那一间屋。", "外交": "外交 wài jiāo 与 wài jiān 韵母不同（ao 与 an），意思是国家之间的往来。", "外加": "外加 wài jiā 与 wài jiān 韵母不同（少了 n），意思是另外再加上。", "外迁": "外迁 wài qiān 与 wài jiān 声母不同（q 与 j），意思是迁往外地居住。"}, "sentence_index": null, "correct_answer": "外间"}, "level_3": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：房子最外面靠近门的房间，与“一进门”和“里面才是卧室”的位置关系相符。"}, {"text": "大门", "is_correct": false, "explanation": "语义：“大门”是出入口，不能说“一进门就是大门”，与“里面才是卧室”矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”不是可以进入的房间，不能说“一进门就是窗户”。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：“卧室”在里面，与“一进门就是”的位置矛盾，句中已说“里面才是卧室”。"}], "explanations": {"外间": "外间：房子最外面靠近门的房间，与“一进门”和“里面才是卧室”的位置关系相符。", "大门": "语义：“大门”是出入口，不能说“一进门就是大门”，与“里面才是卧室”矛盾。", "窗户": "搭配：“窗户”不是可以进入的房间，不能说“一进门就是窗户”。", "卧室": "语义：“卧室”在里面，与“一进门就是”的位置矛盾，句中已说“里面才是卧室”。"}, "sentence_index": 0, "correct_answer": "外间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外间很有礼貌，每次见到我都主动问好。", "explanation": "这里应该用〈他〉。外间是房间，不能作主语做出问好的动作。"}, {"text": "他一口气买下了三座外间。", "explanation": "这里应该用〈套〉或〈幢〉。外间是房间，不能用“座”计量。"}, {"text": "外间的心情很好，一直笑个不停。", "explanation": "这里应该用〈他〉或〈她〉。外间是房间，不能有心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：房子中靠近门的房间，与“这套房子的”和“只放得下一张桌子”相符。"}, {"text": "墙", "is_correct": false, "explanation": "语义：“墙”不是可以放桌子的空间，与“只放得下一张桌子”矛盾。"}, {"text": "楼", "is_correct": false, "explanation": "搭配：“楼”指整栋建筑，不能说“这套房子的楼”指其中一个能放桌子的空间。"}, {"text": "湖", "is_correct": false, "explanation": "语义：“湖”是水域，不能说“这套房子的湖”，与“只放得下一张桌子”矛盾。"}], "explanations": {"外间": "外间：房子中靠近门的房间，与“这套房子的”和“只放得下一张桌子”相符。", "墙": "语义：“墙”不是可以放桌子的空间，与“只放得下一张桌子”矛盾。", "楼": "搭配：“楼”指整栋建筑，不能说“这套房子的楼”指其中一个能放桌子的空间。", "湖": "语义：“湖”是水域，不能说“这套房子的湖”，与“只放得下一张桌子”矛盾。"}, "sentence_index": 6, "correct_answer": "外间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位老师的外间很高，学生们都很敬佩他。", "explanation": "这里应该用〈个子〉。外间是房间，不能形容人的身高。"}, {"text": "这只杯子的外间画着花，很好看。", "explanation": "这里应该用〈外壁〉或〈表面〉。外间指房间，不能指杯子的外壁。"}, {"text": "他的外间很红，像刚喝过酒一样。", "explanation": "这里应该用〈脸〉。外间是房间，不能形容人的脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在桌子上外间写作业。", "corrected_sentence": "妹妹在外间写作业。", "error_description": "错误：处所词语序错误，“在桌子上外间写作业”应为“在外间写作业”。“桌子上”多余，且插在介词“在”与处所词“外间”之间，“外间”应紧跟“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们外间挂好了雨衣，再进屋。", "corrected_sentence": "我们在外间挂好了雨衣，再进屋。", "error_description": "错误形式：“我们外间挂好了雨衣”；正确形式：“我们在外间挂好了雨衣”。表示地点的“外间”作状语时前面要加介词“在”，漏掉“在”句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
