INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "正对着自家大门的邻居。", "primary_collocate": null, "pronunciation": "duì mén", "ipa": "tweɪ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "对门的王奶奶很热情。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对门是一对年轻夫妻。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和对门关系很好。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门的小孩常来我家玩。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家对门搬来了新邻居。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门的李叔叔送了我一盒水果。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天对门的人帮我拿了快递。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家对门住了五年，我们从没吵过架。", "target_word": "对门", "complexity_tier": "T3", "furigana": "duì mén", "sentence_source": "generated"}, {"text": "对门的老人每天早上都出来散步。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这封信交给对门。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对门儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "正对着自家大门的邻居", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2788c192-8f6e-4f9a-8a24-ddfd2d5e5bc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对门", "is_correct": true, "explanation": "正确：「对门」指正对着自家大门的邻居，与「王奶奶很热情」的语境相符。"}, {"text": "对头", "is_correct": false, "explanation": "语义：「对头」指仇敌，与「王奶奶很热情」不合。"}, {"text": "对方", "is_correct": false, "explanation": "语义：「对方」指对手或对立的一方，与邻居的意思不符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：「对手」指竞争者，不能指住在对门的王奶奶。"}], "explanations": {"对门": "正确：「对门」指正对着自家大门的邻居，与「王奶奶很热情」的语境相符。", "对头": "语义：「对头」指仇敌，与「王奶奶很热情」不合。", "对方": "语义：「对方」指对手或对立的一方，与邻居的意思不符。", "对手": "语义：「对手」指竞争者，不能指住在对门的王奶奶。"}, "sentence_index": 0, "correct_answer": "对门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次谈判，我们对门了很多条件。", "explanation": "这里应该用〈提出〉。「对门」是名词，不能当动词用。"}, {"text": "我们常在对门的公园见面。", "explanation": "「对门」指邻居人家，不能指公园这类场所。"}, {"text": "这次比赛，我们对门了三个球。", "explanation": "这里应该用〈进〉。「对门」是名词，不能当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对门", "is_correct": true, "explanation": "正确：「对门的人帮我拿了快递」指住在对门的邻居，符合语境。"}, {"text": "对策", "is_correct": false, "explanation": "语义：「对策」指应对问题的办法，不指人，与帮忙拿快递不合。"}, {"text": "对比", "is_correct": false, "explanation": "语义：「对比」指比较，不指人，与帮忙拿快递不合。"}, {"text": "对台", "is_correct": false, "explanation": "搭配：「对台」指舞台的对面，不能用来指住在对门的人。"}], "explanations": {"对门": "正确：「对门的人帮我拿了快递」指住在对门的邻居，符合语境。", "对策": "语义：「对策」指应对问题的办法，不指人，与帮忙拿快递不合。", "对比": "语义：「对比」指比较，不指人，与帮忙拿快递不合。", "对台": "搭配：「对台」指舞台的对面，不能用来指住在对门的人。"}, "sentence_index": 6, "correct_answer": "对门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "打麻将时，他对门了一张牌。", "explanation": "这里应该用〈打〉。「对门」是名词，不能当动词用。"}, {"text": "对门这件事，我们要认真考虑。", "explanation": "这里应该用「对于」。「对门」指邻居，不能用来引出话题。"}, {"text": "他每天在对门的学校上学。", "explanation": "「对门」指邻居，不能指学校这类场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对门了的阿姨每天很早出门。", "corrected_sentence": "对门的阿姨每天很早出门。", "error_description": "“对门”是名词，后面不能直接加“了”，“对门了的阿姨”应改为“对门的阿姨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家对门住了着一位老人。", "corrected_sentence": "他家对门住着一位老人。", "error_description": "「住着」已表示持续，后面不能再加「了」，「住了着」不成立，应为「住着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
