INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古时候皇帝身边管事的大官。", "primary_collocate": null, "pronunciation": "shàng shū", "ipa": "ʂaŋ˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "古时候，尚书是皇帝身边管事的大官。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "戏里的尚书穿着红色的官服，站在皇帝旁边。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位尚书很有学问，皇帝有事总是先问他。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的尚书正直又聪明，帮皇帝解决了难题。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尚书走进大殿，向皇帝报告今天的大事。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爷爷年轻时在宫里做过尚书，常陪在皇帝身边，家里人都很骄傲。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个尚书一生为皇帝管事，从不收别人的钱。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里写到，皇帝把尚书叫到身边商量大事。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，尚书在古代是地位很高的大官。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位尚书每天陪在皇帝身边，帮他管理国家大事。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尚書", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "古时皇帝身边管事的大官（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚书", "is_correct": true, "explanation": "正确：“尚书”指古时皇帝身边管事的大官。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不是管事的大官。"}, {"text": "马车", "is_correct": false, "explanation": "语义：“马车”是交通工具，不能是管事的大官。"}, {"text": "宝座", "is_correct": false, "explanation": "搭配：“宝座”是物品，不能与指人的“大官”搭配。"}], "explanations": {"尚书": "正确：“尚书”指古时皇帝身边管事的大官。", "厨师": "语义：厨师负责做饭，不是管事的大官。", "马车": "语义：“马车”是交通工具，不能是管事的大官。", "宝座": "搭配：“宝座”是物品，不能与指人的“大官”搭配。"}, "sentence_index": 0, "correct_answer": "尚书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是尚书，每天为皇帝准备饭菜，很用心。", "explanation": "这里应该用〈御厨〉。“尚书”是管事的大官，为皇帝做饭要用〈御厨〉。"}, {"text": "他是尚书，站在皇帝身边，负责保护他的安全。", "explanation": "这里应该用〈侍卫〉。“尚书”是管事的大官，负责贴身保护皇帝的安全要用〈侍卫〉。"}, {"text": "他是尚书，每天在殿上为皇帝奏乐。", "explanation": "这里应该用〈乐师〉。“尚书”是管事的大官，在殿上为皇帝奏乐要用〈乐师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚书", "is_correct": true, "explanation": "正确：“尚书”指古时皇帝身边管事的大官，那个大官一生为皇帝管事、从不收钱。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是摆设，不能为皇帝管事。"}, {"text": "柴火", "is_correct": false, "explanation": "语义：“柴火”是燃料，不能为皇帝管事。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“大门”是建筑物，不能主语一生为皇帝管事、从不收钱。"}], "explanations": {"尚书": "正确：“尚书”指古时皇帝身边管事的大官，那个大官一生为皇帝管事、从不收钱。", "花瓶": "语义：“花瓶”是摆设，不能为皇帝管事。", "柴火": "语义：“柴火”是燃料，不能为皇帝管事。", "大门": "搭配：“大门”是建筑物，不能主语一生为皇帝管事、从不收钱。"}, "sentence_index": 6, "correct_answer": "尚书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是尚书，每天负责喂马、洗刷，很辛苦。", "explanation": "这里应该用〈马夫〉。“尚书”是管事的大官，负责喂马、洗刷的杂役要用〈马夫〉。"}, {"text": "他是尚书，每天在花园里修剪花草，很细心。", "explanation": "这里应该用〈花匠〉。“尚书”是管事的大官，修剪花草要用〈花匠〉。"}, {"text": "他是尚书，每天为皇帝画像，画得很像。", "explanation": "这里应该用〈画师〉。“尚书”是管事的大官，为皇帝画像要用〈画师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的爷爷以前做过一只尚书，地位很高。", "corrected_sentence": "他的爷爷以前做过一位尚书，地位很高。", "error_description": "“尚书”指人，量词应用“位”，不能用指动物的“只”。应说“做过一位尚书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皇帝尚书召进大殿问话。", "corrected_sentence": "皇帝把尚书召进大殿问话。", "error_description": "“把”字句漏了“把”。应说“皇帝把尚书召进大殿”；直接说“皇帝尚书召进大殿”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
