INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力打，把人或动物打死。", "primary_collocate": null, "pronunciation": "dǎ shā", "ipa": "ta²¹⁴ ʂa⁵⁵", "syllable_count": 2, "sentences": [{"text": "他用棍子打杀了一条蛇。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农夫打杀了偷鸡的黄鼠狼。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎来了，大家一起把它打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条疯狗咬了人，村民把它打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一棍子打杀了那只老鼠。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人打杀过一头野猪。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用石头打杀小鸟。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗闯进村里，村民打杀了两个强盗。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人打杀了一只狼。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗太凶，主人也没有打杀它。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打杀了", "label": "体标"}, {"form": "打杀过", "label": "体标"}, {"form": "打殺", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用力打，把人或动物打死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打，把人或动物打死。"}, {"text": "打伤", "is_correct": false, "explanation": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。"}, {"text": "大厦", "is_correct": false, "explanation": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。"}, {"text": "打傻", "is_correct": false, "explanation": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}], "explanations": {"打杀": "目标词：用力打，把人或动物打死。", "打伤": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。", "大厦": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。", "打傻": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}, "sentence_index": null, "correct_answer": "打杀"}, "level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打死动物，符合“用棍子打杀了一条蛇”的情节。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指养育动物，与“用棍子”的动作不合，句子意思不通。"}, {"text": "抚摸", "is_correct": false, "explanation": "搭配：“抚摸”要用手，不能用棍子，搭配不当。"}, {"text": "救活", "is_correct": false, "explanation": "语义：“救活”是使其存活，与“打”的动作相反。"}], "explanations": {"打杀": "目标词：用力打死动物，符合“用棍子打杀了一条蛇”的情节。", "饲养": "语义：“饲养”指养育动物，与“用棍子”的动作不合，句子意思不通。", "抚摸": "搭配：“抚摸”要用手，不能用棍子，搭配不当。", "救活": "语义：“救活”是使其存活，与“打”的动作相反。"}, "sentence_index": 0, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兽医打杀了那只受伤的狗。", "explanation": "这里应该用〈救治〉。兽医救治动物，而打杀是用力打死，两者意思相反。"}, {"text": "他用棍子打杀了那条狗，那条狗却还在院子里跑。", "explanation": "这里应该用〈打伤〉。打杀指打死，而句子说狗还在院子里跑，前后矛盾。"}, {"text": "村民用石头打杀了那群狼，狼群却全都逃走了。", "explanation": "这里应该用〈击退〉。打杀指打死，而句子说狼群全都逃走，并未死去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打死动物，符合“别用石头打杀小鸟”的语境。"}, {"text": "放生", "is_correct": false, "explanation": "语义：“放生”是放走动物使其活命，与“用石头”的动作相反。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：“驯养”多指养成家畜或宠物，与“用石头”的动作不搭配。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，与“用石头打”的动作相反。"}], "explanations": {"打杀": "目标词：用力打死动物，符合“别用石头打杀小鸟”的语境。", "放生": "语义：“放生”是放走动物使其活命，与“用石头”的动作相反。", "驯养": "搭配：“驯养”多指养成家畜或宠物，与“用石头”的动作不搭配。", "保护": "语义：“保护”是护卫，与“用石头打”的动作相反。"}, "sentence_index": 6, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这匹野马很烈，打杀后就能骑了。", "explanation": "这里应该用〈驯服〉。打杀指打死，马被打死后就无法骑了。"}, {"text": "猫受了惊，主人轻声打杀它。", "explanation": "这里应该用〈安抚〉。打杀要用力打死，与“轻声”的动作相矛盾。"}, {"text": "农民每天打杀那几只狗，让它们听话。", "explanation": "这里应该用〈驯养〉。打杀指用力打死，被打死的狗无法再听话，与“让它们听话”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农夫用棍子把那只狐狸打杀死了。", "corrected_sentence": "农夫用棍子把那只狐狸打杀了。", "error_description": "“打杀”本身已含“打死”之义，后面再加“死”属于重复补语。正确说法：农夫用棍子把那只狐狸打杀了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老鼠偷吃粮食，村民正在把它打杀过。", "corrected_sentence": "老鼠偷吃粮食，村民正在把它打杀。", "error_description": "“过”表示已经发生过的经历，与表示进行中的“正在”矛盾。正确说法：村民正在把它打杀。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
