INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "殴打致死；多见于方言和旧小说。", "primary_collocate": null, "pronunciation": "dǎ shā", "ipa": "ta²¹⁴ ʂa⁵⁵", "syllable_count": 2, "sentences": [{"text": "那个恶霸把长工打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕自己一生气，会失手打杀了人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里写他一怒之下打杀了仇人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，当年有人在村口打杀了一个小偷。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了酒，差点打杀了邻居。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官府说，是他打杀了那个商人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的恶霸打杀过好几个人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打杀了人，只好连夜逃走。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都说是王二打杀了他的哥哥。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥一时失手，打杀了那个欺负人的恶棍。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打杀了", "label": "体标"}, {"form": "打杀过", "label": "体标"}, {"form": "打殺", "label": "繁体"}], "register": "方言", "sense_fingerprint": "殴打致死，方言或旧小说用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：殴打致死，多见于方言和旧小说。"}, {"text": "打伤", "is_correct": false, "explanation": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。"}, {"text": "大厦", "is_correct": false, "explanation": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。"}, {"text": "打傻", "is_correct": false, "explanation": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}], "explanations": {"打杀": "目标词：殴打致死，多见于方言和旧小说。", "打伤": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。", "大厦": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。", "打傻": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}, "sentence_index": null, "correct_answer": "打杀"}, "level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：殴打致死，符合恶霸杀害长工的情节。"}, {"text": "善待", "is_correct": false, "explanation": "语义：“善待”是好好对待，与“恶霸”的身份和“打杀了”的情节矛盾。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，与恶霸欺压长工的情节不合。"}, {"text": "体谅", "is_correct": false, "explanation": "搭配：“体谅”多用于理解对方的难处，与“恶霸”的身份不搭配。"}], "explanations": {"打杀": "目标词：殴打致死，符合恶霸杀害长工的情节。", "善待": "语义：“善待”是好好对待，与“恶霸”的身份和“打杀了”的情节矛盾。", "尊敬": "语义：“尊敬”表示敬重，与恶霸欺压长工的情节不合。", "体谅": "搭配：“体谅”多用于理解对方的难处，与“恶霸”的身份不搭配。"}, "sentence_index": 0, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被对方打杀后，第二天还照常去上班。", "explanation": "这里应该用〈殴打〉。打杀指殴打致死，而句子说他第二天还照常上班，两者矛盾，应用〈殴打〉。"}, {"text": "他把小偷打杀后送去了医院。", "explanation": "这里应该用〈打伤〉。打杀指打死，而句子说被送去了医院，人还活着。"}, {"text": "几个孩子在院子里打杀同伴，玩得很开心。", "explanation": "这里应该用〈打闹〉。打杀指殴打致死，把“打杀同伴”用来形容玩耍，与“玩得很开心”矛盾，应用〈打闹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：“过”表示经历，指恶霸曾经殴打致死好几个人。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与恶霸的凶狠形象不符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与恶霸杀人的情节相反。"}, {"text": "疼爱", "is_correct": false, "explanation": "搭配：“疼爱”多用于对亲近的人，用于“恶霸”搭配不当。"}], "explanations": {"打杀": "目标词：“过”表示经历，指恶霸曾经殴打致死好几个人。", "感谢": "语义：“感谢”表示感激，与恶霸的凶狠形象不符。", "赞美": "语义：“赞美”表示称赞，与恶霸杀人的情节相反。", "疼爱": "搭配：“疼爱”多用于对亲近的人，用于“恶霸”搭配不当。"}, "sentence_index": 6, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在巷子里打杀了那个小偷，直到他认错。", "explanation": "这里应该用〈教训〉。打杀指殴打致死，而句子说“直到他认错”，死人不能认错，前后矛盾，应用〈教训〉。"}, {"text": "他被对方一拳打杀，过了一会儿就醒了。", "explanation": "这里应该用〈打晕〉。打杀意味着致死，而句子说“过了一会儿就醒了”，前后矛盾。"}, {"text": "小男孩调皮，被大孩子打杀得鼻青脸肿。", "explanation": "这里应该用〈揍〉。打杀指殴打致死，而句子说“鼻青脸肿”，人仍然活着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个恶霸没把长工打杀了。", "corrected_sentence": "那个恶霸没把长工打杀。", "error_description": "“没”表示否定时，“打杀”后不加“了”。正确说法：那个恶霸没把长工打杀。加“了”与否定相矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那伙强盗抢了粮食，村民把他们打杀死了。", "corrected_sentence": "那伙强盗抢了粮食，村民把他们打杀了。", "error_description": "“打杀”本身已含“打死”之义，后面不必再加“死”，属于重复补语。正确说法：村民把他们打杀了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
