INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数中每个数码所占的位置，如个位、十位、百位。", "primary_collocate": null, "pronunciation": "shù wèi", "ipa": "ʂu˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "一万有五个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数位从右往左，先是个位，再是十位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过了数位，知道百位在十位的左边。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明算的时候漏掉了一个数位，答案也错了。", "target_word": "数位", "complexity_tier": "T3", "furigana": "xiǎo míng suàn de shí hou lòu diào le yī gè shù wèi， dá àn yě cuò le。", "sentence_source": "generated"}, {"text": "计算时，数位要对齐。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九百八十七有三个数位，各数位上的数字都不同。", "target_word": "数位", "complexity_tier": "T3", "furigana": "jiǔ bǎi bā shí qī yǒu sān gè shù wèi， gè shù wèi shàng de shù zì dōu bù tóng。", "sentence_source": "generated"}, {"text": "这道题要说出这个数的最高数位。", "target_word": "数位", "complexity_tier": "T3", "furigana": "zhè dào tí yào shuō chū zhè gè shù de zuì gāo shù wèi。", "sentence_source": "generated"}, {"text": "从数位来看，十位在个位的左边。", "target_word": "数位", "complexity_tier": "T3", "furigana": "cóng shù wèi lái kàn， shí wèi zài gè wèi de zuǒ biān。", "sentence_source": "generated"}, {"text": "老师教我们怎么读每个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多了一个数位，这个数就大了很多。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数位", "label": "量词"}], "register": "中性", "sense_fingerprint": "数学中一个数里每个数码所占的位置，决定它的数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2788c192-8f6e-4f9a-8a24-ddfd2d5e5bc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：数中每一个数码所占的位置，一万有五位。"}, {"text": "数轴", "is_correct": false, "explanation": "语义：数轴是画出来的直线，用来表示数的大小，不能数“五个”。"}, {"text": "数列", "is_correct": false, "explanation": "语义：数列是按顺序排列的一串数，一万不能有五个数列。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”不用“个”计数，不能说“五个数量”。"}], "explanations": {"数位": "数位：数中每一个数码所占的位置，一万有五位。", "数轴": "语义：数轴是画出来的直线，用来表示数的大小，不能数“五个”。", "数列": "语义：数列是按顺序排列的一串数，一万不能有五个数列。", "数量": "搭配：“数量”不用“个”计数，不能说“五个数量”。"}, "sentence_index": 0, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中的数位很靠前。", "explanation": "这里应该用〈名次〉。“数位”指数中某一位的位置，不指比赛中的排名。"}, {"text": "这张地图标出了每个城市的数位。", "explanation": "这里应该用〈位置〉。“数位”只指数字中每一位的位置，不指城市的地点。"}, {"text": "这个数的数位是四。", "explanation": "这里应该用〈位数〉。“位数”指数有几位，“数位”指某一位的位置，不能说“是四”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：数中每一个数码所占的位置，最高的那一位就是最高数位。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“最高”不修饰学科名称，不能说“最高数学”。"}, {"text": "数据", "is_correct": false, "explanation": "语义：数据指一组用于分析的资料，不是数中的某一位。"}, {"text": "数论", "is_correct": false, "explanation": "语义：数论是数学的一个分支，不指数字中的位置。"}], "explanations": {"数位": "数位：数中每一个数码所占的位置，最高的那一位就是最高数位。", "数学": "搭配：“最高”不修饰学科名称，不能说“最高数学”。", "数据": "语义：数据指一组用于分析的资料，不是数中的某一位。", "数论": "语义：数论是数学的一个分支，不指数字中的位置。"}, "sentence_index": 6, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一万的数位很大，比一千还大。", "explanation": "这里应该用〈数值〉。“数值”指数的大小，“数位”指数中每一位的位置，不能说“很大”。"}, {"text": "黑板上写着一个数位，是他的名字。", "explanation": "这里应该用〈名字〉。“数位”指数中某一位的位置，不指人的名字。"}, {"text": "那个数的数位很重要，是最关键的一个。", "explanation": "这里应该用〈地位〉。“地位”指在某个范围中的重要程度，“数位”指数中某一位的位置，不能说“很重要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数的每只数位上都有数字。", "corrected_sentence": "这个数的每个数位上都有数字。", "error_description": "量词错误：“每”后面的“数位”应用“个”计量，“只”用于动物，应改为“每个数位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "计算时要把数位对。", "corrected_sentence": "计算时要把数位对齐。", "error_description": "补语缺失：“把”字句中动词后需要补语，“把数位对”不完整，应说“把数位对齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
