INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不便；不宜（多用于书面语）。", "primary_collocate": null, "pronunciation": "wèi biàn", "ipa": "wei˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此事关系重大，现在未便公布。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "案子还在调查，记者未便透露细节。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本公司未便对外说明具体原因。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因涉及个人资料，我方未便提供。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方还没签字，未便提前宣布结果。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身份特殊，我们未便公开姓名。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情尚未查清，请恕我未便回答。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议内容保密，工作人员未便外传。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人情况不稳定，医生未便让家属探视。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公告里说，部分细节未便详述。", "target_word": "未便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "未便：公文、公告中表示不宜做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示不宜、不便，与“关系重大”而需审慎的语境相合。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”含冒进、不顾后果之意，与“关系重大”而需审慎的语境相抵触。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示情愿，与“关系重大”而需慎重处理的语境不合。"}, {"text": "得", "is_correct": false, "explanation": "语域：“得”是口语说法，与书面的“未便”语域不合，且表示需要，与审慎的语境相悖。"}], "explanations": {"未便": "正确：“未便”表示不宜、不便，与“关系重大”而需审慎的语境相合。", "敢": "语义：“敢”含冒进、不顾后果之意，与“关系重大”而需审慎的语境相抵触。", "肯": "语义：“肯”表示情愿，与“关系重大”而需慎重处理的语境不合。", "得": "语域：“得”是口语说法，与书面的“未便”语域不合，且表示需要，与审慎的语境相悖。"}, "sentence_index": 0, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章太难，我未便读懂。", "explanation": "这里应该用〈读不懂〉。未便指碍于情面或处境而不便做，不指能力不足。"}, {"text": "这个办法很好，你未便先试试。", "explanation": "这里应该用〈不妨〉，表示可以这样做、建议对方先试。未便指不便、不宜，语气恰好相反。"}, {"text": "他一见老板就紧张，未便开口。", "explanation": "这里应该用〈不敢〉。未便指碍于情面或处境而不宜做，不表示心里害怕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未便", "is_correct": true, "explanation": "正确：“未便”表示不宜、不便，与“事情尚未查清”而请人谅解的语境相合。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示许可，与“事情尚未查清”而需谨慎的语境直接矛盾。"}, {"text": "该", "is_correct": false, "explanation": "语域：“该”是口语简省形式，与书面的“未便”不合；且表示应当，与“尚未查清”相矛盾。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要，与“请恕我”的谦让语气及“尚未查清”的语境相抵触。"}], "explanations": {"未便": "正确：“未便”表示不宜、不便，与“事情尚未查清”而请人谅解的语境相合。", "可以": "语义：“可以”表示许可，与“事情尚未查清”而需谨慎的语境直接矛盾。", "该": "语域：“该”是口语简省形式，与书面的“未便”不合；且表示应当，与“尚未查清”相矛盾。", "必须": "语义：“必须”表示必要，与“请恕我”的谦让语气及“尚未查清”的语境相抵触。"}, "sentence_index": 6, "correct_answer": "未便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个字太难写，我未便写出来。", "explanation": "这里应该用〈写不出来〉。未便指碍于情面或处境而不便做某事，不用来表示能力不够。"}, {"text": "这份工作我不想做，未便接下。", "explanation": "这里应该用〈不愿意〉。未便指客观上不便或不宜，不表示个人不愿意。"}, {"text": "这盘菜太辣，我未便吃。", "explanation": "这里应该用〈不爱吃〉。未便指不宜、不便，不表示个人口味上不喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此事我们未便了公开细节。", "corrected_sentence": "此事我们未便公开细节。", "error_description": "词语误加：情态动词“未便”后不能直接加“了”，应说“未便公开细节”，不能说“未便了公开细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议资料我们不未便外传。", "corrected_sentence": "会议资料我们未便外传。", "error_description": "词语误加：“未便”本身已含否定，不能再加“不”，应说“未便外传”，不能说“不未便外传”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "明亮", "is_correct": false, "explanation": "与“未知”没有反义关系，只表示光线充足。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写面积大。"}, {"text": "干净", "is_correct": false, "explanation": "与“未知”没有反义关系，只表示没有污物。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "明亮": "与“未知”没有反义关系，只表示光线充足。", "宽阔": "与“未知”没有反义关系，只描写面积大。", "干净": "与“未知”没有反义关系，只表示没有污物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "嘈杂", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写声音杂乱。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写外表好看。"}, {"text": "冰冷", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写温度低。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "嘈杂": "与“未知”没有反义关系，只描写声音杂乱。", "漂亮": "与“未知”没有反义关系，只描写外表好看。", "冰冷": "与“未知”没有反义关系，只描写温度低。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "还不知道，没有人弄明白。", "primary_collocate": null, "pronunciation": "wèi zhī", "ipa": "weɪ̯⁵¹ ʈʂɨ⁵⁵", "syllable_count": 2, "sentences": [{"text": "海底还有很多未知的东西。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的原因目前还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇宙里有许多未知的星星。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的真相至今未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想找到未知的答案。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山洞里有什么，还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，这个问题的答案仍然未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在研究这些未知的现象。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深海里的未知生物让人好奇。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机为什么会失踪，原因到现在还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "还没有人弄明白的，尚不为人所知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。未知（wèi zhī）指还没有人弄明白。"}, {"text": "位置", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。"}, {"text": "未至", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。"}, {"text": "为之", "is_correct": false, "explanation": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。"}, {"text": "位址", "is_correct": false, "explanation": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}], "explanations": {"未知": "正确答案。未知（wèi zhī）指还没有人弄明白。", "位置": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。", "未至": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。", "为之": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。", "位址": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}, "sentence_index": null, "correct_answer": "未知"}, "level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知”修饰“东西”，表示还没有人弄明白的事物。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：海底是潮湿的水下环境，“干燥”与之冲突。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：“沸腾”指液体受热翻滚，不能用来描写海底泛指的“东西”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多用于声音和脆性食物，不用来形容泛指的东西。"}], "explanations": {"未知": "正确答案。“未知”修饰“东西”，表示还没有人弄明白的事物。", "干燥": "语义：海底是潮湿的水下环境，“干燥”与之冲突。", "沸腾": "语义：“沸腾”指液体受热翻滚，不能用来描写海底泛指的“东西”。", "清脆": "搭配：“清脆”多用于声音和脆性食物，不用来形容泛指的东西。"}, "sentence_index": 0, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班转来了一位未知的同学。", "explanation": "这里应该用〈陌生〉。未知指事情还没有人弄明白，不用来指刚转来、只是彼此不熟的同学。"}, {"text": "我对这条路很未知。", "explanation": "这里应该用〈生疏〉。未知说的是事情还没有人弄明白，不用来说自己对某条路不熟悉；这个意思要用“生疏”，如“我对这条路很生疏”。"}, {"text": "他对这份工作很未知，干起来却很顺手。", "explanation": "这里应该用〈熟悉〉。未知指事情还没有人弄明白，不用来说自己对工作很熟悉；“对这份工作很熟悉”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“仍然未知”说答案还没有被弄明白。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”描写质地，不能用来形容“答案”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”只描写物体或环境，不能形容“答案”。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”描写外形或声音，不能说答案“圆润”。"}], "explanations": {"未知": "正确答案。“仍然未知”说答案还没有被弄明白。", "柔软": "语义：“柔软”描写质地，不能用来形容“答案”。", "潮湿": "语义：“潮湿”只描写物体或环境，不能形容“答案”。", "圆润": "体貌：“圆润”描写外形或声音，不能说答案“圆润”。"}, "sentence_index": 6, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然辞职，让大家都很未知。", "explanation": "这里应该用〈意外〉。未知表示事情还没有人弄明白，不能表示事情出乎意料；“大家都很意外”才是这个意思。"}, {"text": "他未知地离开了房间。", "explanation": "这里应该用〈悄悄地〉。未知表示事情还没有人弄明白，不能用来描述离开的方式；“悄悄地离开”才是这个意思。"}, {"text": "这个孩子很未知，每天都爱说爱笑。", "explanation": "这里应该用〈活泼〉。未知表示还没有人弄明白，不用来形容孩子的性格；“很活泼”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个山洞里还有许多未知地角落。", "corrected_sentence": "这个山洞里还有许多未知的角落。", "error_description": "错误形式：“未知地角落”；正确形式：“未知的角落”。“未知”修饰名词时要用“的”；“地”是状语标志，不用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个洞穴的深度至今仍然未知的。", "corrected_sentence": "这个洞穴的深度至今仍然未知。", "error_description": "错误形式：“至今仍然未知的”；正确形式：“至今仍然未知”。作谓语的“仍然未知”句末不加“的”；“的”需要名词中心语，或用在“是……的”结构中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "干燥", "is_correct": false, "explanation": "与“未知”没有反义关系，只说水分少。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写面积大。"}, {"text": "滚烫", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写温度高。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "干燥": "与“未知”没有反义关系，只说水分少。", "宽阔": "与“未知”没有反义关系，只描写面积大。", "滚烫": "与“未知”没有反义关系，只描写温度高。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已知", "is_correct": true, "explanation": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。"}, {"text": "嘈杂", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写声音杂乱。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写外表好看。"}, {"text": "冰冷", "is_correct": false, "explanation": "与“未知”没有反义关系，只描写温度低。"}], "correct_answer": "已知", "explanations": {"已知": "正确答案。“已知”与“未知”是反义词，指已经弄清楚的。", "嘈杂": "与“未知”没有反义关系，只描写声音杂乱。", "漂亮": "与“未知”没有反义关系，只描写外表好看。", "冰冷": "与“未知”没有反义关系，只描写温度低。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不了解；还不知道的。", "primary_collocate": null, "pronunciation": "wèi zhī", "ipa": "weɪ̯⁵¹ ʈʂɨ⁵⁵", "syllable_count": 2, "sentences": [{"text": "对他来说，新城市是未知的地方。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次出国，一切都是未知的。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕未知的困难。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对未知的路，她有点紧张。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对未知的东西总是很好奇。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工作怎么样，对我来说还是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要勇敢地走进未知的世界。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，未来对他是未知的。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去一个未知的国家旅行，让她很兴奋。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩，对大家都是未知。", "target_word": "未知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "对某人来说不了解、还不知道的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e8ee6ca-1001-4a78-9120-b2d749ded6bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。未知（wèi zhī）指对某人来说还不了解。"}, {"text": "位置", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。"}, {"text": "未至", "is_correct": false, "explanation": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。"}, {"text": "为之", "is_correct": false, "explanation": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。"}, {"text": "位址", "is_correct": false, "explanation": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}], "explanations": {"未知": "正确答案。未知（wèi zhī）指对某人来说还不了解。", "位置": "wèi 相同，zhì（第四声）与 zhī（第一声）声调不同，意思是位置。", "未至": "wèi 相同，zhì（第四声）与 zhī（第一声）只差声调，意思是还没有到。", "为之": "zhī 相同，wéi（第二声）与 wèi（第四声）只差声调，意思是做、办理。", "位址": "wèi 相同，zhǐ（第三声）与 zhī（第一声）声调不同，意思是地址。"}, "sentence_index": null, "correct_answer": "未知"}, "level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知的地方”指对他来说还不了解的地方。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：“熟悉”与句中的“新城市”相反，新城市对他来说不可能是熟悉的。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”描写质地，不能用来形容一个地方。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多用于声音，不能形容地方。"}], "explanations": {"未知": "正确答案。“未知的地方”指对他来说还不了解的地方。", "熟悉": "语义：“熟悉”与句中的“新城市”相反，新城市对他来说不可能是熟悉的。", "柔软": "语义：“柔软”描写质地，不能用来形容一个地方。", "清脆": "搭配：“清脆”多用于声音，不能形容地方。"}, "sentence_index": 0, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从小在这里长大，对这条街很未知。", "explanation": "这里应该用〈熟悉〉。未知表示不了解，不能用来说在这里长大、对街道很熟悉的情况。"}, {"text": "他的英语很未知，每次说话都要想半天。", "explanation": "这里应该用〈不熟练〉。未知说的是不了解的情况，不用来形容语言水平；说英语不熟练才对。"}, {"text": "听到这个好消息，我心里很未知。", "explanation": "这里应该用〈高兴〉。未知表示还不了解，不能用来形容心情；听到好消息应说“高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未知", "is_correct": true, "explanation": "正确答案。“未知的世界”指还没有人探索过的世界。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”描写道路，与“勇敢地走进”的探索语境不协调。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描写环境，不能用来形容“世界”这样的整体概念。"}, {"text": "圆润", "is_correct": false, "explanation": "体貌：“圆润”描写外形，不能用来形容“世界”。"}], "explanations": {"未知": "正确答案。“未知的世界”指还没有人探索过的世界。", "平坦": "语义：“平坦”描写道路，与“勇敢地走进”的探索语境不协调。", "潮湿": "语义：“潮湿”描写环境，不能用来形容“世界”这样的整体概念。", "圆润": "体貌：“圆润”描写外形，不能用来形容“世界”。"}, "sentence_index": 6, "correct_answer": "未知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父母很未知，我们经常一起吃饭。", "explanation": "这里应该用〈亲近〉。未知表示不了解，不能用来形容与父母的关系；“我和父母很亲近”才是这个意思。"}, {"text": "她未知地摇了摇头。", "explanation": "这里应该用〈轻轻地〉。未知表示不了解，不能用来形容摇头的样子；“轻轻地摇了摇头”才是这个意思。"}, {"text": "我和他是多年的老朋友，对他的脾气很未知。", "explanation": "这里应该用〈熟悉〉。未知表示不了解，老朋友的脾气应该说“熟悉”，不能用“未知”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对我来说，这条山路是未知地。", "corrected_sentence": "对我来说，这条山路是未知的。", "error_description": "错误形式：“是未知地”；正确形式：“是未知的”。“地”是状语标志，不用于句中的表语位置；“是……的”结构中应用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个岛上的秘密，至今仍然未知的。", "corrected_sentence": "那个岛上的秘密，至今仍然未知。", "error_description": "错误形式：“至今仍然未知的”；正确形式：“至今仍然未知”。作谓语的“仍然未知”句末不加“的”；“的”需要名词中心语，或用在“是……的”结构中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcf371d-b6bd-4243-b37c-8be2aaf2a3a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
