INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97325, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和尚或道士为了拜神佛做的活动。", "primary_collocate": null, "pronunciation": "fǎ shì", "ipa": "fa˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "道士们正在庙里做法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座道观今天有法事，不开放。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚做法事时，会敲木鱼。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看到和尚做法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法事要准备香、花和水果。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "道士穿着长衣服，在院子里做法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场法事请了五位和尚。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完法事，和尚们回房休息了。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友好奇地看着道士做法事。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法事开始前，庙里先打扫干净。", "target_word": "法事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场法事", "label": "量词"}], "register": "中性", "sense_fingerprint": "和尚或道士在寺庙道观里为拜神佛而进行的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2788c192-8f6e-4f9a-8a24-ddfd2d5e5bc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事（fǎ shì）：和尚或道士为拜神佛而进行的活动。"}, {"text": "发誓", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是发誓。"}, {"text": "发式", "is_correct": false, "explanation": "fà（第四声）与 fǎ（第三声）声调不同，意思是发式（发型）。"}, {"text": "法术", "is_correct": false, "explanation": "shù 与 shì 韵母不同（u 与 i），意思是法术。"}, {"text": "法制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是法制（法律制度）。"}], "explanations": {"法事": "法事（fǎ shì）：和尚或道士为拜神佛而进行的活动。", "发誓": "fā（第一声）与 fǎ（第三声）声调不同，意思是发誓。", "发式": "fà（第四声）与 fǎ（第三声）声调不同，意思是发式（发型）。", "法术": "shù 与 shì 韵母不同（u 与 i），意思是法术。", "法制": "zhì 与 shì 声母不同（zh 与 sh），意思是法制（法律制度）。"}, "sentence_index": null, "correct_answer": "法事"}, "level_3": {"options": [{"text": "法事", "is_correct": true, "explanation": "法事：和尚或道士为拜神佛而进行的活动，道士在庙里做的就是法事。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，道士在庙里不做手术。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，与道士在庙里的活动无关。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验学习的活动，道士在庙里不是在考试。"}], "explanations": {"法事": "法事：和尚或道士为拜神佛而进行的活动，道士在庙里做的就是法事。", "手术": "语义：手术是医疗操作，道士在庙里不做手术。", "作业": "语义：作业是学生的功课，与道士在庙里的活动无关。", "考试": "语义：考试是测验学习的活动，道士在庙里不是在考试。"}, "sentence_index": 0, "correct_answer": "法事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的成立法事很热闹。", "explanation": "这里应该用〈庆典〉。“法事”是宗教活动，公司的庆祝不用“法事”。"}, {"text": "周末的电影节很热闹，大家都在看电影。", "explanation": "这里应该用〈电影节〉。“法事”是和尚道士的宗教活动，不指电影放映。"}, {"text": "法事上有很多比赛。", "explanation": "这里应该用〈运动会〉。“法事”是宗教活动，不能用来说比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd72428f5-3b32-4b7f-ab38-a238fa4385c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version