INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能在水底下开的船。", "primary_collocate": null, "pronunciation": "qián tǐng", "ipa": "tɕʰjɛn˧˥ tʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "潜艇是一种能在水底下开的船。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明画了一艘黄色的潜艇。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想坐潜艇去看海底的鱼。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘潜艇在水里慢慢往下沉。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在博物馆里看了一艘真的潜艇。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜艇不在水面上走，而是在水下走。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜艇可以在水下待很久，不用经常浮上来。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在潜艇里，窗外全是蓝色的海水。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借给我一本讲潜艇的书，我很喜欢。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜艇的窗户很小，却能看见海底。", "target_word": "潜艇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艘", "label": "量词"}, {"form": "潜艇模型", "label": "复合词"}, {"form": "潛艇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能在水底下开的船", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0741d1e3-cd5c-4fae-91d1-65d37b98a78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜艇", "is_correct": true, "explanation": "潜艇：能在水底下开的船，与“能在水底下开”的定义相符。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机在空中飞，不能在水底下开。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“开”可以搭配车船，不能说“开房子”。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车在铁轨上行驶，不能在水底下开。"}], "explanations": {"潜艇": "潜艇：能在水底下开的船，与“能在水底下开”的定义相符。", "飞机": "语义：飞机在空中飞，不能在水底下开。", "房子": "搭配：“开”可以搭配车船，不能说“开房子”。", "火车": "语义：火车在铁轨上行驶，不能在水底下开。"}, "sentence_index": 0, "correct_answer": "潜艇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛开始后，潜艇队员奋力划桨。", "explanation": "这里应该用〈龙舟〉。划桨是龙舟的动力方式，潜艇靠动力在水下开，不用划桨。"}, {"text": "潜艇在马路上飞快地跑，司机不停地按喇叭。", "explanation": "这里应该用〈汽车〉。在马路上飞快地跑、不停按喇叭的是汽车，潜艇是在水底下开的船，不在马路上行驶。"}, {"text": "潜艇借着风力，慢慢驶向岸边。", "explanation": "这里应该用〈帆船〉。借风力航行是帆船的做法，潜艇是在水底下开的船，不靠风力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜艇", "is_correct": true, "explanation": "潜艇：能在水底下开的船，可以在水下待很久，不用经常浮上来。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车在陆地上行驶，不能在水下待很久。"}, {"text": "帐篷", "is_correct": false, "explanation": "语义：帐篷搭在陆地上，不能在水下待很久。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能在水下待很久。"}], "explanations": {"潜艇": "潜艇：能在水底下开的船，可以在水下待很久，不用经常浮上来。", "汽车": "语义：汽车在陆地上行驶，不能在水下待很久。", "帐篷": "语义：帐篷搭在陆地上，不能在水下待很久。", "书包": "语义：书包是装东西的袋子，不能在水下待很久。"}, "sentence_index": 6, "correct_answer": "潜艇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着潜艇去超市买菜。", "explanation": "这里应该用〈自行车〉。骑着去超市的是自行车这类陆上车辆，潜艇是在水底下开的船，不能骑。"}, {"text": "这艘潜艇能在天上飞行好几个小时。", "explanation": "这里应该用〈飞机〉。在天上飞行的是飞机，潜艇是在水底下开的船，不能飞。"}, {"text": "妈妈用潜艇炒菜，香味飘满了厨房。", "explanation": "这里应该用〈炒锅〉。炒菜要用炒锅，潜艇是在水底下开的船，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把潜艇慢慢沉下去了。", "corrected_sentence": "这艘潜艇慢慢沉下去了。", "error_description": "量词错误：“把”用于有柄的器物，潜艇是船只，量词应用“艘”。应说“这艘潜艇慢慢沉下去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "潜艇终于飞上来了。", "corrected_sentence": "潜艇终于浮上来了。", "error_description": "搭配错误：“飞”用于能在空中飞行的物体，潜艇在水下航行，应说“浮上来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
