INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过圆心连接圆上两点的线段长度。", "primary_collocate": null, "pronunciation": "zhí jìng", "ipa": "ʈʂɻ̩˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "圆的直径是半径的两倍。", "target_word": "直径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "直径是通过圆心的线段，也是圆里最长的线。", "target_word": "直径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知道半径，就能算出直径。", "target_word": "直径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个圆，又画出它的直径。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圆的直径把圆分成两个相等的半圆。", "target_word": "直径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个圆的半径是三厘米，直径是六厘米。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圆里所有的直径都一样长。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你用尺子画一条直径。", "target_word": "直径", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "直径的长度等于两个半径加在一起。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "求圆的周长，要先知道直径。", "target_word": "直径", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "直徑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数学中过圆心的弦及其长度，是半径的两倍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径（zhí jìng）：经过圆心、连接圆上两点的线段，本词。"}, {"text": "止境", "is_correct": false, "explanation": "zhǐ jìng 与 zhí jìng 第一音节声调不同（第三声与第二声），意思是尽头、限度。"}, {"text": "直井", "is_correct": false, "explanation": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}, {"text": "直进", "is_correct": false, "explanation": "第二音节韵尾不同（jìn 是 n，jìng 是 ng），意思是笔直前进。"}, {"text": "石径", "is_correct": false, "explanation": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是石头铺成的小路。"}], "explanations": {"直径": "直径（zhí jìng）：经过圆心、连接圆上两点的线段，本词。", "止境": "zhǐ jìng 与 zhí jìng 第一音节声调不同（第三声与第二声），意思是尽头、限度。", "直井": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。", "直进": "第二音节韵尾不同（jìn 是 n，jìng 是 ng），意思是笔直前进。", "石径": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是石头铺成的小路。"}, "sentence_index": null, "correct_answer": "直径"}, "level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径：圆的一种长度，可以说“圆的直径是半径的两倍”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是长度，不能和半径比较倍数。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能用来和半径比较倍数。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”是平方单位的量，不能和长度的“半径”直接比较倍数。"}], "explanations": {"直径": "直径：圆的一种长度，可以说“圆的直径是半径的两倍”。", "颜色": "语义：颜色不是长度，不能和半径比较倍数。", "价格": "语义：价格是钱数，不能用来和半径比较倍数。", "面积": "搭配：“面积”是平方单位的量，不能和长度的“半径”直接比较倍数。"}, "sentence_index": 0, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上画了一条直径，离圆心很远。", "explanation": "这里应该用〈弦〉。直径必须经过圆心，离圆心远的线段只能叫弦。"}, {"text": "这个正方形的直径是五厘米。", "explanation": "这里应该用〈边长〉。直径只属于圆形，正方形没有圆心，要说边长。"}, {"text": "这个长方形的直径是十厘米。", "explanation": "这里应该用〈对角线〉。直径只属于圆形，长方形要说对角线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径（zhí jìng）：经过圆心、连接圆上两点的线段，本词。"}, {"text": "至境", "is_correct": false, "explanation": "zhì jìng 与 zhí jìng 只差第一音节声调（第四声与第二声），意思是最高的境界。"}, {"text": "实境", "is_correct": false, "explanation": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是真实的环境。"}, {"text": "直井", "is_correct": false, "explanation": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}], "explanations": {"直径": "直径（zhí jìng）：经过圆心、连接圆上两点的线段，本词。", "至境": "zhì jìng 与 zhí jìng 只差第一音节声调（第四声与第二声），意思是最高的境界。", "实境": "第一音节声母 sh 与 zh 不同（shí 与 zhí），意思是真实的环境。", "直井": "zhí jǐng 与 zhí jìng 只差第二音节声调（第三声与第四声），意思是垂直的井。"}, "sentence_index": null, "correct_answer": "直径"}, "level_3": {"options": [{"text": "直径", "is_correct": true, "explanation": "直径：圆里的线段长度，可以说“圆里所有的直径都一样长”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是长度，不能说“一样长”。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”说“一样大”，不说“一样长”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不能说“一样长”。"}], "explanations": {"直径": "直径：圆里的线段长度，可以说“圆里所有的直径都一样长”。", "味道": "语义：味道不是长度，不能说“一样长”。", "体积": "搭配：“体积”说“一样大”，不说“一样长”。", "年龄": "语义：年龄是人的岁数，不能说“一样长”。"}, "sentence_index": 6, "correct_answer": "直径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个正六边形的直径是二十四厘米。", "explanation": "这里应该用〈周长〉。正六边形没有圆心，直径只属于圆形，一圈的长度要说周长。"}, {"text": "这个梯形的直径是四厘米。", "explanation": "这里应该用〈高〉。直径只属于圆，梯形上下底之间的距离要说高。"}, {"text": "这个正方体的直径是三厘米。", "explanation": "这里应该用〈棱长〉。直径只属于圆形，正方体的边要说棱长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, va