INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个圆的一个直径是十厘米。", "corrected_sentence": "这个圆的直径是十厘米。", "error_description": "量词误用：直径作线段时用“条”，作数值时不加量词；此处应说“这个圆的直径是十厘米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个圆形垫子直径的十二厘米，很薄。", "corrected_sentence": "这个圆形垫子直径十二厘米，很薄。", "error_description": "多余的“的”：“直径”后面直接接数量，不加“的”，应说“直径十二厘米”；加“的”后“直径的十二厘米”缺少中心语，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
