INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97391, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "少花力气，也少花工夫。", "primary_collocate": null, "pronunciation": "shěng biàn", "ipa": "ʂɤŋ˨˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "用洗衣机洗衣服，比用手洗省便多了。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买票又快又省便，不用排队。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路近，走起来省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时请搬家公司，省便不少。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把东西放在门口，拿起来很省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付钱，省便得很，不用找零。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自己做饭不如叫外卖省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找个省便的办法打扫房间。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人住一楼，上下都省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把几件事一起办，既省时间又省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "省便：做事少费力气、少花工夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省便", "is_correct": true, "explanation": "正确：“省便”指做事少费力、少花工夫，与洗衣机替代手洗的语境相合。"}, {"text": "费力", "is_correct": false, "explanation": "语义：“费力”说耗费力气，与用洗衣机代替手洗的省力语境相反。"}, {"text": "麻烦", "is_correct": false, "explanation": "语义：“麻烦”说事情繁杂，与洗衣机省事的语境相反。"}, {"text": "辛苦", "is_correct": false, "explanation": "搭配：“辛苦”多形容人劳累，不用来形容洗衣机或洗衣方式。"}], "explanations": {"省便": "正确：“省便”指做事少费力、少花工夫，与洗衣机替代手洗的语境相合。", "费力": "语义：“费力”说耗费力气，与用洗衣机代替手洗的省力语境相反。", "麻烦": "语义：“麻烦”说事情繁杂，与洗衣机省事的语境相反。", "辛苦": "搭配：“辛苦”多形容人劳累，不用来形容洗衣机或洗衣方式。"}, "sentence_index": 0, "correct_answer": "省便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很省便，价格只要两百块。", "explanation": "这里应该用〈便宜〉。省便指做事少费力、少花工夫，不指东西价格低。"}, {"text": "孩子大了，我们很省便。", "explanation": "这里应该用〈省心〉。省便只说做事省力省工夫，不说人不操心。"}, {"text": "他很省便，从不乱花钱。", "explanation": "这里应该用〈节俭〉。省便只形容做事方法少费力，不形容人花钱节约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省便", "is_correct": true, "explanation": "正确：“省便”指省事便当，与叫外卖比自己做饭省事的语境相合。"}, {"text": "费时", "is_correct": false, "explanation": "语义：“费时”说耗时长，与叫外卖比自己做饭更省事的语境相反。"}, {"text": "费神", "is_correct": false, "explanation": "语义：“费神”指费心力，与叫外卖省事的语境相反。"}, {"text": "繁琐", "is_correct": false, "explanation": "语域：“繁琐”是书面词，与这句口语的语域不合；且说叫外卖繁琐，与句意矛盾。"}], "explanations": {"省便": "正确：“省便”指省事便当，与叫外卖比自己做饭省事的语境相合。", "费时": "语义：“费时”说耗时长，与叫外卖比自己做饭更省事的语境相反。", "费神": "语义：“费神”指费心力，与叫外卖省事的语境相反。", "繁琐": "语域：“繁琐”是书面词，与这句口语的语域不合；且说叫外卖繁琐，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "省便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱很省便，一个月电费很低。", "explanation": "这里应该用〈省电〉。省便指省力、省工夫，不指节约电能。"}, {"text": "这种包装很省便，用料很少。", "explanation": "这里应该用〈省料〉。省便说的是做事省工夫，不说节约材料。"}, {"text": "这个喷头很省便，一天能节约几吨水。", "explanation": "这里应该用〈省水〉。省便指做事少费力，不指节约用水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样做很省便，省便了很多时间。", "corrected_sentence": "这样做很省便，省了很多时间。", "error_description": "词性误用：“省便”是形容词，不能带宾语，不能说“省便了很多时间”；应说“很省便，省了很多时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找了个省便地路子解决问题。", "corrected_sentence": "他找了个省便的路子解决问题。", "error_description": "的地误用：“省便”修饰名词“路子”时应用“的”，不能用“地”，应说“省便的路子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
