INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97392, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "省事便当；简便。", "primary_collocate": null, "pronunciation": "shěng biàn", "ipa": "ʂɤŋ˨˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种做法很省便，大家都爱用。", "target_word": "省便", "complexity_tier": "T3", "furigana": "zhè zhǒng zuò fǎ hěn shěng biàn, dà jiā dōu ài yòng.", "sentence_source": "generated"}, {"text": "他用一个小办法，省便地解决了问题。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次说清楚最省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冲泡饮料，不用煮，省便极了。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件操作省便，老人也会用。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办手续只要一张表，非常省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的办法比以前省便得多。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嫌麻烦，总想找省便的路子。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把几个步骤合在一起，做起来省便。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里装了热水器，洗澡省便多了。", "target_word": "省便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "省便：办法或步骤简单，省事便当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省便", "is_correct": true, "explanation": "正确：“省便”指办法简单、省事便当，与“大家都爱用”的语境相合。"}, {"text": "费力", "is_correct": false, "explanation": "语义：“费力”说耗费力气，与“大家都爱用”的便利语境相抵触。"}, {"text": "麻烦", "is_correct": false, "explanation": "语义：“麻烦”说事情繁杂，与“大家都爱用”的语境相矛盾。"}, {"text": "繁琐", "is_correct": false, "explanation": "语域：“繁琐”是书面词，与这句口语的语域不合；且步骤繁琐与大家都爱用相矛盾。"}], "explanations": {"省便": "正确：“省便”指办法简单、省事便当，与“大家都爱用”的语境相合。", "费力": "语义：“费力”说耗费力气，与“大家都爱用”的便利语境相抵触。", "麻烦": "语义：“麻烦”说事情繁杂，与“大家都爱用”的语境相矛盾。", "繁琐": "语域：“繁琐”是书面词，与这句口语的语域不合；且步骤繁琐与大家都爱用相矛盾。"}, "sentence_index": 0, "correct_answer": "省便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个牌子的衣服很省便，穿得久。", "explanation": "这里应该用〈耐穿〉。省便指办法简单、省工夫，不指物品耐用。"}, {"text": "孩子大了，全家都很省便。", "explanation": "这里应该用〈省心〉。省便只说办法省力省事，不说人不操心。"}, {"text": "这个人很省便，平时很少乱花钱。", "explanation": "这里应该用〈节俭〉。省便只形容做事方法少费力，不形容人花钱节约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省便", "is_correct": true, "explanation": "正确：“省便”指办法简便、省事，与“比以前”改进的语境相合。"}, {"text": "费时", "is_correct": false, "explanation": "语义：“费时”说耗时长，与“比以前”改进的语境相反。"}, {"text": "费神", "is_correct": false, "explanation": "语义：“费神”指费心力，与现在办法比以前改进的语境相反。"}, {"text": "辛苦", "is_correct": false, "explanation": "搭配：“辛苦”多形容人的劳累，不说办法“辛苦”。"}], "explanations": {"省便": "正确：“省便”指办法简便、省事，与“比以前”改进的语境相合。", "费时": "语义：“费时”说耗时长，与“比以前”改进的语境相反。", "费神": "语义：“费神”指费心力，与现在办法比以前改进的语境相反。", "辛苦": "搭配：“辛苦”多形容人的劳累，不说办法“辛苦”。"}, "sentence_index": 6, "correct_answer": "省便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个灯泡很省便，一年电费很少。", "explanation": "这里应该用〈省电〉。省便指省力、省工夫，不指节约电能。"}, {"text": "这种纸很省便，用料很少。", "explanation": "这里应该用〈省料〉。省便说的是做事省工夫，不说节约材料。"}, {"text": "我这个月很省便，攒了不少钱。", "explanation": "这里应该用〈省钱〉。省便指做事少费力、少花工夫，不指花钱少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省便地办法很实用。", "corrected_sentence": "这个省便的办法很实用。", "error_description": "的地误用：“省便”修饰名词“办法”时应用“的”，不能用“地”，应说“省便的办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法很省便，省便了很多步骤。", "corrected_sentence": "这个办法很省便，省了很多步骤。", "error_description": "词性误用：“省便”是形容词，不能带宾语，不能说“省便了很多步骤”；应说“很省便，省了很多步骤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
