INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出门旅行时带的箱子和包。", "primary_collocate": null, "pronunciation": "xíng li", "ipa": "ɕiŋ˧˥ li", "syllable_count": 2, "sentences": [{"text": "这次去北京，我只带了一件行李。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把行李放在门口。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人提着两件行李慢慢上了楼。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行，行李越轻越好。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，行李可以放在哪儿？", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明帮妈妈拿行李，一点也不累。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们下了车，先去取行李。", "target_word": "行李", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的行李里有两件毛衣和一双鞋。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机时，大件行李要先托运。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天要走，她今晚就收拾行李。", "target_word": "行李", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件行李", "label": "量词"}, {"form": "行李箱", "label": "复合"}, {"form": "行李架", "label": "复合"}], "register": "中性", "sense_fingerprint": "行李：出门旅行时带的箱子和包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675cfc97-fbfc-4651-bf94-1c49f7b53f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事故", "is_correct": false, "explanation": "语义：事故不是可以随身带去北京的东西，句子说不通。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗行为，不能被带去北京。"}, {"text": "行李", "is_correct": true, "explanation": "正确：行李指出门旅行时带的箱包，“带了一件”正好指随身携带的物品。"}, {"text": "事件", "is_correct": false, "explanation": "搭配：“带”不能和“事件”搭配，事件无法随身携带。"}], "explanations": {"事故": "语义：事故不是可以随身带去北京的东西，句子说不通。", "手术": "语义：手术是医疗行为，不能被带去北京。", "行李": "正确：行李指出门旅行时带的箱包，“带了一件”正好指随身携带的物品。", "事件": "搭配：“带”不能和“事件”搭配，事件无法随身携带。"}, "sentence_index": 0, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他带了两张行李去北京。", "explanation": "这里应该用〈件〉。行李用“件”计量，“张”用于纸张、桌子等平面的东西。"}, {"text": "他每天下班后背着行李去健身房。", "explanation": "这里应该用〈运动包〉。去健身房背装备要用〈运动包〉，“行李”指出门旅行时带的箱子和包，不用于健身。"}, {"text": "他每次买菜都提着一件行李，装了很多蔬菜。", "explanation": "这里应该用〈购物袋〉。买菜装蔬菜要用〈购物袋〉，“行李”指出门旅行时带的箱子和包，不用来买菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方向", "is_correct": false, "explanation": "语义：方向不是可以拿走的东西，“取”的语境不合。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是一项活动，不能去“取”。"}, {"text": "行李", "is_correct": true, "explanation": "正确：下车后去取的是旅行时携带的箱包，“取”正好搭配行李。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“取”不能和“天气”搭配，天气无法被拿走。"}], "explanations": {"方向": "语义：方向不是可以拿走的东西，“取”的语境不合。", "演唱会": "语义：演唱会是一项活动，不能去“取”。", "行李": "正确：下车后去取的是旅行时携带的箱包，“取”正好搭配行李。", "天气": "搭配：“取”不能和“天气”搭配，天气无法被拿走。"}, "sentence_index": 6, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天的行李安排得很满，要去三个景点。", "explanation": "这里应该用〈行程〉。“安排得很满”“去三个景点”说的是出行计划，要用〈行程〉；“行李”指出门带的箱子和包。"}, {"text": "我们的行李定在下午三点，不能再改了。", "explanation": "这里应该用〈日程〉。时间定下来、不能再改，要说〈日程〉；“行李”指出门带的箱子和包，不能用来定时间。"}, {"text": "快递送来一件行李，是我在网上买的书。", "explanation": "这里应该用〈包裹〉。网购的东西寄来要说〈包裹〉，“行李”指出门旅行时带的箱子和包，不用于快递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带了两张行李来北京找朋友。", "corrected_sentence": "他带了两件行李来北京找朋友。", "error_description": "量词错误：“行李”应该用量词“件”，说“两件行李”。“张”用于纸张、桌子等平面的东西，不能用来数行李。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本行李已经装上车了。", "corrected_sentence": "这件行李已经装上车了。", "error_description": "量词错误：“行李”应该用量词“件”，说“这件行李”。“本”用于书籍、本子等，不能用来数行李。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
