INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走以前，互相说再见。", "primary_collocate": null, "pronunciation": "huà bié", "ipa": "xwa˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "临走前，他和老朋友一一话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里，大家含着泪话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开公司那天，她和同事话别了。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车快开了，我们在站台上话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业前，同学们一起吃饭话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国前，来向我们话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站在门口，互相话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要走了，学生都来和他话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天就出发，今晚我去和邻居话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在车站握着手话别，谁也没哭。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "话别了", "label": "体标（了）"}], "register": "书面", "sense_fingerprint": "话别：分别之前与人当面道别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指离开前与人当面道别，与“临走前”的语境一致。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争执，与“临走前一一话别”的道别语境不符。"}, {"text": "相识", "is_correct": false, "explanation": "语义：“相识”指初次认识，与“老朋友”的前提以及“临走前”的语境矛盾。"}, {"text": "探望", "is_correct": false, "explanation": "配价：“探望”需带宾语（探望某人），“和老朋友”只是共同参与者，句子缺宾语。"}], "explanations": {"话别": "正确：话别指离开前与人当面道别，与“临走前”的语境一致。", "吵架": "语义：“吵架”是争执，与“临走前一一话别”的道别语境不符。", "相识": "语义：“相识”指初次认识，与“老朋友”的前提以及“临走前”的语境矛盾。", "探望": "配价：“探望”需带宾语（探望某人），“和老朋友”只是共同参与者，句子缺宾语。"}, "sentence_index": 0, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他离开前，向故乡话别了。", "explanation": "这里应该用〈告别〉。话别是人与人当面互道告别，对象是人，不能对故乡等地点说话别。"}, {"text": "我们每天早上见面时互相话别。", "explanation": "这里应该用〈打招呼〉。话别只用于临别时的道别，日常见面不能说话别。"}, {"text": "久别重逢，我们热情地话别了一番。", "explanation": "这里应该用〈问候〉。话别用于临别时互相道别，久别重逢时应说问候，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指临别时当面道别，与“大家站在门口”的离别场景一致。"}, {"text": "聚会", "is_correct": false, "explanation": "搭配：“互相”修饰可以彼此进行的动作，“聚会”是集体活动，不说互相聚会。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带宾语（送某人、送某物），单独用于“互相送”句子不完整。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争执，与“大家站在门口”的道别场景不符。"}], "explanations": {"话别": "正确：话别指临别时当面道别，与“大家站在门口”的离别场景一致。", "聚会": "搭配：“互相”修饰可以彼此进行的动作，“聚会”是集体活动，不说互相聚会。", "送": "配价：“送”需要带宾语（送某人、送某物），单独用于“互相送”句子不完整。", "吵架": "语义：“吵架”是争执，与“大家站在门口”的道别场景不符。"}, "sentence_index": 6, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚进门，就和邻居话别了几句。", "explanation": "这里应该用〈寒暄〉。话别只用于临别时道别，刚见面时的客套不能说话别。"}, {"text": "我们在机场为远道而来的朋友话别。", "explanation": "这里应该用〈接风〉。话别是送人离开时的道别，朋友刚到应当说接风，不能说话别。"}, {"text": "春节那天，我们挨家挨户话别。", "explanation": "这里应该用〈拜年〉。话别是临行时的告别，春节走访只能说拜年，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天出发前，他要老朋友话别。", "corrected_sentence": "明天出发前，他要和老朋友话别。", "error_description": "错误：话别的对象要用“和”引出，此处漏掉“和”。正确为“和老朋友话别”，不能说“老朋友话别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在站台上互相话别大家。", "corrected_sentence": "他们在站台上互相话别。", "error_description": "错误：“话别”后直接带人称宾语“大家”。正确为“互相话别”，互相道别不带宾语；若要指明对象，应用“和”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
