INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临别时互相说告别的话。", "primary_collocate": null, "pronunciation": "huà bié", "ipa": "xwa˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "临别时，两位老人话别了很久。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在门前话别，说了许多祝福的话。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话别时，她送给我一封信。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在餐桌上举杯话别，说着心里话。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临行前夜，兄弟二人彻夜话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她与家人话别，叮嘱了很多事。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家围坐着话别，气氛有点伤感。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们与乡亲们依依话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长和毕业生们话别，互相道了珍重。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临别的晚上，我们只想好好话别。", "target_word": "话别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "话别了", "label": "体标（了）"}], "register": "书面", "sense_fingerprint": "话别：临别时彼此交谈、说告别的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指临别时彼此交谈、说告别的话，与“临别时”的语境相合。"}, {"text": "拜年", "is_correct": false, "explanation": "语义：“拜年”是春节的贺岁问候，与“临别时”的离别语境不符。"}, {"text": "迎接", "is_correct": false, "explanation": "配价：“迎接”需带宾语（迎接某人），单用“迎接了很久”句子不完整，且与“临别”语境相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎来，与“临别时”的离别语境相反。"}], "explanations": {"话别": "正确：话别指临别时彼此交谈、说告别的话，与“临别时”的语境相合。", "拜年": "语义：“拜年”是春节的贺岁问候，与“临别时”的离别语境不符。", "迎接": "配价：“迎接”需带宾语（迎接某人），单用“迎接了很久”句子不完整，且与“临别”语境相反。", "欢迎": "语义：“欢迎”表示迎来，与“临别时”的离别语境相反。"}, "sentence_index": 0, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚见到老同学，两人就话别了几句。", "explanation": "这里应该用〈寒暄〉。话别只用于临别之时，刚见面时的客套不能说话别。"}, {"text": "我们在车站为远道而来的朋友话别。", "explanation": "这里应该用〈接风〉。话别是送人离开时的道别，朋友刚到应当说接风，不能说话别。"}, {"text": "大年初一，我们挨家挨户话别。", "explanation": "这里应该用〈拜年〉。话别是临行时的告别，春节走访只能说拜年，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话别", "is_correct": true, "explanation": "正确：话别指临别时彼此交谈、说告别的话，与“大家围坐着”的临别场景一致。"}, {"text": "欢庆", "is_correct": false, "explanation": "语义：“欢庆”表示喜庆，与“气氛有点伤感”的语气矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需带宾语（感谢某人），“围坐着感谢”句子缺宾语。"}, {"text": "欢聚", "is_correct": false, "explanation": "语义：“欢聚”表示欢乐地聚在一起，与“伤感”的气氛冲突。"}], "explanations": {"话别": "正确：话别指临别时彼此交谈、说告别的话，与“大家围坐着”的临别场景一致。", "欢庆": "语义：“欢庆”表示喜庆，与“气氛有点伤感”的语气矛盾。", "感谢": "配价：“感谢”需带宾语（感谢某人），“围坐着感谢”句子缺宾语。", "欢聚": "语义：“欢聚”表示欢乐地聚在一起，与“伤感”的气氛冲突。"}, "sentence_index": 6, "correct_answer": "话别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚回到母校，就和老师话别了几句。", "explanation": "这里应该用〈问候〉。话别只用于临别之时，刚回到母校时的寒暄应说问候，不能说话别。"}, {"text": "我们每天上课前见面时互相话别。", "explanation": "这里应该用〈打招呼〉。话别只用于临别之时，日常见面不能说话别。"}, {"text": "重逢的那天，我们兴奋地话别。", "explanation": "这里应该用〈叙旧〉。话别用于临别时，重逢后互相聊往事应说叙旧，不能说话别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "临别前，她妈妈话别。", "corrected_sentence": "临别前，她和妈妈话别。", "error_description": "错误：话别的对象要用“和”引出，此处漏掉“和”。正确为“和妈妈话别”，不能说“她妈妈话别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们互相话别同学，说了很多心里话。", "corrected_sentence": "他们互相话别，说了很多心里话。", "error_description": "错误：“话别”后直接带人称宾语“同学”。正确为“互相话别”，互相道别不带宾语；若要指明对象，应用“和”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送走", "is_correct": true, "explanation": "送走：与“迎来”相对，指送走离去的人或时期。"}, {"text": "休息", "is_correct": false, "explanation": "与“迎来”没有反义关系，指停止劳动或活动。"}, {"text": "生长", "is_correct": false, "explanation": "与“迎来”没有反义关系，指植物或人逐渐长大。"}, {"text": "思考", "is_correct": false, "explanation": "与“迎来”没有反义关系，指用脑子考虑问题。"}], "correct_answer": "送走", "explanations": {"送走": "送走：与“迎来”相对，指送走离去的人或时期。", "休息": "与“迎来”没有反义关系，指停止劳动或活动。", "生长": "与“迎来”没有反义关系，指植物或人逐渐长大。", "思考": "与“迎来”没有反义关系，指用脑子考虑问题。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送别", "is_correct": true, "explanation": "送别：与“迎来”相对，指送行告别离去的人。"}, {"text": "写作", "is_correct": false, "explanation": "与“迎来”没有反义关系，指写文章或作品。"}, {"text": "游泳", "is_correct": false, "explanation": "与“迎来”没有反义关系，指在水中划动身体前进。"}, {"text": "说话", "is_correct": false, "explanation": "与“迎来”没有反义关系，指用语言表达想法。"}], "correct_answer": "送别", "explanations": {"送别": "送别：与“迎来”相对，指送行告别离去的人。", "写作": "与“迎来”没有反义关系，指写文章或作品。", "游泳": "与“迎来”没有反义关系，指在水中划动身体前进。", "说话": "与“迎来”没有反义关系，指用语言表达想法。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有人或好日子来了，大家高兴地迎接。", "primary_collocate": null, "pronunciation": "yíng lái", "ipa": "iŋ˧˥ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "全家人站在门口，迎来了远方的客人。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的努力，农民迎来了丰收的好日子。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里，大家迎来了回国的运动员。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天雨，村里终于迎来了晴天。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口，孩子们迎来了放假回家的哥哥。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家迎来了一个可爱的小宝宝。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节到了，我们高高兴兴地迎来新年。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人迎来了幸福的晚年。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们敲锣打鼓，迎来了新来的老师。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈笑着迎来了下班回家的爸爸。", "target_word": "迎来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎来了", "label": "完成体"}, {"form": "迎来过", "label": "经历体"}, {"form": "迎來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高兴地接来客人或好日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0741d1e3-cd5c-4fae-91d1-65d37b98a78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：高兴地接来远方的客人，与“站在门口”的语境相符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：全家人站在门口是热情接待，“抛弃”的语义与之相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”含有赶走的意思，与热情接待客人的语境冲突。"}, {"text": "吸收", "is_correct": false, "explanation": "搭配：“吸收”用于知识、营养等，不能用于接待客人。"}], "explanations": {"迎来": "迎来：高兴地接来远方的客人，与“站在门口”的语境相符。", "抛弃": "语义：全家人站在门口是热情接待，“抛弃”的语义与之相反。", "驱赶": "语义：“驱赶”含有赶走的意思，与热情接待客人的语境冲突。", "吸收": "搭配：“吸收”用于知识、营养等，不能用于接待客人。"}, "sentence_index": 0, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌人来犯，士兵们奋起迎来了敌人。", "explanation": "这里应该用〈迎战〉。迎来表示高兴地接来人或好日子，不用于对敌作战。"}, {"text": "春节刚过，我们迎来了旧年。", "explanation": "这里应该用〈送走〉。迎来用于将要到来的人或时期，旧年已经过去。"}, {"text": "士兵迎来了入侵的敌人。", "explanation": "这里应该用〈驱逐〉。入侵者不是高兴地迎接的客人，迎来不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎来", "is_correct": true, "explanation": "迎来：高兴地迎接新的一年，与“春节到了”和“高高兴兴”的语境相符。"}, {"text": "送走", "is_correct": false, "explanation": "语义：春节刚到，新年才开始，不能说送走新年。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不与节日或“新年”搭配，不能说推迟新年。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“高高兴兴”的情绪相反，语境不合。"}], "explanations": {"迎来": "迎来：高兴地迎接新的一年，与“春节到了”和“高高兴兴”的语境相符。", "送走": "语义：春节刚到，新年才开始，不能说送走新年。", "推迟": "搭配：“推迟”不与节日或“新年”搭配，不能说推迟新年。", "拒绝": "语义：“拒绝”与“高高兴兴”的情绪相反，语境不合。"}, "sentence_index": 6, "correct_answer": "迎来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迎来了那个被放弃的计划。", "explanation": "这里应该用〈放弃〉。迎来指高兴地接来人或好日子，被放弃的计划既不是人，也不是好日子，不能迎来。"}, {"text": "小镇迎来了那条被拆掉的旧铁路。", "explanation": "这里应该用〈拆除〉。迎来指高兴地接来人或好日子，旧铁路既不是人，也不是好日子，不能迎来。"}, {"text": "他迎来了那些旧习惯。", "explanation": "这里应该用〈丢掉〉。迎来指高兴地接来人或好日子，旧习惯既不是人，也不是好日子，不能迎来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开学那天，学校迎来在三个新同学。", "corrected_sentence": "开学那天，学校迎来了三个新同学。", "error_description": "“在”位置错误：“在”不能直接放在“迎来”之后引出数量短语，应去掉“在”，说“学校迎来了三个新同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那天我们不迎来远道而来的朋友。", "corrected_sentence": "那天我们没迎来远道而来的朋友。", "error_description": "否定副词错误：过去发生的事应用“没”否定，不能用“不”。应说“那天我们没迎来远道而来的朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
