INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落选", "is_correct": true, "explanation": "落选：没有被录取，与“录取”意思相反。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先做好安排，与“录取”没有反义关系。"}, {"text": "考虑", "is_correct": false, "explanation": "考虑：指思量、斟酌，与“录取”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "参加：指加入某项活动，与“录取”不构成反义。"}], "correct_answer": "落选", "explanations": {"落选": "落选：没有被录取，与“录取”意思相反。", "准备": "准备：指事先做好安排，与“录取”没有反义关系。", "考虑": "考虑：指思量、斟酌，与“录取”不构成反义。", "参加": "参加：指加入某项活动，与“录取”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学校或工作的地方，选了你，你可以来。", "primary_collocate": null, "pronunciation": "lù qǔ", "ipa": "lu˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我考得很好，学校录取我了。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家公司录取了我，我下周上班。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈很高兴，因为大学录取了我姐姐。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去那家公司工作，可是公司没录取他。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的成绩这么好，那所大学肯定会录取你。", "target_word": "录取", "complexity_tier": "T3", "furigana": "lù qǔ", "sentence_source": "generated"}, {"text": "小明说，那所中学录取了他。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说医院只录取了两个护士。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申请过三所大学，只有一所录取了她。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校录取了我，我马上告诉了爸爸。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试了两次，这次公司终于录取他了。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "录取了", "label": "体标"}, {"form": "录取过", "label": "体标"}, {"form": "录取通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校或公司选中某人，同意他来上学或上班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示学校选中学生，符合句意。"}, {"text": "开除", "is_correct": false, "explanation": "语义：“开除”是让人离开，与前句“考得很好”的语境相矛盾。"}, {"text": "辞退", "is_correct": false, "explanation": "搭配：“辞退”用于解雇员工，学校不能辞退学生。"}, {"text": "驳回", "is_correct": false, "explanation": "搭配：“驳回”用于申请、请求等，不能直接用于人。"}], "explanations": {"录取": "“录取”表示学校选中学生，符合句意。", "开除": "语义：“开除”是让人离开，与前句“考得很好”的语境相矛盾。", "辞退": "搭配：“辞退”用于解雇员工，学校不能辞退学生。", "驳回": "搭配：“驳回”用于申请、请求等，不能直接用于人。"}, "sentence_index": 0, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校录取了我的申请。", "explanation": "这里应该用〈接受〉。录取的对象是人，申请要说“接受”，不能说“录取”。"}, {"text": "这份工作录取了我。", "explanation": "这里应该用〈录用〉并以机构为主语。录取、录用都要求挑选人的机构作主语，“工作”是事物，不能挑选人，应说“公司录用了我”。"}, {"text": "我录取了那所大学。", "explanation": "这里应该用〈考上〉。录取的主语是挑选学生的学校，学生是被挑选的一方，应说“我考上了那所大学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示医院之类的机构选拔并接收人员，符合句意。"}, {"text": "保送", "is_correct": false, "explanation": "搭配：“保送”是学校为学生办理升学，医院不能保送护士。"}, {"text": "入学", "is_correct": false, "explanation": "配价：“入学”是不及物动词，不能带“两个护士”作宾语。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带宾语，护士也不是在医院毕业。"}], "explanations": {"录取": "“录取”表示医院之类的机构选拔并接收人员，符合句意。", "保送": "搭配：“保送”是学校为学生办理升学，医院不能保送护士。", "入学": "配价：“入学”是不及物动词，不能带“两个护士”作宾语。", "毕业": "配价：“毕业”是不及物动词，不能带宾语，护士也不是在医院毕业。"}, "sentence_index": 6, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆录取了这首歌。", "explanation": "这里应该用〈收录〉。收录指把作品收进去，录取只用于选拔人员。"}, {"text": "他在比赛里被录取了第一名。", "explanation": "这里应该用〈获得〉。录取指选拔人员入学或入职，比赛名次要说“他在比赛里获得了第一名”。"}, {"text": "那家餐厅录取了这位顾客。", "explanation": "这里应该用〈接待〉。餐厅招待顾客要说“接待”；录取只用于按标准选拔人员入学或入职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校录取着我，我特别开心。", "corrected_sentence": "学校录取了我，我特别开心。", "error_description": "“录取”是一次性完成的动作，不能加“着”表示持续，应说“录取了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那所学校没录取了他，他很难过。", "corrected_sentence": "那所学校没录取他，他很难过。", "error_description": "“没”与“了”不能同用，否定句应说“没录取他”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
