INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按标准挑选并接收为学生或员工。", "primary_collocate": null, "pronunciation": "lù qǔ", "ipa": "lu˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这所大学今年录取了三千名新生。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司录取了十个新员工。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的分数够高，学校一定会录取他。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京大学去年没有录取这个学生。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司只录取有经验的人。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校按成绩录取学生。", "target_word": "录取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是我们公司去年录取的第一个人。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医学院录取学生时，很看重成绩。", "target_word": "录取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校他申请过两次，都没有录取他。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把录取的同学叫到办公室。", "target_word": "录取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录取了", "label": "体标"}, {"form": "录取过", "label": "体标"}, {"form": "录取通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "学校或单位按成绩、条件挑选并接收新生或新员工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示学校经过选拔接收新生，符合句意。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”是送别，新生刚入学，与句子的意思不合。"}, {"text": "派遣", "is_correct": false, "explanation": "搭配：“派遣”用于派出人员或部队，不能用于学校招收新生。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带“三千名新生”作宾语，且新生尚未毕业。"}], "explanations": {"录取": "“录取”表示学校经过选拔接收新生，符合句意。", "欢送": "语义：“欢送”是送别，新生刚入学，与句子的意思不合。", "派遣": "搭配：“派遣”用于派出人员或部队，不能用于学校招收新生。", "毕业": "配价：“毕业”是不及物动词，不能带“三千名新生”作宾语，且新生尚未毕业。"}, "sentence_index": 0, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他录取了北京大学。", "explanation": "这里应该用〈考上〉。录取的主语是挑选学生的学校，学生是“考上”学校，不能说“录取”学校。"}, {"text": "老板录取了一个好主意。", "explanation": "这里应该用〈采纳〉。录取指按标准挑选并接收学生或员工，对象只能是人；接受别人的主意、建议要说“采纳”。"}, {"text": "这份工作录取了我。", "explanation": "这里应该用〈录用〉并以机构为主语。录取、录用都要求挑选人的机构作主语，“工作”是事物，不能挑选人，应说“公司录用了我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "录取", "is_correct": true, "explanation": "“录取”表示公司或学校挑选并接收人员，符合句意。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”只用于学生完成学业，不能说“公司毕业”。"}, {"text": "保送", "is_correct": false, "explanation": "搭配：“保送”是学校为学生办理升学，公司不能保送人。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“下课”指一节课结束，与“第一个人”的语境不合。"}], "explanations": {"录取": "“录取”表示公司或学校挑选并接收人员，符合句意。", "毕业": "搭配：“毕业”只用于学生完成学业，不能说“公司毕业”。", "保送": "搭配：“保送”是学校为学生办理升学，公司不能保送人。", "下课": "语义：“下课”指一节课结束，与“第一个人”的语境不合。"}, "sentence_index": 6, "correct_answer": "录取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆录取了这本新书。", "explanation": "这里应该用〈收录〉。收录指把书籍、作品收进去，录取只用于选拔人员。"}, {"text": "这次比赛，我们录取了三名冠军。", "explanation": "这里应该用〈获得〉。比赛名次靠成绩取得，不经过选拔接收入学或入职，要说“获得了前三名”。"}, {"text": "医院录取了那位病人。", "explanation": "这里应该用〈收治〉。医院接收病人住院治疗要说“收治”；录取只用于按标准选拔人员入学或入职。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学去年没录取了我的朋友。", "corrected_sentence": "这所大学去年没录取我的朋友。", "error_description": "“没”表示否定，不能与“了”同用。否定句应去掉“了”，说“没录取我的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听说学校录取着小王，真好。", "corrected_sentence": "我听说学校录取了小王，真好。", "error_description": "“录取”是一次性完成的动作，不能加“着”表示持续，应改为“录取了小王”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97513, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次要", "is_correct": true, "explanation": "次要：指位于第二位、不如首要的，与“首要”意思相反。"}, {"text": "紧急", "is_correct": false, "explanation": "紧急：指需要立即处理，与“首要”不构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂：指头绪多、难理解，与“首要”不构成反义。"}, {"text": "简单", "is_correct": false, "explanation": "简单：指不复杂、容易，与“首要”不构成反义。"}], "correct_answer": "次要", "explanations": {"次要": "次要：指位于第二位、不如首要的，与“首要”意思相反。", "紧急": "紧急：指需要立即处理，与“首要”不构成反义。", "复杂": "复杂：指头绪多、难理解，与“首要”不构成反义。", "简单": "简单：指不复杂、容易，与“首要”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
