INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里很坏很吓人的怪物。", "primary_collocate": null, "pronunciation": "mó guǐ", "ipa": "mwo˧˥ kweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "故事里的魔鬼住在黑山上。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小弟弟怕魔鬼，晚上不敢关灯。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里有一个很大的魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王把魔鬼关进了山洞里。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的魔鬼有红眼睛和长牙。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英雄打败了魔鬼，大家都很高兴。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们听着魔鬼的故事，不敢睡觉。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一个有两只角的魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，这座山以前有过魔鬼。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔鬼在夜里出来，吓坏了村里人。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小魔鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "童话、电影、故事里又坏又吓人的怪物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：魔鬼是故事里的怪物，可以住在黑山上。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“住”需要有生命的主体，电脑是机器，不能住在山上。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“住”不搭配“汽车”，汽车只能停在山上。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不会住在黑山上。"}], "explanations": {"魔鬼": "正确：魔鬼是故事里的怪物，可以住在黑山上。", "电脑": "语义：“住”需要有生命的主体，电脑是机器，不能住在山上。", "汽车": "搭配：“住”不搭配“汽车”，汽车只能停在山上。", "面包": "语义：面包是食物，不会住在黑山上。"}, "sentence_index": 0, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "圣诞夜，魔鬼悄悄给孩子们送来礼物。", "explanation": "这里应该用〈天使〉。魔鬼是凶恶的怪物，不会悄悄给孩子送礼物；带来礼物和祝福的要说天使。"}, {"text": "天上的魔鬼很善良，常常保佑人们。", "explanation": "这里应该用〈神仙〉。魔鬼是凶恶的怪物，不能说“很善良，常常保佑人们”。"}, {"text": "农夫在田边摆上供品，向魔鬼祈求丰收。", "explanation": "这里应该用〈土地公〉。魔鬼是凶恶的怪物，不能用来保佑丰收；求丰收要向土地公祈求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：魔鬼是让孩子害怕的怪物，所以他们不敢睡觉。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果的故事通常温馨，不会让孩子不敢睡觉。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“故事”多指人物或事件，“天气”不是可以讲的故事。"}, {"text": "物理", "is_correct": false, "explanation": "搭配：“物理”是学科，不能作为讲述的故事题材。"}], "explanations": {"魔鬼": "正确：魔鬼是让孩子害怕的怪物，所以他们不敢睡觉。", "糖果": "语义：糖果的故事通常温馨，不会让孩子不敢睡觉。", "天气": "搭配：“故事”多指人物或事件，“天气”不是可以讲的故事。", "物理": "搭配：“物理”是学科，不能作为讲述的故事题材。"}, "sentence_index": 6, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子上放着一本魔鬼。", "explanation": "这里应该用〈个〉。“本”用于书、本子一类，魔鬼要用“个”。"}, {"text": "村口的树下坐着一棵魔鬼。", "explanation": "这里应该用〈个〉。“棵”用于植物，魔鬼要用“个”。"}, {"text": "他手里拿着一根魔鬼。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，魔鬼要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在山洞里看见了个一魔鬼。", "corrected_sentence": "他在山洞里看见了一个魔鬼。", "error_description": "语序错误：数量短语应说“一个”，不能说“个一”，应把“个一”改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里来了一条魔鬼，大家都躲了起来。", "corrected_sentence": "村里来了一个魔鬼，大家都躲了起来。", "error_description": "量词错误：“条”用于细长的东西，魔鬼要用“个”，应把“条”改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
