INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "迷信或故事中凶恶的鬼怪；比喻极坏的人。", "primary_collocate": null, "pronunciation": "mó guǐ", "ipa": "mwo˧˥ kweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "以前的人说，魔鬼会在夜里害人。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏人像魔鬼一样，什么坏事都做。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对孩子那么狠，简直是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人以为他是魔鬼，都不敢靠近。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人说那个独裁者是魔鬼，会毁掉一切。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，魔鬼最怕光和火。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个骗子是个魔鬼，骗光了老人的钱。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，夜里不能出门，魔鬼会来抓人。", "target_word": "魔鬼", "complexity_tier": "T3", "furigana": "lǎo rén shuō, yè lǐ bù néng chū mén, mó guǐ huì lái zhuā rén.", "sentence_source": "generated"}, {"text": "她把前夫看成魔鬼，再也不想见他。", "target_word": "魔鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在受害者眼里，他就是魔鬼。", "target_word": "魔鬼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小魔鬼", "label": "复合"}], "register": "中性", "sense_fingerprint": "迷信传说中凶恶的鬼怪，也比喻极坏、极残忍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：魔鬼是迷信中凶恶的鬼怪，可以在夜里害人。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳白天出现，夜里不在天上，与“在夜里”矛盾。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“害人”通常指有恶意的鬼怪、坏人或疾病，不搭配“牛奶”。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵没有恶意，不会“害人”。"}], "explanations": {"魔鬼": "正确：魔鬼是迷信中凶恶的鬼怪，可以在夜里害人。", "太阳": "语义：太阳白天出现，夜里不在天上，与“在夜里”矛盾。", "牛奶": "搭配：“害人”通常指有恶意的鬼怪、坏人或疾病，不搭配“牛奶”。", "花朵": "语义：花朵没有恶意，不会“害人”。"}, "sentence_index": 0, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人心地善良，总是像魔鬼一样帮助大家。", "explanation": "这里应该用〈天使〉。魔鬼指极坏的人，与“心地善良、帮助大家”矛盾。"}, {"text": "这位老师是个魔鬼，从不骂学生。", "explanation": "这里应该用〈好人〉。魔鬼指极坏的人，与“从不骂学生”矛盾。"}, {"text": "这位医生是魔鬼，一生都在救治穷人。", "explanation": "这里应该用〈圣人〉。魔鬼指极坏的人，与“一生救治穷人”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔鬼", "is_correct": true, "explanation": "正确：“魔鬼”指极坏的人，与“骗子”和“骗光了钱”相符。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使善良，与“骗光了老人的钱”矛盾。"}, {"text": "好人", "is_correct": false, "explanation": "语义：“好人”与“骗子”的身份矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“是个……”后的名词要能指人，“小猫”不能是骗子。"}], "explanations": {"魔鬼": "正确：“魔鬼”指极坏的人，与“骗子”和“骗光了钱”相符。", "天使": "语义：天使善良，与“骗光了老人的钱”矛盾。", "好人": "语义：“好人”与“骗子”的身份矛盾。", "小猫": "搭配：“是个……”后的名词要能指人，“小猫”不能是骗子。"}, "sentence_index": 6, "correct_answer": "魔鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个人是一棵魔鬼，偷光了村里人的粮食。", "explanation": "这里应该用〈个〉。“棵”用于植物，指人要用“个”。"}, {"text": "这个商人是一条魔鬼，专门骗穷人。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，指人要用“个”。"}, {"text": "那个老板是一块魔鬼，欺负了很多工人。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，指人要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人简直是个一魔鬼，常常欺负弱小的孩子。", "corrected_sentence": "那个人简直是一个魔鬼，常常欺负弱小的孩子。", "error_description": "语序错误：数量短语应说“一个”，不能说“个一”，应把“个一”改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个老板是一颗魔鬼，工人们都很害怕他。", "corrected_sentence": "那个老板是个魔鬼，工人们都很害怕他。", "error_description": "量词错误：“颗”用于颗粒状的东西，指人要用“个”，应把“颗”改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
