INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "事前", "is_correct": true, "explanation": "反义：“事前”指事情发生之前，与“事后”表示的先后顺序相对。"}, {"text": "冬天", "is_correct": false, "explanation": "无反义关系：“冬天”是季节，与事情的先后无关。"}, {"text": "书包", "is_correct": false, "explanation": "无反义关系：“书包”是物品，不表示时间先后。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：“河流”是地理事物，与“事后”无关。"}], "correct_answer": "事前", "explanations": {"事前": "反义：“事前”指事情发生之前，与“事后”表示的先后顺序相对。", "冬天": "无反义关系：“冬天”是季节，与事情的先后无关。", "书包": "无反义关系：“书包”是物品，不表示时间先后。", "河流": "无反义关系：“河流”是地理事物，与“事后”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
