INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情做完了以后。", "primary_collocate": null, "pronunciation": "shì hòu", "ipa": "ʂɻ̩˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "事后他才告诉我，这件事是他做的。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后想一想，我觉得自己说得太多了。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后他很后悔，不该那样说。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后我请他吃了一顿饭，谢谢他帮忙。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他事后才知道，那天的会已经取消了。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时他不说话，事后却提了很多意见。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动很成功，事后大家一起吃了饭。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错事不要紧，事后要说声对不起。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后我才想起来，那天忘了关门。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他事后给每个人都打了电话，说明情况。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "事後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某件事做完之后的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：事后（shì hòu）指事情做完了以后。"}, {"text": "时候", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，hou 为轻声，意思是“时候”。"}, {"text": "伺候", "is_correct": false, "explanation": "sì 与 shì 声母不同（s/sh），hou 为轻声，意思是“伺候”。"}, {"text": "事故", "is_correct": false, "explanation": "声母混淆：gù（第四声）与 hòu（第四声）仅声母不同（g/h），意思是“事故”。"}], "explanations": {"事后": "正确：事后（shì hòu）指事情做完了以后。", "时候": "shí（第二声）与 shì（第四声）声调不同，hou 为轻声，意思是“时候”。", "伺候": "sì 与 shì 声母不同（s/sh），hou 为轻声，意思是“伺候”。", "事故": "声母混淆：gù（第四声）与 hòu（第四声）仅声母不同（g/h），意思是“事故”。"}, "sentence_index": null, "correct_answer": "事后"}, "level_3": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：“事后”指事情做完之后，与“才告诉我”的先后顺序相合。"}, {"text": "事前", "is_correct": false, "explanation": "语义：“事前”指事情发生之前，与“才告诉我”的先后顺序矛盾。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”指某时点以前，与“才告诉我”的时间顺序矛盾。"}, {"text": "赛后", "is_correct": false, "explanation": "搭配：“赛后”限用于比赛结束之后，不能用于一般事情。"}], "explanations": {"事后": "正确：“事后”指事情做完之后，与“才告诉我”的先后顺序相合。", "事前": "语义：“事前”指事情发生之前，与“才告诉我”的先后顺序矛盾。", "之前": "语义：“之前”指某时点以前，与“才告诉我”的时间顺序矛盾。", "赛后": "搭配：“赛后”限用于比赛结束之后，不能用于一般事情。"}, "sentence_index": 0, "correct_answer": "事后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事后我们还没开始准备。", "explanation": "这里应该用〈事前〉。事后指事情做完之后，“还没开始准备”说明事情尚未展开，不能用事后。"}, {"text": "事后我们要先确定好活动时间。", "explanation": "这里应该用〈事先〉。事后指事情完成之后，确定安排应在事前，不能说事后。"}, {"text": "我们应该事后预先通知大家。", "explanation": "这里应该用〈预先〉。事后指事情结束之后，而通知大家应在事情发生之前提前进行，不能说事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：事后（shì hòu）指事情做完了以后。"}, {"text": "侍候", "is_correct": false, "explanation": "hou（轻声）与 hòu（第四声）声调不同，意思是“侍候”。"}, {"text": "是否", "is_correct": false, "explanation": "fǒu（第三声）与 hòu（第四声）声母不同（f/h），意思是“是否”。"}, {"text": "日后", "is_correct": false, "explanation": "rì 与 shì 声母不同（r/sh），意思是“日后”。"}], "explanations": {"事后": "正确：事后（shì hòu）指事情做完了以后。", "侍候": "hou（轻声）与 hòu（第四声）声调不同，意思是“侍候”。", "是否": "fǒu（第三声）与 hòu（第四声）声母不同（f/h），意思是“是否”。", "日后": "rì 与 shì 声母不同（r/sh），意思是“日后”。"}, "sentence_index": null, "correct_answer": "事后"}, "level_3": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：“事后”指事情做完之后，与“大家一起吃了饭”的先后顺序相合。"}, {"text": "赛前", "is_correct": false, "explanation": "搭配：“赛前”限用于比赛，不能说活动的赛前。"}, {"text": "饭前", "is_correct": false, "explanation": "语义：“饭前”指进餐之前，与句中“大家一起吃了饭”矛盾。"}, {"text": "课前", "is_correct": false, "explanation": "语义：“课前”指上课之前，与“活动很成功”的语境不合。"}], "explanations": {"事后": "正确：“事后”指事情做完之后，与“大家一起吃了饭”的先后顺序相合。", "赛前": "搭配：“赛前”限用于比赛，不能说活动的赛前。", "饭前": "语义：“饭前”指进餐之前，与句中“大家一起吃了饭”矛盾。", "课前": "语义：“课前”指上课之前，与“活动很成功”的语境不合。"}, "sentence_index": 6, "correct_answer": "事后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一边跑步，事后一边听音乐。", "explanation": "这里应该用〈同时〉。事后指事情完成之后，不能用于两件事同时进行。"}, {"text": "我事后想当一名医生。", "explanation": "这里应该用〈以后〉。事后指事情已经完成之后，不用于对将来的打算。"}, {"text": "事后，他一直在场边热身。", "explanation": "这里应该用〈期间〉。事后指事情结束之后，“一直在场边热身”发生在比赛进行中，不能用事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事后以后我才想到，应该先打个电话。", "corrected_sentence": "事后我才想到，应该先打个电话。", "error_description": "错误：“事后”本身已表示事情完成之后，后面不能再加“以后”。正确为“事后我才想到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚会结束，事后了我们一起去了餐厅。", "corrected_sentence": "晚会结束，事后我们一起去了餐厅。", "error_description": "错误：“事后”是时间名词，后面不能直接加“了”。正确为“事后我们一起去了餐厅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
