INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生或结束之后。", "primary_collocate": null, "pronunciation": "shì hòu", "ipa": "ʂɻ̩˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "火灾的事后调查花了很长时间。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后检查很重要，能让我们发现问题。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次事故很严重，事后公司检查了所有设备。", "target_word": "事后", "complexity_tier": "T3", "furigana": "shì hòu", "sentence_source": "generated"}, {"text": "出了问题，事后再后悔就来不及了。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后，警察问了在场的每一个人。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不愿意事先说明，只想事后解释。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起事后补救，事前准备更重要。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事处理得不好，事后大家都在议论。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事后他向公司写了一份说明。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议很顺利，事后领导还表扬了我们。", "target_word": "事后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "事後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事件发生或结束之后，常与事前、事先相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a815514-4d7f-4238-8b45-1947406c3be3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97564, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：事后（shì hòu）指事件发生或结束之后。"}, {"text": "侍候", "is_correct": false, "explanation": "hou（轻声）与 hòu（第四声）声调不同，意思是“侍候”。"}, {"text": "是否", "is_correct": false, "explanation": "fǒu（第三声）与 hòu（第四声）声母不同（f/h），意思是“是否”。"}, {"text": "日后", "is_correct": false, "explanation": "rì 与 shì 声母不同（r/sh），意思是“日后”。"}], "explanations": {"事后": "正确：事后（shì hòu）指事件发生或结束之后。", "侍候": "hou（轻声）与 hòu（第四声）声调不同，意思是“侍候”。", "是否": "fǒu（第三声）与 hòu（第四声）声母不同（f/h），意思是“是否”。", "日后": "rì 与 shì 声母不同（r/sh），意思是“日后”。"}, "sentence_index": null, "correct_answer": "事后"}, "level_3": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：“事后调查”指事件结束之后进行的调查，与“火灾”的语境相合。"}, {"text": "赛后", "is_correct": false, "explanation": "搭配：“赛后”多指比赛结束之后，不用于火灾事件。"}, {"text": "课后", "is_correct": false, "explanation": "语义：“课后”指下课之后，与“火灾”的语境毫不相关。"}, {"text": "饭后", "is_correct": false, "explanation": "语义：“饭后”指饭后的时间，与“火灾的调查”不符。"}], "explanations": {"事后": "正确：“事后调查”指事件结束之后进行的调查，与“火灾”的语境相合。", "赛后": "搭配：“赛后”多指比赛结束之后，不用于火灾事件。", "课后": "语义：“课后”指下课之后，与“火灾”的语境毫不相关。", "饭后": "语义：“饭后”指饭后的时间，与“火灾的调查”不符。"}, "sentence_index": 0, "correct_answer": "事后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该事后做好准备。", "explanation": "这里应该用〈事先〉。做准备必须在事情发生之前，事后不能用于准备。"}, {"text": "事后预报天气比什么都重要。", "explanation": "这里应该用〈事前〉。预报天气要在天气变化之前进行，事后预报没有意义，事后不能与预报搭配。"}, {"text": "我们明年事后再去北京。", "explanation": "这里应该用〈以后〉。事后指某件事发生或结束之后，不能用于“明年”这样尚未发生的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97564, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：事后（shì hòu）指事件发生或结束之后。"}, {"text": "时候", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，hou 为轻声，意思是“时候”。"}, {"text": "伺候", "is_correct": false, "explanation": "sì 与 shì 声母不同（s/sh），hou 为轻声，意思是“伺候”。"}, {"text": "事故", "is_correct": false, "explanation": "声母混淆：gù（第四声）与 hòu（第四声）仅声母不同（g/h），意思是“事故”。"}], "explanations": {"事后": "正确：事后（shì hòu）指事件发生或结束之后。", "时候": "shí（第二声）与 shì（第四声）声调不同，hou 为轻声，意思是“时候”。", "伺候": "sì 与 shì 声母不同（s/sh），hou 为轻声，意思是“伺候”。", "事故": "声母混淆：gù（第四声）与 hòu（第四声）仅声母不同（g/h），意思是“事故”。"}, "sentence_index": null, "correct_answer": "事后"}, "level_3": {"options": [{"text": "事后", "is_correct": true, "explanation": "正确：“事后补救”指事件发生之后的补救，与“事前准备”形成对照。"}, {"text": "病后", "is_correct": false, "explanation": "搭配：“病后”指病愈之后，不能与“补救”搭配。"}, {"text": "产后", "is_correct": false, "explanation": "搭配：“产后”指分娩之后，不能说“产后补救”。"}, {"text": "雨后", "is_correct": false, "explanation": "语义：“雨后”指下雨之后，与“补救”的人为事件语境不合。"}], "explanations": {"事后": "正确：“事后补救”指事件发生之后的补救，与“事前准备”形成对照。", "病后": "搭配：“病后”指病愈之后，不能与“补救”搭配。", "产后": "搭配：“产后”指分娩之后，不能说“产后补救”。", "雨后": "语义：“雨后”指下雨之后，与“补救”的人为事件语境不合。"}, "sentence_index": 6, "correct_answer": "事后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事后，我们一直在记笔记。", "explanation": "这里应该用〈期间〉。事后指事情结束之后，“一直在记笔记”发生在培训进行中，不能用事后。"}, {"text": "她一边开车，事后一边接电话。", "explanation": "这里应该用〈同时〉。事后指事情完成之后，不能用于两件事同时进行。"}, {"text": "他事后当场向大家道歉。", "explanation": "这里应该用〈当场〉。事后指事情结束之后，“当场”指事情发生的当时，两者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事已经发生，很事后补救还来得及。", "corrected_sentence": "这件事已经发生，事后补救还来得及。", "error_description": "错误：“事后”是时间名词，不能受程度副词“很”修饰。正确为“事后补救还来得及”，“事后”直接修饰“补救”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事后了，他向公司写了一封信。", "corrected_sentence": "事后，他向公司写了一封信。", "error_description": "错误：“事后”是时间名词，后面不能加“了”。正确为“事后，他向公司写了一封信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c1d4ff8-68a2-4e52-9644-ad8a9a8ade8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
