INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发脾气，闹别扭。", "primary_collocate": null, "pronunciation": "shǐ xìng", "ipa": "ʂɻ̩˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子不高兴的时候总爱使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跟妈妈使性，快过来吃饭。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一不如意就使性，大家都怕她。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在门口使性，不肯进屋。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是不想去，就直说，不要使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架后，她一直在使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿使性不吃早饭，妈妈很着急。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李有点儿使性，说话也不看我。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱使性的人，朋友会越来越少。", "target_word": "使性", "complexity_tier": "T3", "furigana": "ài shǐxìng de rén péngyou huì yuè lái yuè shǎo", "sentence_source": "generated"}, {"text": "小明又在使性了，谁也哄不好。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "使性子", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词：因不满而闹别扭、赌气，不肯配合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使性", "is_correct": true, "explanation": "使性：因不满而闹别扭、赌气，为正确答案。"}, {"text": "实行", "is_correct": false, "explanation": "shí xíng 与 shǐ xìng 声调不同，意思是实施、推行。"}, {"text": "试行", "is_correct": false, "explanation": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。"}, {"text": "时兴", "is_correct": false, "explanation": "shí xīng 与 shǐ xìng 声调不同，意思是一时流行。"}, {"text": "死性", "is_correct": false, "explanation": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}, {"text": "驶行", "is_correct": false, "explanation": "shǐ xíng 与 shǐ xìng 第二音节声调不同，意思是车船行驶。"}], "explanations": {"使性": "使性：因不满而闹别扭、赌气，为正确答案。", "实行": "shí xíng 与 shǐ xìng 声调不同，意思是实施、推行。", "试行": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。", "时兴": "shí xīng 与 shǐ xìng 声调不同，意思是一时流行。", "死性": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。", "驶行": "shǐ xíng 与 shǐ xìng 第二音节声调不同，意思是车船行驶。"}, "sentence_index": null, "correct_answer": "使性"}, "level_3": {"options": [{"text": "使性", "is_correct": true, "explanation": "正确：“总爱使性”指孩子不高兴时闹别扭，符合语境。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：孩子“不高兴”时“总爱微笑”自相矛盾，不符合语境。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：“大笑”与“不高兴”的语境相反，不能说孩子不高兴时总爱大笑。"}, {"text": "赞许", "is_correct": false, "explanation": "语域：“赞许”是书面语，口语中不用；且“孩子不高兴的时候总爱赞许”语义说不通。"}], "explanations": {"使性": "正确：“总爱使性”指孩子不高兴时闹别扭，符合语境。", "微笑": "语义：孩子“不高兴”时“总爱微笑”自相矛盾，不符合语境。", "大笑": "语义：“大笑”与“不高兴”的语境相反，不能说孩子不高兴时总爱大笑。", "赞许": "语域：“赞许”是书面语，口语中不用；且“孩子不高兴的时候总爱赞许”语义说不通。"}, "sentence_index": 0, "correct_answer": "使性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他冻得浑身直使性。", "explanation": "这里应该用〈发抖〉。使性指发脾气、闹别扭，不表示身体因寒冷而颤抖。"}, {"text": "我们听到这个好消息，都很使性。", "explanation": "这里应该用〈高兴〉。使性指发脾气，与听到好消息时的高兴相反，前后意思矛盾。"}, {"text": "我们明天去使性办签证。", "explanation": "这里应该用〈使馆〉。使性是动词，不表示地点，“去使馆办签证”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "使性", "is_correct": true, "explanation": "使性：因不满而闹别扭、赌气，为正确答案。"}, {"text": "食性", "is_correct": false, "explanation": "shí xìng 与 shǐ xìng 声调不同，意思是动物的食物习性。"}, {"text": "施行", "is_correct": false, "explanation": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。"}, {"text": "室性", "is_correct": false, "explanation": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。"}, {"text": "死性", "is_correct": false, "explanation": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}], "explanations": {"使性": "使性：因不满而闹别扭、赌气，为正确答案。", "食性": "shí xìng 与 shǐ xìng 声调不同，意思是动物的食物习性。", "施行": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。", "室性": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。", "死性": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}, "sentence_index": null, "correct_answer": "使性"}, "level_3": {"options": [{"text": "使性", "is_correct": true, "explanation": "正确：“女儿使性不吃早饭”指女儿闹别扭、发脾气，符合语境。"}, {"text": "吃饱", "is_correct": false, "explanation": "语义：“吃饱”与“不吃早饭”自相矛盾，不符合语境。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”需要感激的对象，“女儿感激不吃早饭”说不通。"}, {"text": "嘉许", "is_correct": false, "explanation": "语域：“嘉许”是书面语，口语中少用；且“嘉许不吃早饭”语义也不通。"}], "explanations": {"使性": "正确：“女儿使性不吃早饭”指女儿闹别扭、发脾气，符合语境。", "吃饱": "语义：“吃饱”与“不吃早饭”自相矛盾，不符合语境。", "感激": "配价：“感激”需要感激的对象，“女儿感激不吃早饭”说不通。", "嘉许": "语域：“嘉许”是书面语，口语中少用；且“嘉许不吃早饭”语义也不通。"}, "sentence_index": 6, "correct_answer": "使性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的使性是保护这片森林。", "explanation": "这里应该用〈使命〉。使性指发脾气、闹别扭，不能表示任务、职责。"}, {"text": "他是政府派往外国的使性。", "explanation": "这里应该用〈使节〉。使性不指人，更不表示外交人员。"}, {"text": "这是环境使性。", "explanation": "这里应该用〈使然〉。使性是发脾气，不能表示“由于某种原因而造成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一不高兴就使性我，谁也劝不住。", "corrected_sentence": "他一不高兴就使性，谁也劝不住。", "error_description": "错误形式：“使性我”；正确形式：“使性”后不带宾语，表示对象时说“对我使性”。原因：“使性”是动宾式离合词，宾语不能直接放在它后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她以前也使性过，现在好多了。", "corrected_sentence": "她以前也使过性，现在好多了。", "error_description": "错误形式：“使性过”；正确形式：“使过性”。“过”要放在离合词的动词“使”与宾语“性”之间，“使性过”不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
