INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耍脾气；发火。", "primary_collocate": null, "pronunciation": "shǐ xìng", "ipa": "ʂɻ̩˨˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经理对客人使性，被老板批评了。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有话好好说，不要对同事使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太累，回家就对孩子使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听这话就使性，把门关上了。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，他在车里直使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别因为小事就使性，对身体不好。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天心情不好，动不动就使性。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当着大家的面使性，真让人为难。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一使性，就摔了杯子。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢跟爱使性的人一起工作。", "target_word": "使性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "使性子", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词：对人耍脾气、发火，常带“对／跟”引出对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
