 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "使性", "is_correct": true, "explanation": "使性：对人发脾气、发火，为正确答案。"}, {"text": "试行", "is_correct": false, "explanation": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。"}, {"text": "施行", "is_correct": false, "explanation": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。"}, {"text": "室性", "is_correct": false, "explanation": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。"}, {"text": "死性", "is_correct": false, "explanation": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}], "explanations": {"使性": "使性：对人发脾气、发火，为正确答案。", "试行": "shì xíng 与 shǐ xìng 声调不同，意思是先试验性地施行。", "施行": "shī xíng 与 shǐ xìng 声调不同，意思是实施、施行。", "室性": "shì xìng 与 shǐ xìng 声调不同，意思是与心室有关（医学用语）。", "死性": "sǐ xìng 与 shǐ xìng 声母不同（s 与 sh），意思是死板、固执的性情。"}, "sentence_index": null, "correct_answer": "使性"}, "level_3": {"options": [{"text": "使性", "is_correct": true, "explanation": "正确：“老板动不动就使性”指老板时常发脾气，符合语境。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：老板心情不好时“动不动就微笑”自相矛盾，不符合语境。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：“欢呼”表示高兴，与“心情不好”相反，不符合语境。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：“嘉奖”是书面语，口语中不用；且与“心情不好、动不动就”的语境不合。"}], "explanations": {"使性": "正确：“老板动不动就使性”指老板时常发脾气，符合语境。", "微笑": "语义：老板心情不好时“动不动就微笑”自相矛盾，不符合语境。", "欢呼": "语义：“欢呼”表示高兴，与“心情不好”相反，不符合语境。", "嘉奖": "语域：“嘉奖”是书面语，口语中不用；且与“心情不好、动不动就”的语境不合。"}, "sentence_index": 6, "correct_answer": "使性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是天神派来的使性。", "explanation": "这里应该用〈使者〉。使性是发脾气，不指人或身份。"}, {"text": "这次谈判，他作为使性出席。", "explanation": "这里应该用〈使节〉。使性不指外交人员，也不能表示“作为代表出席”。"}, {"text": "他常去使性处理手续。", "explanation": "这里应该用〈使馆〉。使性不表示地点，“去使馆处理手续”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向我使性，把门关上了。", "corrected_sentence": "他对我使性，把门关上了。", "error_description": "错误形式：“向我使性”；正确形式：“对我使性”。使性表示对人发脾气，引出对象须用介词“对”，“向”不能这样搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前天对我使性过，现在道歉了。", "corrected_sentence": "他前天对我使过性，现在道歉了。", "error_description": "错误形式：“使性过”；正确形式：“使过性”。“过”须放在离合词的动词“使”与宾语“性”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
