INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做同样的事、走同一条路的人。", "primary_collocate": null, "pronunciation": "tóng dào", "ipa": "tʰʊŋ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "山路很长，我们是同道，一起走吧。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在登山的路上遇到了一位同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我是同道，每天都走这条路。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这条路上，我找到了几位同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张和我是多年的同道，都走过这条山路。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走这条路的人不多，同道更少。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们既是朋友，又是同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去西藏的路上认识了不少同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是同道，一起走过二十年的山路。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上有很多同道，大家互相帮助。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位同道", "label": "量词"}], "register": "书面语", "sense_fingerprint": "走同一条路、做同样事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同道", "is_correct": true, "explanation": "正确：「我们是同道，一起走吧」表示走同一条路的人，与一起走的语境相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：「对手」表示竞争的一方，与「一起走吧」的合作语境相反。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：「敌人」表示敌对的人，与「一起走吧」的合作语境相反。"}, {"text": "罪犯", "is_correct": false, "explanation": "语义：「罪犯」与「一起走吧」的结伴邀约不符，一般不会邀请罪犯同行。"}], "explanations": {"同道": "正确：「我们是同道，一起走吧」表示走同一条路的人，与一起走的语境相符。", "对手": "语义：「对手」表示竞争的一方，与「一起走吧」的合作语境相反。", "敌人": "语义：「敌人」表示敌对的人，与「一起走吧」的合作语境相反。", "罪犯": "语义：「罪犯」与「一起走吧」的结伴邀约不符，一般不会邀请罪犯同行。"}, "sentence_index": 0, "correct_answer": "同道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和哥哥是同道，都是二十岁。", "explanation": "这里应该用〈同龄〉。「同道」指做同样的事或走同一条路的人，不指年龄相同，要说「同龄」。"}, {"text": "这两个孩子是同道，都在一年级。", "explanation": "这里应该用〈同班〉。「同道」不指同一年级或同一班级的人，要说「同班」。"}, {"text": "这两道题是同道，答案一样。", "explanation": "这里应该用〈同类〉。「同道」只指人，不指题目，这两道题要说「同类」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同道", "is_correct": true, "explanation": "正确：「既是朋友，又是同道」表示既是朋友，又是走同一条路、做同样事情的人，语义通顺。"}, {"text": "猫", "is_correct": false, "explanation": "语义：「猫」是动物，不能与「朋友」并列作身份，句意不通。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：「乞丐」与「朋友」并列的身份说明不合常理，句意不通。"}, {"text": "路人", "is_correct": false, "explanation": "语义：「路人」指与自己没有关系的人，与「既是朋友」的说法矛盾。"}], "explanations": {"同道": "正确：「既是朋友，又是同道」表示既是朋友，又是走同一条路、做同样事情的人，语义通顺。", "猫": "语义：「猫」是动物，不能与「朋友」并列作身份，句意不通。", "乞丐": "语义：「乞丐」与「朋友」并列的身份说明不合常理，句意不通。", "路人": "语义：「路人」指与自己没有关系的人，与「既是朋友」的说法矛盾。"}, "sentence_index": 6, "correct_answer": "同道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩是同道，都姓王。", "explanation": "这里应该用〈同姓〉。「同道」指做同样的事或走同一条路的人，不指姓氏相同的人。"}, {"text": "这两棵树是同道，都长在山坡上。", "explanation": "这里应该用〈同种〉。「同道」只指人，不用来形容植物，要说「同种」。"}, {"text": "这两个包是同道，颜色一样。", "explanation": "这里应该用〈同款〉。「同道」只指人，不指物品，要说「同款」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在路上遇到了一只同道。", "corrected_sentence": "我在路上遇到了一位同道。", "error_description": "错误：「一只同道」用了量词「只」。正确：「同道」指人，量词应用「位」，「只」多用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很同道，常常一起走这条路。", "corrected_sentence": "他们是同道，常常一起走这条路。", "error_description": "错误：「很同道」用副词「很」修饰「同道」。正确：「同道」作谓语要用系动词「是」，应说「他们是同道」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
