INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "志趣相同的人；同行。", "primary_collocate": null, "pronunciation": "tóng dào", "ipa": "tʰʊŋ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "在这个小组里，我遇到了很多同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱读书的人总能找到同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多爱摄影的同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很高兴在会上认识了几位同道。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和同道聊天，时间过得特别快。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找几位同道一起做公益。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是同道，常常一起切磋。", "target_word": "同道", "complexity_tier": "T3", "furigana": "tāmen shì tóngdào, chángcháng yìqǐ qiēcuō.", "sentence_source": "generated"}, {"text": "这位老师是我的同道，我们都爱京剧。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，同道们互相分享了经验。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你也喜欢画画？那我们是同道了。", "target_word": "同道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位同道", "label": "量词"}], "register": "书面语", "sense_fingerprint": "志趣相投的人、同行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同道", "is_correct": true, "explanation": "正确：「在这个小组里，我遇到了很多同道」表示志趣相同的人，与小组的语境相符。"}, {"text": "路人", "is_correct": false, "explanation": "语义：「路人」指与自己没有关系的人，不在小组里，与「在这个小组里」的语境不符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：「乘客」指乘车的人，与「在这个小组里」的语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」不是人，不能在小组中「遇到」。"}], "explanations": {"同道": "正确：「在这个小组里，我遇到了很多同道」表示志趣相同的人，与小组的语境相符。", "路人": "语义：「路人」指与自己没有关系的人，不在小组里，与「在这个小组里」的语境不符。", "乘客": "语义：「乘客」指乘车的人，与「在这个小组里」的语境不符。", "窗户": "语义：「窗户」不是人，不能在小组中「遇到」。"}, "sentence_index": 0, "correct_answer": "同道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很高兴在会上认识了几张同道的票。", "explanation": "这里应该用〈票〉。「同道」只指人，不指票，「几张票」前不能用「同道」修饰。"}, {"text": "他很高兴在会上认识了几张同道的照片。", "explanation": "这里应该用〈照片〉。「同道」只指人，不指照片，要说「几张照片」。"}, {"text": "他很高兴在会上认识了几座同道的山。", "explanation": "这里不能用〈同道〉指山，「同道」只指人，应直接说「几座山」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同道", "is_correct": true, "explanation": "正确：「他们是同道，常常一起切磋」表示志趣相同、可以互相切磋的人，与句意相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：「陌生人」与「常常一起切磋」的熟悉往来语境矛盾。"}, {"text": "窃贼", "is_correct": false, "explanation": "语义：「窃贼」与「一起切磋」的交流语境完全不合。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：「乞丐」与「一起切磋」的学问交流语境不合，句意不通。"}], "explanations": {"同道": "正确：「他们是同道，常常一起切磋」表示志趣相同、可以互相切磋的人，与句意相符。", "陌生人": "语义：「陌生人」与「常常一起切磋」的熟悉往来语境矛盾。", "窃贼": "语义：「窃贼」与「一起切磋」的交流语境完全不合。", "乞丐": "语义：「乞丐」与「一起切磋」的学问交流语境不合，句意不通。"}, "sentence_index": 6, "correct_answer": "同道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你也是我的同桌？那我们是同道了。", "explanation": "这里应该用〈同桌〉。「同道」指志趣相同或做同样事情的人，「同桌」指同坐一张桌的同学。"}, {"text": "你也姓李？那我们是同道了。", "explanation": "这里应该用〈同姓〉。「同道」指志趣相同或同行的人，不指姓氏相同，同姓要说「同姓」。"}, {"text": "你也住我们宿舍？那我们是同道了。", "explanation": "这里应该用〈室友〉。「同道」不指住在同一宿舍的人，「室友」才是同住的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他认识了一只同道。", "corrected_sentence": "他认识了一位同道。", "error_description": "错误：「一只同道」用了量词「只」。正确：「同道」指人，量词应用「位」，「只」多用于动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他也是同道着。", "corrected_sentence": "他也是同道了。", "error_description": "错误：「同道」作谓语后用了「着」，不合语法。正确：表示「成为同道」这一变化要用「了」，应说「他也是同道了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
