INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卖东西给大家的人家或店。", "primary_collocate": null, "pronunciation": "shāng jiā", "ipa": "ʂaŋ˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这个商家的东西很便宜。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家今天打折，我买了两件衣服。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家把东西送到了我家。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商家卖的水果很新鲜。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家在门口放着一张大海报。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，很多商家都不休息。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问商家能不能便宜一点。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家说这件衣服没有别的颜色。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上找了一个商家。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家为了卖东西，把价格降低了。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个商家", "label": "量词"}], "register": "中性", "sense_fingerprint": "卖东西给顾客的人家或店铺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商家", "is_correct": true, "explanation": "商家指卖东西给顾客的人家或店，“这个商家的东西很便宜”符合句意。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是买东西的人，不卖东西，与“东西很便宜”的卖方立场冲突。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷偷来东西，不是正常卖东西的人，与句意不符。"}, {"text": "警察", "is_correct": false, "explanation": "搭配：警察不卖东西，“东西很便宜”的说法不搭配警察。"}], "explanations": {"商家": "商家指卖东西给顾客的人家或店，“这个商家的东西很便宜”符合句意。", "顾客": "语义：顾客是买东西的人，不卖东西，与“东西很便宜”的卖方立场冲突。", "小偷": "语义：小偷偷来东西，不是正常卖东西的人，与句意不符。", "警察": "搭配：警察不卖东西，“东西很便宜”的说法不搭配警察。"}, "sentence_index": 0, "correct_answer": "商家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件商家的颜色很漂亮，我很喜欢。", "explanation": "这里误把〈商家〉当成了〈商品〉。商家指卖东西的人或店，不指商品本身。"}, {"text": "这家商家专门生产汽车零件。", "explanation": "这里应该用〈厂家〉。商家指卖东西的人或店，负责生产的是厂家。"}, {"text": "这栋大楼是商家。", "explanation": "这里应该用〈商场〉。商家指经营买卖的人家或店，不指建筑物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商家", "is_correct": true, "explanation": "商家指卖东西的人家或店，“问商家能不能便宜一点”符合买卖情境。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不卖东西，问医生能不能便宜一点与句意不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能议价，“问桌子”不合常理。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是交易的对象，不能议价，“问太阳能不能便宜一点”不合常理。"}], "explanations": {"商家": "商家指卖东西的人家或店，“问商家能不能便宜一点”符合买卖情境。", "医生": "语义：医生不卖东西，问医生能不能便宜一点与句意不符。", "桌子": "语义：桌子不能议价，“问桌子”不合常理。", "太阳": "语义：太阳不是交易的对象，不能议价，“问太阳能不能便宜一点”不合常理。"}, "sentence_index": 6, "correct_answer": "商家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次商家很成功，大家都同意了。", "explanation": "这里误把〈商家〉当成了〈商量〉的意思。商家指卖东西的人或店，不指讨论。"}, {"text": "这把椅子是商家。", "explanation": "这里误把〈商家〉当成了〈家具〉。商家指卖东西的人或店，不是家具这样的物品。"}, {"text": "这首歌是商家，大家都很喜欢。", "explanation": "这里误把〈商家〉当成了〈歌曲〉。商家指经营买卖的人家或店，不指作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只商家的价格很合理。", "corrected_sentence": "这家商家的价格很合理。", "error_description": "错误在量词：商家是经营单位，应用〈家〉；〈只〉多用于动物或成对物件中的一个，不用于经营单位。正确说法是“这家商家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在商家一家买了两件衣服。", "corrected_sentence": "我在一家商家买了两件衣服。", "error_description": "错误在语序：数量词“一家”应放在名词“商家”之前。正确说法是“在一家商家买了两件衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
