INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出售商品或提供服务的店家。", "primary_collocate": null, "pronunciation": "shāng jiā", "ipa": "ʂaŋ˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这个商家提供送货服务。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家会帮你修手机。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家给客人准备了免费的茶。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商家的服务很好。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请商家开一张发票。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商品坏了，你可以找商家。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家在网上卖衣服，也提供送货。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家一般晚上十点关门。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多商家在节日做活动。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人对商家的服务很满意。", "target_word": "商家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个商家", "label": "量词"}], "register": "中性", "sense_fingerprint": "出售商品或提供服务的店家，强调服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商家", "is_correct": true, "explanation": "商家指出售商品或提供服务的店家，“提供送货服务”符合句意。"}, {"text": "顾客", "is_correct": false, "explanation": "配价：提供服务的主体不能是接受服务的人，顾客不能“提供”送货服务。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不提供正当服务，与“送货服务”的意思不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不提供服务，与句意不符。"}], "explanations": {"商家": "商家指出售商品或提供服务的店家，“提供送货服务”符合句意。", "顾客": "配价：提供服务的主体不能是接受服务的人，顾客不能“提供”送货服务。", "小偷": "语义：小偷不提供正当服务，与“送货服务”的意思不符。", "病人": "语义：病人不提供服务，与句意不符。"}, "sentence_index": 0, "correct_answer": "商家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个商家每天生产一千台电视机。", "explanation": "这里应该用〈厂家〉。商家指卖东西或提供服务的店家，生产产品的是厂家。"}, {"text": "这个商家明天要考试，所以很紧张。", "explanation": "这里误把〈商家〉当成了〈学生〉。商家指出售商品或提供服务的店家，不是参加考试的人。"}, {"text": "我的商家很喜欢吃饭。", "explanation": "这里误把〈商家〉当成了〈顾客〉。商家指提供商品或服务的一方，不是消费的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商家", "is_correct": true, "explanation": "商家指在网上卖衣服并提供送货的店家，“也提供送货”符合句意。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不卖衣服，句意不通。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不正当地卖衣服，与“提供送货”的正规服务不符。"}, {"text": "乞丐", "is_correct": false, "explanation": "搭配：乞丐没有衣服可卖，“卖衣服”不与其搭配。"}], "explanations": {"商家": "商家指在网上卖衣服并提供送货的店家，“也提供送货”符合句意。", "医生": "语义：医生不卖衣服，句意不通。", "小偷": "语义：小偷不正当地卖衣服，与“提供送货”的正规服务不符。", "乞丐": "搭配：乞丐没有衣服可卖，“卖衣服”不与其搭配。"}, "sentence_index": 6, "correct_answer": "商家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客人用这个商家开了门，很方便。", "explanation": "这里误把〈商家〉当成了〈钥匙〉。商家指出售商品或提供服务的店家，不是开门的工具。"}, {"text": "我们商家一下，然后决定去哪儿玩。", "explanation": "这里误把名词〈商家〉当成了动词〈商量〉。商家是名词，不能作动词用。"}, {"text": "我的商家是我最好的朋友，我们常一起玩。", "explanation": "这里误把〈商家〉当成了〈朋友〉。商家指经营的店家，不能说是最好的朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只商家提供送货服务。", "corrected_sentence": "这家商家提供送货服务。", "error_description": "错误在量词：商家是经营单位，应用〈家〉；〈只〉多用于动物或成对物件中的一个，不用于经营单位。正确说法是“这家商家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台商家今天打折了。", "corrected_sentence": "这个商家今天打折了。", "error_description": "错误在量词：〈台〉多用于机器、电器，不用于商家这类经营单位；正确说法是“这个商家今天打折了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
