INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家的人，大家都是这个国家的人。", "primary_collocate": null, "pronunciation": "guó rén", "ipa": "kwo˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "国人都很爱自己的国家。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时，国人都会回老家。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人对这件事都很关心。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人的生活越来越好了。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好消息让国人都很高兴。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人一起看着比赛，大声喊加油。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写给国人看，大家都能懂。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人都希望国家越来越好。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体国人都在等这个结果。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人过年时都爱吃饺子。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个国家的全体人民，强调大家是一体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指一个国家的全体人民，“都很爱自己的国家”指向这一群体，符合句意。"}, {"text": "国土", "is_correct": false, "explanation": "语义：国土是领土，不会爱自己的国家，句意不通。"}, {"text": "国歌", "is_correct": false, "explanation": "语义：国歌是一首歌，不是人，不能“爱自己的国家”。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“爱”的主体须是有感情的人，国籍不能作这样的主语。"}], "explanations": {"国人": "国人指一个国家的全体人民，“都很爱自己的国家”指向这一群体，符合句意。", "国土": "语义：国土是领土，不会爱自己的国家，句意不通。", "国歌": "语义：国歌是一首歌，不是人，不能“爱自己的国家”。", "国籍": "搭配：“爱”的主体须是有感情的人，国籍不能作这样的主语。"}, "sentence_index": 0, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国人是法国，却在中国工作。", "explanation": "这里应该用〈国籍〉。国人指同一国家的人民，不能用来说明一个人的国籍。"}, {"text": "这座城市就是国人。", "explanation": "这里误把〈国人〉当成了〈国家〉。国人指人民，不指国土或地域。"}, {"text": "这家公司的国人产品很受欢迎。", "explanation": "这里应该用〈国产〉。国人是名词，指人，不能修饰产品表示国内生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指本国的全体人民，“写给国人看，大家都能懂”指向读者群，符合句意。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物无法读懂人类文字，与“大家都能懂”冲突。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不是读者，写给机器看，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“看”需要能看的主体作对象，石头不能作阅读对象。"}], "explanations": {"国人": "国人指本国的全体人民，“写给国人看，大家都能懂”指向读者群，符合句意。", "动物": "语义：动物无法读懂人类文字，与“大家都能懂”冲突。", "机器": "语义：机器不是读者，写给机器看，句意不通。", "石头": "配价：“看”需要能看的主体作对象，石头不能作阅读对象。"}, "sentence_index": 6, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头是国人。", "explanation": "这里误把〈国人〉当成了〈国宝〉。国人指人民群体，不能指珍贵的物品。"}, {"text": "我每天早上喝一杯国人。", "explanation": "这里误把〈国人〉当成了〈饮料〉。国人指人，不是饮品。"}, {"text": "这幅国人很有名，是齐白石画的。", "explanation": "这里误把〈国人〉当成了〈国画〉。国人指人，不指绘画作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块国人都在关心这次比赛。", "corrected_sentence": "这群国人都在关心这次比赛。", "error_description": "错误在量词：指一群人应用〈群〉，〈块〉用于块状的东西，不能修饰国人。正确说法是“这群国人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在车站看见了一只国人。", "corrected_sentence": "我在车站看见了一位国人。", "error_description": "错误在量词：指人应用〈位〉或〈个〉，〈只〉一般不用于指人。正确说法是“一位国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
