INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本国的人；同一国家的人民。", "primary_collocate": null, "pronunciation": "guó rén", "ipa": "kwo˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "在国外，我遇到了很多国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客人大多是国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外生活，常和国人聚会。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，国人要带好护照。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方国人很少来，游客很多。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人出国旅游的越来越多。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店只卖东西给国人。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国人去那个国家不用办签证。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教国人学外语。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的朋友问国人爱吃什么。", "target_word": "国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "本国的人，与外国人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指同一国家的人，与“在国外遇到”的语境相符。"}, {"text": "国王", "is_correct": false, "explanation": "语义：国王是君主，“在国外遇到很多国王”不合常理，与国人的人民之义不符。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“遇到”的对象应是人，不能说遇到很多国籍。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是证件，不是人，不能与“遇到很多”搭配。"}], "explanations": {"国人": "国人指同一国家的人，与“在国外遇到”的语境相符。", "国王": "语义：国王是君主，“在国外遇到很多国王”不合常理，与国人的人民之义不符。", "国籍": "搭配：“遇到”的对象应是人，不能说遇到很多国籍。", "护照": "语义：护照是证件，不是人，不能与“遇到很多”搭配。"}, "sentence_index": 0, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国人是美国，但他长期在中国生活。", "explanation": "这里应该用〈国籍〉。国人指同一国家的人民，不能用来说明一个人的国籍。"}, {"text": "这台电脑是国人。", "explanation": "这里误把〈国人〉当成了〈国货〉的意思。国人指同一国家的人，不指物品；国产的物品称为“国货”。"}, {"text": "我们学校有很多国人学生，他们来自法国、德国和巴西。", "explanation": "这里应该用〈国际〉。国人指本国的人，学生来自不同国家时应说“国际学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国人", "is_correct": true, "explanation": "国人指本国的人，“只卖东西给”的对象是本国顾客，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能成为买东西的对象。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“卖给”需要能接受交易的人作受事，空气不能作这样的对象。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不是可以买东西的人，句意不通。"}], "explanations": {"国人": "国人指本国的人，“只卖东西给”的对象是本国顾客，符合句意。", "桌子": "语义：桌子不是人，不能成为买东西的对象。", "空气": "配价：“卖给”需要能接受交易的人作受事，空气不能作这样的对象。", "汽车": "语义：汽车是交通工具，不是可以买东西的人，句意不通。"}, "sentence_index": 6, "correct_answer": "国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国人很大，人口超过十亿。", "explanation": "这里应该用〈国家〉。国人指人，不指国土或人口所在的国家。"}, {"text": "我们住在一个国人里。", "explanation": "国人是指人群，不是可以居住的地方，这里应说“在国内”或“在这个国家”。"}, {"text": "国人是一种很好吃的水果。", "explanation": "这里误把〈国人〉当成了〈国光〉（一种苹果的名称）。国人指同一国家的人，不是水果的名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在火车上遇到了一只国人。", "corrected_sentence": "我在火车上遇到了一位国人。", "error_description": "错误在量词：指人应用〈位〉或〈个〉，〈只〉一般不用于指人。正确说法是“一位国人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店对这张国人很热情。", "corrected_sentence": "这家商店对这位国人很热情。", "error_description": "错误在量词：指人应用〈位〉或〈个〉，〈张〉用于平面的东西，不能修饰国人。正确说法是“这位国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在某一职位上任职的期间。", "primary_collocate": null, "pronunciation": "zài rèn", "ipa": "tsai̯˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他在任期间，学校盖了新楼。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王市长在任时，每天都很忙。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张在任十年，从来没请过假。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在任的这几年，公司越办越好。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在任时，常常和学生聊天。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在任期间，没有收过别人的礼物。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在任的时候，大家都很放心。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局长在任时，修了一条新路。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老书记在任三年，大家都很尊敬他。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任期间，她每年都去看望老人。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在任期间", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：处于某职位任职的期间，常说“在任期间／在任时”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“他在任期间”指他担任职务的时期，符合语境。"}, {"text": "建造", "is_correct": false, "explanation": "配价：“建造”需要带建筑物等宾语，“他建造期间”不能指时段，语义说不通。"}, {"text": "颁布", "is_correct": false, "explanation": "配价：“颁布”的对象是法令、规定，“他颁布期间，学校盖了新楼”语义不通。"}, {"text": "抵押", "is_correct": false, "explanation": "配价：“抵押”需要抵押物作宾语，“他抵押期间”语义不通。"}], "explanations": {"在任": "正确：“他在任期间”指他担任职务的时期，符合语境。", "建造": "配价：“建造”需要带建筑物等宾语，“他建造期间”不能指时段，语义说不通。", "颁布": "配价：“颁布”的对象是法令、规定，“他颁布期间，学校盖了新楼”语义不通。", "抵押": "配价：“抵押”需要抵押物作宾语，“他抵押期间”语义不通。"}, "sentence_index": 0, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经去世三年，现在仍在任。", "explanation": "这里应该用〈曾任〉。在任表示目前正担任职务，与“已经去世三年”矛盾。"}, {"text": "这台电脑在任，运行得很快。", "explanation": "这里应该用〈运行〉。在任只用于人，表示担任职务，不能指机器的工作状态。"}, {"text": "他明年才正式在任。", "explanation": "这里应该用〈上任〉。在任表示目前正担任职务，不能用于尚未就职的将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“经理在任的时候”指经理担任职务的时候，符合语境。"}, {"text": "殴打", "is_correct": false, "explanation": "配价：“殴打”需要带受事宾语，“经理殴打的时候”说不通；且与“大家都很放心”矛盾。"}, {"text": "寻衅", "is_correct": false, "explanation": "语义：“寻衅”指故意挑衅闹事，与“大家都很放心”的语境不合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：经理生气时“大家都很放心”不成立，语义矛盾。"}], "explanations": {"在任": "正确：“经理在任的时候”指经理担任职务的时候，符合语境。", "殴打": "配价：“殴打”需要带受事宾语，“经理殴打的时候”说不通；且与“大家都很放心”矛盾。", "寻衅": "语义：“寻衅”指故意挑衅闹事，与“大家都很放心”的语境不合。", "生气": "语义：经理生气时“大家都很放心”不成立，语义矛盾。"}, "sentence_index": 6, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经在任，现在没有任何职务。", "explanation": "这里应该用〈辞职〉。在任表示目前正担任职务，与“没有任何职务”矛盾。"}, {"text": "他现在在任，每天在家找工作。", "explanation": "这里应该用〈失业〉。在任表示目前正担任职务，与“在家找工作”矛盾。"}, {"text": "这次比赛他在任了，很沮丧。", "explanation": "这里应该用〈失败〉。在任表示担任职务，不能用于比赛的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在任三年过，学校盖了新楼。", "corrected_sentence": "他在任三年了，学校盖了新楼。", "error_description": "错误形式：“在任三年过”；正确形式：“在任三年了”。表示任职时长并延续到现在，句末用“了”，不用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在任三个年，攒下了不少经验。", "corrected_sentence": "他在任三年，攒下了不少经验。", "error_description": "错误形式：“在任三个年”；正确形式：“在任三年”。表示时段时，“年”前直接用数词，不加量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
