INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "目前担任某一职务。", "primary_collocate": null, "pronunciation": "zài rèn", "ipa": "tsai̯˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他是目前在任的市长。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任的经理明年就要退休了。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在在任的局长姓李。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位在任的主任很年轻。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任的老师里，他的年纪最大。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前在任的两位副校长都是女的。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是在任的董事长，不是以前那位。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任的领导明天要来学校。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在任的书记亲自接待了我们。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还在任，现在不能随便接受采访。", "target_word": "在任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在任期间", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：目前正担任某职务，常作定语，如“在任的市长”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f438f32-4542-4572-9676-f54eafc66eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“目前在任的市长”指现在正担任市长的人，符合语境。"}, {"text": "下台", "is_correct": false, "explanation": "语义：“目前下台”与“目前担任”相反，不符合语境。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“目前退休”与“目前在任”矛盾，不能修饰“市长”。"}, {"text": "颁布", "is_correct": false, "explanation": "配价：“颁布”的对象是法规、文件，“颁布的市长”说不通。"}], "explanations": {"在任": "正确：“目前在任的市长”指现在正担任市长的人，符合语境。", "下台": "语义：“目前下台”与“目前担任”相反，不符合语境。", "退休": "语义：“目前退休”与“目前在任”矛盾，不能修饰“市长”。", "颁布": "配价：“颁布”的对象是法规、文件，“颁布的市长”说不通。"}, "sentence_index": 0, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在任市长，现在已经退休了。", "explanation": "这里应该用〈曾任〉。在任表示目前正担任某职务，与“现在已经退休”矛盾。"}, {"text": "他现在在任，还没找到工作。", "explanation": "这里应该用〈失业〉。在任表示目前担任职务，与“还没找到工作”矛盾。"}, {"text": "她已经在任，现在只是一名普通职员。", "explanation": "这里应该用〈离任〉。在任表示目前正担任职务，与“现在只是一名普通职员”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在任", "is_correct": true, "explanation": "正确：“她是在任的董事长”指她现在担任董事长，符合语境。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业的董事长”自相矛盾，不符合语境。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”通常接证书、奖项，不能用来修饰“董事长”。"}, {"text": "嘱托", "is_correct": false, "explanation": "语域：“嘱托”是书面语，口语少用；且“嘱托的董事长”语境也不合。"}], "explanations": {"在任": "正确：“她是在任的董事长”指她现在担任董事长，符合语境。", "失业": "语义：“失业的董事长”自相矛盾，不符合语境。", "颁发": "搭配：“颁发”通常接证书、奖项，不能用来修饰“董事长”。", "嘱托": "语域：“嘱托”是书面语，口语少用；且“嘱托的董事长”语境也不合。"}, "sentence_index": 6, "correct_answer": "在任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下个月在任副市长。", "explanation": "这里应该用〈将任〉。在任表示目前正担任，不能用于将来才上任的情况。"}, {"text": "他现在在任，每天没有工作。", "explanation": "这里应该用〈下台〉。在任表示目前担任职务，与“每天没有工作”矛盾。"}, {"text": "犯人在半夜在任了。", "explanation": "这里应该用〈逃跑〉。在任表示担任职务，不能用于犯人的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是在任了的市长。", "corrected_sentence": "他是在任的市长。", "error_description": "错误形式：“在任了的市长”；正确形式：“在任的市长”。“在任”表示目前的职务状态，修饰名词时不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位在任的的老师很认真。", "corrected_sentence": "这位在任的老师很认真。", "error_description": "错误形式：“在任的的老师”；正确形式：“在任的老师”。定语后的“的”只用一个，重复加“的”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0de718-302a-49ee-aa87-6e2183c3173e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
