INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97689, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很小很小的事，不用谢。", "primary_collocate": null, "pronunciation": "xiǎo yì si", "ipa": "ɕiɑʊ˨˩˦ i˥˩ sɿ", "syllable_count": 3, "sentences": [{"text": "谢谢你帮我！——小意思，不用谢。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你帮了我大忙！——小意思！", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“多谢你送我回家。”“小意思，别客气。”", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点忙算什么，小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“小意思，不用谢。”", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你借我伞。——小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮你搬家只是小意思，不用谢。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这么晚还麻烦你。”“小意思！”", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我替你拿一下包，小意思。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说帮这点忙是小意思，不用谢我。", "target_word": "小意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回应别人道谢时说的客气话，表示帮忙很轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大恩", "is_correct": false, "explanation": "语义：“大恩”说明帮助很大，与“小意思”的客气、轻松语气矛盾。"}, {"text": "小意思", "is_correct": true, "explanation": "正确：回应道谢时说“小意思”，表示帮忙很轻松，与“不用谢”相符。"}, {"text": "大礼", "is_correct": false, "explanation": "搭配：“大礼”指贵重的礼物，不用来回应道谢时说的帮忙。"}, {"text": "重任", "is_correct": false, "explanation": "语域：“重任”是书面语，口语里回应道谢时不用。"}], "explanations": {"大恩": "语义：“大恩”说明帮助很大，与“小意思”的客气、轻松语气矛盾。", "小意思": "正确：回应道谢时说“小意思”，表示帮忙很轻松，与“不用谢”相符。", "大礼": "搭配：“大礼”指贵重的礼物，不用来回应道谢时说的帮忙。", "重任": "语域：“重任”是书面语，口语里回应道谢时不用。"}, "sentence_index": 0, "correct_answer": "小意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这封信的小意思很明白。", "explanation": "这里说的是文字的寓意，“小意思”只表示轻松的客套，不指含义。"}, {"text": "对不起，我弄丢了你的书，这本新书是我的一点小意思。", "explanation": "这里的〈小意思〉是送礼时的谦辞，指礼物轻薄、表示心意，不是回应道歉或“不用谢”的意思。"}, {"text": "谢谢你帮我！——一颗小意思，不用谢。", "explanation": "量词用错：“小意思”作为客套话不用“颗”计量，颗用于粒状的东西；这里应直接说〈小意思〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大工程", "is_correct": false, "explanation": "语义：“只是”表示轻微，与“大工程”的规模矛盾。"}, {"text": "小意思", "is_correct": true, "explanation": "正确：“小意思”表示帮忙很轻松，与“只是”和“不用谢”相符。"}, {"text": "大事", "is_correct": false, "explanation": "语义：“大事”与“只是”表示轻微的语气矛盾。"}, {"text": "大功", "is_correct": false, "explanation": "语域：“大功”是书面语，口语里说帮人搬家不用这个词。"}], "explanations": {"大工程": "语义：“只是”表示轻微，与“大工程”的规模矛盾。", "小意思": "正确：“小意思”表示帮忙很轻松，与“只是”和“不用谢”相符。", "大事": "语义：“大事”与“只是”表示轻微的语气矛盾。", "大功": "语域：“大功”是书面语，口语里说帮人搬家不用这个词。"}, "sentence_index": 6, "correct_answer": "小意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谢谢你帮我！——你真是个小意思。", "explanation": "“小意思”指事情或东西，不能用来称人；这里应直接回应“不用谢”，说〈小意思〉。"}, {"text": "这道题对我来说只是一粒小意思。", "explanation": "量词用错：“小意思”指事情，不用“粒”计量，粒用于细小的颗粒状东西；这里应说〈这道题对我来说只是小意思〉。"}, {"text": "他的小意思很明显，就是想请我吃饭。", "explanation": "这里要用〈小心思〉，指小小的算盘或打算；“小意思”指事情微不足道，不能用来表示心思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谢谢你替我照看猫！——把小意思。", "corrected_sentence": "谢谢你替我照看猫！——小意思。", "error_description": "错误在于“把”字句需要动词和宾语，“小意思”是名词性的客套话，不能直接接在“把”后面；直接说“小意思”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谢谢你带我看医生！——小意思了。", "corrected_sentence": "谢谢你带我看医生！——小意思。", "error_description": "错误在于“小意思”作为客套话，后面不能加“了”。直接说“小意思”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
