INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97741, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力保护，不让别人抢走或伤害。", "primary_collocate": null, "pronunciation": "hàn wèi", "ipa": "xan˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "士兵们用生命捍卫着自己的家园。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗拼命捍卫它的骨头。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟张开双手，捍卫他的玩具。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们团结起来，捍卫祖辈留下的土地。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母鸡张开翅膀，捍卫自己的小鸡。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意用一切捍卫自己的家人。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须捍卫这片美丽的森林。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捍卫过这座小城，没让敌人进来。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人想抢走他的土地，他拼命捍卫。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们把阵地捍卫到了最后一刻。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捍卫了", "label": "完成体"}, {"form": "捍卫着", "label": "持续体"}, {"form": "捍卫过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "拼力保护自己的人或东西，不让别人抢走或伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97741, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占领", "is_correct": false, "explanation": "语义：“占领”是夺取，与“用生命”保护自己的家园相反。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示用力保护，与“用生命”“自己的家园”相符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢下不管，与“捍卫”的保护之义相反。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清理，不能与“用生命”搭配。"}], "explanations": {"占领": "语义：“占领”是夺取，与“用生命”保护自己的家园相反。", "捍卫": "正确：“捍卫”表示用力保护，与“用生命”“自己的家园”相符。", "抛弃": "语义：“抛弃”是丢下不管，与“捍卫”的保护之义相反。", "打扫": "搭配：“打扫”是清理，不能与“用生命”搭配。"}, "sentence_index": 0, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们捍卫敌人的进攻。", "explanation": "这里应该用〈抵抗〉。捍卫的对象是自己拥有、值得保护的东西，阻挡敌人的进攻要用抵抗。"}, {"text": "这个小偷捍卫了别人的钱包。", "explanation": "这里应该用〈抢〉。捍卫用于保护自己或正当拥有的东西，把别人的钱包抢过来要用抢。"}, {"text": "这个流氓捍卫了他的赃物。", "explanation": "这里应该用〈交出〉。捍卫用于正当拥有的东西，对赃物应说交出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“必须”后的保护意愿相反，句意矛盾。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示保护，与“必须”“美丽的森林”相符。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”使环境变脏，与“美丽的森林”的赞美语境冲突。"}, {"text": "采", "is_correct": false, "explanation": "搭配：“采”的对象是花、果等，不说“采森林”。"}], "explanations": {"破坏": "语义：“破坏”与“必须”后的保护意愿相反，句意矛盾。", "捍卫": "正确：“捍卫”表示保护，与“必须”“美丽的森林”相符。", "污染": "语义：“污染”使环境变脏，与“美丽的森林”的赞美语境冲突。", "采": "搭配：“采”的对象是花、果等，不说“采森林”。"}, "sentence_index": 6, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些乡绅捍卫了那个贪官。", "explanation": "这里应该用〈揭发〉。捍卫用于正当的人或事，对贪官的罪行要用揭发。"}, {"text": "强盗捍卫了村里的粮食。", "explanation": "这里应该用〈掠夺〉。捍卫用于保护自己的财物，抢夺别人的粮食要用掠夺。"}, {"text": "村民捍卫了入侵者。", "explanation": "这里应该用〈驱逐〉。捍卫不用于敌对的入侵者，把入侵者赶走要用驱逐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们把阵地捍卫。", "corrected_sentence": "士兵们把阵地捍卫住了。", "error_description": "错误形式：“把阵地捍卫”；正确形式：“把阵地捍卫住了”。“把”字句中动词后要带补语或“了”等成分，单独的“捍卫”不能收尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战士们捍卫很英勇。", "corrected_sentence": "战士们捍卫得很英勇。", "error_description": "错误形式：“捍卫很英勇”；正确形式：“捍卫得很英勇”。动作的程度补语要用“得”引出，不能直接在动词后接“很”加形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
