INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保卫；坚决保护。", "primary_collocate": null, "pronunciation": "hàn wèi", "ipa": "xan˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "国家坚决捍卫自己的主权。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要捍卫每个人的合法权利。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行动捍卫了自己的尊严。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直捍卫着真理。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师的工作是捍卫法律的公正。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律捍卫着公民的自由。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的责任是捍卫国家的安全。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他勇敢地站出来，捍卫自己的看法。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者应该捍卫新闻的真实。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把捍卫和平当作最大的责任。", "target_word": "捍卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捍卫了", "label": "完成体"}, {"form": "捍卫着", "label": "持续体"}, {"form": "捍卫过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "坚决保护主权、权利、尊严、真理等重要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出卖", "is_correct": false, "explanation": "语义：“出卖”是背叛、卖掉，与“坚决”的态度矛盾。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示坚决保护，与“坚决”“自己的主权”相符。"}, {"text": "批判", "is_correct": false, "explanation": "搭配：“批判”针对观点或错误，不说“批判主权”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“坚决”的态度矛盾，不能用来维护主权。"}], "explanations": {"出卖": "语义：“出卖”是背叛、卖掉，与“坚决”的态度矛盾。", "捍卫": "正确：“捍卫”表示坚决保护，与“坚决”“自己的主权”相符。", "批判": "搭配：“批判”针对观点或错误，不说“批判主权”。", "忘记": "语义：“忘记”与“坚决”的态度矛盾，不能用来维护主权。"}, "sentence_index": 0, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚决捍卫这次的失败。", "explanation": "这里应该用〈承认〉。捍卫是坚决保护值得守护的东西，失败应坦然承认。"}, {"text": "老师捍卫了那份抄来的作业。", "explanation": "这里应该用〈揭穿〉。捍卫用于正当的权利或真理，对抄袭的作业要用揭穿。"}, {"text": "他捍卫了那张偷来的照片。", "explanation": "这里应该用〈归还〉。捍卫用于正当拥有或值得守护的东西，偷来的照片应说归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“军队的责任”相反，句意矛盾。"}, {"text": "捍卫", "is_correct": true, "explanation": "正确：“捍卫”表示坚决保护，与“军队的责任”“国家的安全”相符。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是对安全造成危害，不能作军队的责任。"}, {"text": "打击", "is_correct": false, "explanation": "搭配：“打击”的对象是敌人或犯罪，不说“打击安全”。"}], "explanations": {"破坏": "语义：“破坏”与“军队的责任”相反，句意矛盾。", "捍卫": "正确：“捍卫”表示坚决保护，与“军队的责任”“国家的安全”相符。", "威胁": "语义：“威胁”是对安全造成危害，不能作军队的责任。", "打击": "搭配：“打击”的对象是敌人或犯罪，不说“打击安全”。"}, "sentence_index": 6, "correct_answer": "捍卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的纵容捍卫了歪风邪气。", "explanation": "这里应该用〈助长〉。捍卫用于值得守护的正面事物，助长坏风气要用助长。"}, {"text": "这些人捍卫了这场争端。", "explanation": "这里应该用〈挑起〉。捍卫不用于需要平息的争端，引发争端要用挑起。"}, {"text": "他捍卫了这场闹事。", "explanation": "这里应该用〈煽动〉。捍卫不用于闹事这类负面行为，煽动别人闹事要用煽动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把国家的主权捍卫。", "corrected_sentence": "我们要把国家的主权捍卫好。", "error_description": "错误形式：“把国家的主权捍卫”；正确形式：“把国家的主权捍卫好”。“把”字句中动词后要有补语，如“好”“住”，单独的“捍卫”不能收尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "律师捍卫了着公民的权利。", "corrected_sentence": "律师捍卫着公民的权利。", "error_description": "错误形式：“捍卫了着”；正确形式：“捍卫着”。“了”和“着”都是动态助词，不能同时用在同一动词后，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
