INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己的东西或钱送给别人，帮助他们。", "primary_collocate": null, "pronunciation": "juān zèng", "ipa": "tɕɥɛn˥ tsɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把旧衣服捐赠给了山区的孩子。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每年都捐赠一些钱。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些书捐赠给图书馆。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人捐赠了自己一半的钱。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请大家捐赠不用的玩具。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捐赠过很多东西，从不说出来。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们捐赠食物，帮助生病的老人。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捐赠了一笔钱，帮助穷孩子上学。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们捐赠自己的零花钱，帮助灾区的人。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家捐赠了一台旧电视。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐赠了", "label": "完成体"}, {"form": "捐赠过", "label": "经历体"}, {"form": "捐赠者", "label": "复合词"}], "register": "正式", "sense_fingerprint": "把自己的东西或钱送给需要的人，帮助他们", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：无偿把东西送给山区的孩子，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧给”多用于给已故的人烧纸钱，山区的孩子是活人，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”指把衣物穿在身上，不表示把东西送给别人，句意不通。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是打碎，与“给了山区的孩子”的赠予意思相反。"}], "explanations": {"捐赠": "捐赠：无偿把东西送给山区的孩子，符合句意。", "烧": "语义：“烧给”多用于给已故的人烧纸钱，山区的孩子是活人，句意不通。", "穿": "搭配：“穿”指把衣物穿在身上，不表示把东西送给别人，句意不通。", "砸": "语义：“砸”是打碎，与“给了山区的孩子”的赠予意思相反。"}, "sentence_index": 0, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈把一条围巾捐赠给了我。", "explanation": "这里应该用〈赠送〉。捐赠是为了帮助需要的人，送给自己的孩子作日常礼物应用〈赠送〉。"}, {"text": "我把一本旧书捐赠给书店，收了一百块钱。", "explanation": "这里应该用〈卖〉。捐赠是无偿送出，句中“收了一百块钱”说明是有偿交易。"}, {"text": "我把这本书捐赠给了朋友，说好下周还给我。", "explanation": "这里应该用〈借〉。捐赠是永久送出，不会再还回来；句中“下周还给我”说明是借出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：无偿把食物送给需要帮助的人，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，扔掉食物与“帮助生病的老人”的意思相反。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“帮助生病的老人”的意思矛盾。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”指修理器物，不能与“食物”搭配，句子不通。"}], "explanations": {"捐赠": "捐赠：无偿把食物送给需要帮助的人，符合句意。", "扔": "语义：“扔”是丢弃，扔掉食物与“帮助生病的老人”的意思相反。", "偷": "语义：“偷”是窃取，与“帮助生病的老人”的意思矛盾。", "修": "搭配：“修”指修理器物，不能与“食物”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这台旧电视捐赠给了我自己。", "explanation": "这里应该用〈留着〉。捐赠的对象必须是他人或机构，自己留用应说留着。"}, {"text": "公司把总经理的职位捐赠给了小王。", "explanation": "这里应该用〈转让〉。捐赠的对象必须是财物，职位不是财物，职位的交接应说转让。"}, {"text": "我家从希望小学捐赠了一台旧电视。", "explanation": "这里应该用〈受赠〉。捐赠是把东西送出去，句中“从希望小学”说明方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司明天向小学捐赠了一台电脑。", "corrected_sentence": "公司明天向小学捐赠一台电脑。", "error_description": "“明天”指将来，动作尚未发生，动词后不能加“了”。应去掉“了”，改为“公司明天向小学捐赠一台电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校捐赠了过很多图书给山区。", "corrected_sentence": "学校捐赠过很多图书给山区。", "error_description": "“捐赠过”已表示经历体，“了”和“过”不能同时使用。应去掉“了”，改为“学校捐赠过很多图书给山区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
