INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把财物无偿送给他人或机构。", "primary_collocate": null, "pronunciation": "juān zèng", "ipa": "tɕɥɛn˥ tsɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司向医院捐赠了十台机器。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有的画捐赠给了博物馆。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司无偿捐赠了一批口罩。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生向大学捐赠了一百万元。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去世后，家人把她的书捐赠给了学校。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行向灾区捐赠了大量物资。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捐赠过一座图书馆。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红十字会收到了市民捐赠的衣物。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金会每年向学校捐赠一笔钱。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家工厂把新机器捐赠给了职业学校。", "target_word": "捐赠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐赠了", "label": "完成体"}, {"form": "捐赠过", "label": "经历体"}, {"form": "捐赠者", "label": "复合词"}], "register": "正式", "sense_fingerprint": "无偿把财物送给医院、学校、博物馆等机构或个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：向医院无偿送出机器，符合句意。"}, {"text": "抢", "is_correct": false, "explanation": "配价：“抢”要用“从”引出被夺取的对象，不能用“向”引出受益的医院。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开或拆除，与“向医院”送出机器的意思不符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是击碎，与向医院提供机器的意思相反。"}], "explanations": {"捐赠": "捐赠：向医院无偿送出机器，符合句意。", "抢": "配价：“抢”要用“从”引出被夺取的对象，不能用“向”引出受益的医院。", "拆": "语义：“拆”是拆开或拆除，与“向医院”送出机器的意思不符。", "砸": "语义：“砸”是击碎，与向医院提供机器的意思相反。"}, "sentence_index": 0, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位先生把一座楼捐赠给大学，大学付了一百万元。", "explanation": "这里应该用〈卖〉。捐赠是无偿送出，句中“大学付了一百万元”说明是有偿交易。"}, {"text": "这位先生把一百万元捐赠给了他自己。", "explanation": "这里应该用〈留着〉。捐赠的对象必须是他人或机构，自己留用应说留着。"}, {"text": "这位先生向大学捐赠了很多力量。", "explanation": "这里应该用〈贡献〉。捐赠的对象是财物，“力量”不是财物，应说贡献力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐赠", "is_correct": true, "explanation": "捐赠：无偿送给图书馆一座楼，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“图书馆”搭配，句子不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的对象是马、车等，不能用于“图书馆”，句子不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆除，把图书馆拆掉，与“捐赠”的赠予之义相反。"}], "explanations": {"捐赠": "捐赠：无偿送给图书馆一座楼，符合句意。", "吃": "搭配：“吃”的对象是食物，不能与“图书馆”搭配，句子不通。", "骑": "搭配：“骑”的对象是马、车等，不能用于“图书馆”，句子不通。", "拆": "语义：“拆”是拆除，把图书馆拆掉，与“捐赠”的赠予之义相反。"}, "sentence_index": 6, "correct_answer": "捐赠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那家工厂把新机器捐赠给了职业学校，学校说好明年还回来。", "explanation": "这里应该用〈借〉。捐赠是永久送出，不会再还回来；句中“明年还回来”说明是借出。"}, {"text": "那家工厂把新机器捐赠给了自己的女儿。", "explanation": "这里应该用〈赠送〉。捐赠是面向社会或机构的无偿赠予，送给自己女儿这样的家人作礼物应用赠送。"}, {"text": "那家工厂把新机器捐赠给了一个想法。", "explanation": "这里应该用〈支持〉。捐赠的对象必须是人或机构，支持一个想法应说支持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家银行明天向灾区捐赠了一顶帐篷。", "corrected_sentence": "这家银行明天向灾区捐赠一顶帐篷。", "error_description": "“明天”指将来，动作尚未发生，动词后不能加“了”。应去掉“了”，改为“这家银行明天向灾区捐赠一顶帐篷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不捐赠过一座图书馆。", "corrected_sentence": "他没捐赠过一座图书馆。", "error_description": "表示“从未做过”的否定要用“没”加“过”，不能用“不”。应改为“他没捐赠过一座图书馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
