INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97761, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把声音、图像送出去，让大家听到或看到。", "primary_collocate": null, "pronunciation": "bō", "ipa": "pwo˥", "syllable_count": 1, "sentences": [{"text": "电视里正在播新闻。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你播一首轻松的歌。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们播了一段视频。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上八点，电视台会播这部电影。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在手机上播音乐。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目每天都播，我天天看。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上播着孩子们的照片。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想听什么，我就给你播什么。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台今天播了一首新歌。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，先播国歌。", "target_word": "播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "播了", "label": "体标"}, {"form": "播着", "label": "体标"}, {"form": "播过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把声音或图像送出去让人听到看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "播", "is_correct": true, "explanation": "播（bō，第一声），意思是把声音、图像送出去，让人听到或看到。"}, {"text": "伯", "is_correct": false, "explanation": "伯（bó，第二声）与播（bō，第一声）声调不同，意思是伯伯、父亲的哥哥。"}, {"text": "博", "is_correct": false, "explanation": "博（bó，第二声）与播（bō，第一声）声调不同，意思是广博，如博物馆。"}, {"text": "坡", "is_correct": false, "explanation": "坡（pō，第一声）与播（bō）声母不同：p 送气，b 不送气，意思是斜坡。"}, {"text": "脖", "is_correct": false, "explanation": "脖（bó，第二声）与播（bō，第一声）声调不同，意思是脖子。"}], "explanations": {"播": "播（bō，第一声），意思是把声音、图像送出去，让人听到或看到。", "伯": "伯（bó，第二声）与播（bō，第一声）声调不同，意思是伯伯、父亲的哥哥。", "博": "博（bó，第二声）与播（bō，第一声）声调不同，意思是广博，如博物馆。", "坡": "坡（pō，第一声）与播（bō）声母不同：p 送气，b 不送气，意思是斜坡。", "脖": "脖（bó，第二声）与播（bō，第一声）声调不同，意思是脖子。"}, "sentence_index": null, "correct_answer": "播"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，新闻不能被吃，句意不通。"}, {"text": "播", "is_correct": true, "explanation": "正确：“播”表示通过电视传送节目，与句中的“电视里”相符。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”多用于房屋、机器，不说“修新闻”。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，新闻不能被踢，句意不通。"}], "explanations": {"吃": "语义：“吃”的对象是食物，新闻不能被吃，句意不通。", "播": "正确：“播”表示通过电视传送节目，与句中的“电视里”相符。", "修": "搭配：“修”多用于房屋、机器，不说“修新闻”。", "踢": "语义：“踢”是用脚击打，新闻不能被踢，句意不通。"}, "sentence_index": 0, "correct_answer": "播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个剧团下周在礼堂播一场话剧。", "explanation": "这里应该用〈演〉。播指通过广播、电视传送节目，剧团在礼堂的表演要用演。"}, {"text": "我昨天给老同学播了一条短信。", "explanation": "这里应该用〈发〉。播是向大众传送节目或声音图像，给个人发短信要用发。"}, {"text": "我把一封信播给了外婆。", "explanation": "这里应该用〈寄〉。播是向大众传送节目或声音图像，把信寄给亲人要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "播", "is_correct": true, "explanation": "播（bō，第一声），意思是把声音、图像送出去，让人听到或看到。"}, {"text": "泼", "is_correct": false, "explanation": "泼（pō，第一声）与播（bō）声母不同：p 送气，b 不送气，意思是把液体倒出去，如泼水。"}, {"text": "驳", "is_correct": false, "explanation": "驳（bó，第二声）与播（bō，第一声）声调不同，意思是反驳、驳回。"}, {"text": "跛", "is_correct": false, "explanation": "跛（bǒ，第三声）与播（bō，第一声）声调不同，意思是腿脚不灵便，如跛脚。"}, {"text": "勃", "is_correct": false, "explanation": "勃（bó，第二声）与播（bō，第一声）声调不同，意思是旺盛、兴起，如蓬勃。"}], "explanations": {"播": "播（bō，第一声），意思是把声音、图像送出去，让人听到或看到。", "泼": "泼（pō，第一声）与播（bō）声母不同：p 送气，b 不送气，意思是把液体倒出去，如泼水。", "驳": "驳（bó，第二声）与播（bō，第一声）声调不同，意思是反驳、驳回。", "跛": "跛（bǒ，第三声）与播（bō，第一声）声调不同，意思是腿脚不灵便，如跛脚。", "勃": "勃（bó，第二声）与播（bō，第一声）声调不同，意思是旺盛、兴起，如蓬勃。"}, "sentence_index": null, "correct_answer": "播"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "搭配：“洗”可以搭配照片，但“屏幕上”不能冲洗照片，搭配不成立。"}, {"text": "播", "is_correct": true, "explanation": "正确：“播”表示屏幕上播放孩子们的照片，与“屏幕上”相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”可以用于屏幕，但不说“擦照片”。"}, {"text": "剪", "is_correct": false, "explanation": "语义：屏幕是显示画面的表面，不能被“剪”。"}], "explanations": {"洗": "搭配：“洗”可以搭配照片，但“屏幕上”不能冲洗照片，搭配不成立。", "播": "正确：“播”表示屏幕上播放孩子们的照片，与“屏幕上”相符。", "擦": "搭配：“擦”可以用于屏幕，但不说“擦照片”。", "剪": "语义：屏幕是显示画面的表面，不能被“剪”。"}, "sentence_index": 6, "correct_answer": "播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把照片播在桌子上。", "explanation": "这里应该用〈放〉。播用于传送节目或声音图像，把照片摆在桌上要用放。"}, {"text": "我把这份资料播给了朋友。", "explanation": "这里应该用〈转〉。播是把节目送给大众，把资料转交给个人要用转。"}, {"text": "他把奖状播在墙上。", "explanation": "这里应该用〈挂〉。播用于传送声音图像，把奖状挂在墙上要用挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这段视频播。", "corrected_sentence": "我把这段视频播了。", "error_description": "错误形式：“我把这段视频播。”；正确形式：“我把这段视频播了。”“把”字句中动词后要有“了”或补语等成分，单独的“播”不能收尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在播了这部纪录片。", "corrected_sentence": "他们正在播这部纪录片。", "error_description": "错误形式：“正在播了”；正确形式：“正在播”。“正在”表示动作进行中，不能与“了”同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
