INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97769, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不要抓紧，松开手。", "primary_collocate": null, "pronunciation": "fàng kāi", "ipa": "faŋ˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "快放开我的手！", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放开绳子，气球飞走了。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你放开那只小鸟，它会疼的。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子紧紧抱着妈妈，不肯放开。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学骑车时，爸爸扶着车座，慢慢放开了手。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放开了狗，狗马上跑了出去。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再不放开，我就喊人了。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放开我的衣服，转身走了。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一放开手，杯子就掉在了地上。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢放开了她的手。", "target_word": "放开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放开了", "label": "完成体"}, {"form": "放开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "手不再抓紧，把抓住的人或东西松开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d58e6bd-89b2-4568-addc-d3b1e66e6578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放开", "is_correct": true, "explanation": "放开：松开抓着的手，符合“快……我的手”的语境。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是割断，“快切我的手”表示伤害对方，与要求松手的语境不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服鞋袜，不能用于“我的手”。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理器物，不能用于“我的手”，句子不通。"}], "explanations": {"放开": "放开：松开抓着的手，符合“快……我的手”的语境。", "切": "语义：“切”是割断，“快切我的手”表示伤害对方，与要求松手的语境不符。", "穿": "搭配：“穿”用于衣服鞋袜，不能用于“我的手”。", "修": "搭配：“修”用于修理器物，不能用于“我的手”，句子不通。"}, "sentence_index": 0, "correct_answer": "放开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他紧紧放开了绳子。", "explanation": "这里应该用〈抓住〉。“紧紧”表示握牢，与“放开”（松手）的意思矛盾。"}, {"text": "他放开了那盏电灯，屋子马上亮了。", "explanation": "这里应该用〈点亮〉。放开指松手或放宽限制，使灯亮要说点亮。"}, {"text": "他放开了这个机会。", "explanation": "这里应该用〈放弃〉。“放开”指松手或放宽限制，机会不能被“放开”，应说放弃机会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放开", "is_correct": true, "explanation": "放开：松手不再管，符合“你再不……，我就喊人了”的语境。"}, {"text": "捡", "is_correct": false, "explanation": "配价：“捡”要求带宾语，这里单独使用句子不完整，也不表示松手。"}, {"text": "摆", "is_correct": false, "explanation": "配价：“摆”要带宾语，如“摆开”，不能单独用在这里，句子不通。"}, {"text": "掉", "is_correct": false, "explanation": "语义：“掉”指物体脱落，不能用于人主动松手，与句中的威胁语气不合。"}], "explanations": {"放开": "放开：松手不再管，符合“你再不……，我就喊人了”的语境。", "捡": "配价：“捡”要求带宾语，这里单独使用句子不完整，也不表示松手。", "摆": "配价：“摆”要带宾语，如“摆开”，不能单独用在这里，句子不通。", "掉": "语义：“掉”指物体脱落，不能用于人主动松手，与句中的威胁语气不合。"}, "sentence_index": 6, "correct_answer": "放开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放开了那条路，过了很久才建成。", "explanation": "这里应该用〈建造〉。放开指松手或放宽限制，修路要用建造。"}, {"text": "他放开了那台坏掉的电视，请人来看看。", "explanation": "这里应该用〈修理〉。放开指松手或放宽限制，坏了的电器要修理，不能说放开。"}, {"text": "他放开了训练，不想再练了。", "explanation": "这里应该用〈停止〉。“放开”只能用于松开手中的东西，不能用于训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子终于把放开了妈妈的衣角。", "corrected_sentence": "孩子终于放开了妈妈的衣角。", "error_description": "错误在“把”字：“把”后应先接受事、再接动词（如“把妈妈的衣角放开”），这里“把”直接接动词，受事却放在动词之后。应删去“把”，正确说法是“孩子终于放开了妈妈的衣角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经放开了过她的手。", "corrected_sentence": "他曾经放开过她的手。", "error_description": "“放开”后表示经历的“过”不能与“了”同用。应去掉“了”，改为“他曾经放开过她的手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36254b66-134e-4fc7-b4de-02ed376e180b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
