INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寻找机会。", "primary_collocate": null, "pronunciation": "zhǎo jī huì", "ipa": "ʈ͡ʂɑʊ̯˨˩ t͡ɕi˥ xu̯eɪ˥˩", "syllable_count": 3, "sentences": [{"text": "他在大城市找机会，想开一家店。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，很多年轻人去北京找机会。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处找机会，想找一份好工作。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多找机会练习汉语。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去国外找机会学习。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在公司里找机会，想让老板看到他。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要会找机会。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在网上找机会。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该多出去找机会。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了找机会，他搬到了上海。", "target_word": "找机会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找个机会", "label": "离合"}, {"form": "找找机会", "label": "重叠"}, {"form": "找機會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "找机会：四处寻找发展、工作或学习的机会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找借口", "is_correct": false, "explanation": "语义：“找借口”是编造理由推脱，与“想开一家店”的目标矛盾。"}, {"text": "找机会", "is_correct": true, "explanation": "正确：“找机会”指在发展、工作或学习方面寻找机会，与“想开一家店”相合。"}, {"text": "失去机会", "is_correct": false, "explanation": "语义：“失去”表示丢掉已有的机会，与“想开一家店”的追求不合。"}, {"text": "吃机会", "is_correct": false, "explanation": "搭配：“吃”不与“机会”搭配，这个说法不成立。"}], "explanations": {"找借口": "语义：“找借口”是编造理由推脱，与“想开一家店”的目标矛盾。", "找机会": "正确：“找机会”指在发展、工作或学习方面寻找机会，与“想开一家店”相合。", "失去机会": "语义：“失去”表示丢掉已有的机会，与“想开一家店”的追求不合。", "吃机会": "搭配：“吃”不与“机会”搭配，这个说法不成立。"}, "sentence_index": 0, "correct_answer": "找机会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找机会梦见了一只大象。", "explanation": "“找机会”指有意寻找合适的时机去做事，“梦见”是睡眠中出现的情景，不是有意去做的事，不能去找。"}, {"text": "他找机会长高了五厘米。", "explanation": "“找机会”指有意寻找合适的时机去做事，“长高”是自然生长，不能去找。"}, {"text": "他找机会打起了喷嚏。", "explanation": "“找机会”指有意寻找合适的时机去做事，“打喷嚏”是身体不由自己控制的反应，不能去找。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错过机会", "is_correct": false, "explanation": "语义：“错过”是失去机会，与“做生意要会”的能力要求矛盾。"}, {"text": "找机会", "is_correct": true, "explanation": "正确：“要会找机会”指做生意要善于寻找合适的机会。"}, {"text": "忽视机会", "is_correct": false, "explanation": "语义：“忽视”与“要会”的能力要求相反。"}, {"text": "躲避机会", "is_correct": false, "explanation": "搭配：“躲避”多与危险、责任搭配，不说“躲避机会”。"}], "explanations": {"错过机会": "语义：“错过”是失去机会，与“做生意要会”的能力要求矛盾。", "找机会": "正确：“要会找机会”指做生意要善于寻找合适的机会。", "忽视机会": "语义：“忽视”与“要会”的能力要求相反。", "躲避机会": "搭配：“躲避”多与危险、责任搭配，不说“躲避机会”。"}, "sentence_index": 6, "correct_answer": "找机会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找机会吞下了一个西瓜。", "explanation": "“找机会”指有意寻找合适的时机去做事，“吞下一个西瓜”不是寻找时机能完成的事。"}, {"text": "他在房间里仔细找机会。", "explanation": "这里应该用〈找东西〉。“找机会”不能指寻找具体的物品。"}, {"text": "她找机会把月亮装进了口袋。", "explanation": "“找机会”指有意寻找合适的时机去做事，“把月亮装进口袋”不可能实现，只能用于想象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年轻人都想在大城市很找机会。", "corrected_sentence": "年轻人都想在大城市找机会。", "error_description": "副词位置错误：“很”不能修饰动词“找”，“很找机会”不成立；应去掉“很”，说“在大城市找机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业后终于找机会，搬到了上海。", "corrected_sentence": "他毕业后终于找到机会，搬到了上海。", "error_description": "结果补语缺失：“终于”表示达成结果，应说“找到机会”，只说“找机会”表示还在寻找，不能说明已经达成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
