INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "总台是一个地方最前面的服务台，来了人先去那里问。", "primary_collocate": null, "pronunciation": "zǒng tái", "ipa": "tsʊŋ˨˩˦ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "你先去总台问一下。", "target_word": "总台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总台在大门旁边，很好找。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了学校，请先到总台登记。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总台的小姐姐告诉我，会议室在三楼。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的总台前面排着很多人。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到路，可以去总台问问。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总台旁边有一张地图。", "target_word": "总台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把雨伞放在总台，然后上楼了。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的总台没有人，我只好等着。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加活动的人，都要先去总台拿号码。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "總台", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个地方最前面的服务台，来人先去问路或办事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总台", "is_correct": true, "explanation": "总台指一个地方最前面的服务台，去那里问一下符合句意。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：问一下要去能回答问题的服务处，厕所不是问询的地方，句意不通。"}, {"text": "猫", "is_correct": false, "explanation": "配价：「问」需要能作答的对象，猫不能回答问题，句子不成立。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：寒舍是自谦用语，日常问路不用这样的说法。"}], "explanations": {"总台": "总台指一个地方最前面的服务台，去那里问一下符合句意。", "厕所": "语义：问一下要去能回答问题的服务处，厕所不是问询的地方，句意不通。", "猫": "配价：「问」需要能作答的对象，猫不能回答问题，句子不成立。", "寒舍": "语域：寒舍是自谦用语，日常问路不用这样的说法。"}, "sentence_index": 0, "correct_answer": "总台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大厅里有一只总台，你去那儿问一下。", "explanation": "这里应该用〈个〉。总台的量词是「个」，「只」用于动物或某些器物，不用于服务台。"}, {"text": "老师站在总台上讲课。", "explanation": "这里应该用〈讲台〉。讲台是老师讲课时站的台子，总台是接待、咨询的服务台，不能用来站着讲课。"}, {"text": "我去银行总台取了钱。", "explanation": "这里应该用〈柜台〉。总台指机构门口的接待服务台，银行办理取款的窗口叫柜台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总台", "is_correct": true, "explanation": "总台是服务台，放在句首作地点，旁边有一张地图，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是能放地图的地点，「空气旁边有一张地图」句意荒谬。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不会有可以放在旁边的一张地图，与句意不合。"}, {"text": "贵府", "is_correct": false, "explanation": "语域：贵府是对他人家的敬称，描述一般地点的位置时用在这里不合语境。"}], "explanations": {"总台": "总台是服务台，放在句首作地点，旁边有一张地图，句意通顺。", "空气": "语义：空气不是能放地图的地点，「空气旁边有一张地图」句意荒谬。", "天空": "语义：天空上不会有可以放在旁边的一张地图，与句意不合。", "贵府": "语域：贵府是对他人家的敬称，描述一般地点的位置时用在这里不合语境。"}, "sentence_index": 6, "correct_answer": "总台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市总台付了钱。", "explanation": "这里应该用〈收银台〉。付款要去收银台，总台指接待、咨询的服务台。"}, {"text": "门口摆着一把总台。", "explanation": "这里应该用〈个〉。「把」用于有把手的东西，总台的量词是「个」。"}, {"text": "大厅里有一条总台。", "explanation": "这里应该用〈个〉。「条」用于细长的东西，总台的量词是「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校有一间总台。", "corrected_sentence": "我们学校有一个总台。", "error_description": "总台是服务台，量词用「个」。「间」多用于房间，这里说「一间总台」是错误的，应说「一个总台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大厅里有一本总台，很干净。", "corrected_sentence": "大厅里有一个总台，很干净。", "error_description": "总台的量词用「个」。「本」用于书册，这里说「一本总台」不对，应说「一个总台」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
