INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转身是把身体转过去，面对另一边。", "primary_collocate": null, "pronunciation": "zhuǎn shēn", "ipa": "ʈ͡ʂu̯an˨˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "听到声音，我转身往后看。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到门口，又转身回来了。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都转身看着窗外。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转身面对镜子，整理头发。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车来了，他转身躲到树后。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请转身，看后面的图。”", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转身看了看，没有人。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩转身向我挥了挥手。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在台上，他慢慢转身对着大家。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一转身，猫就跳上了桌子。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转了身", "label": "体标"}, {"form": "转过身", "label": "体标"}, {"form": "转个身", "label": "离合"}, {"form": "轉身", "label": "繁体"}], "register": "中性", "sense_fingerprint": "转身：把身体转过去，面对另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转身", "is_correct": true, "explanation": "正确。“转身”表示身体转向，与“往后看”衔接自然。"}, {"text": "闭眼", "is_correct": false, "explanation": "语义：闭上眼睛就看不见，与“往后看”矛盾。"}, {"text": "举起", "is_correct": false, "explanation": "配价：“举起”需要带宾语（如“举起手”），“我举起往后看”不完整。"}, {"text": "面对", "is_correct": false, "explanation": "配价：“面对”后要接对象（如“面对大家”），“我面对往后看”不成立。"}], "explanations": {"转身": "正确。“转身”表示身体转向，与“往后看”衔接自然。", "闭眼": "语义：闭上眼睛就看不见，与“往后看”矛盾。", "举起": "配价：“举起”需要带宾语（如“举起手”），“我举起往后看”不完整。", "面对": "配价：“面对”后要接对象（如“面对大家”），“我面对往后看”不成立。"}, "sentence_index": 0, "correct_answer": "转身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套老房子去年就转身了。", "explanation": "这里应该用〈转手〉。房子等财物卖给或交给别人说转手，转身只指人的身体转向。"}, {"text": "这个电视频道刚才转身了。", "explanation": "这里应该用〈转换〉。频道、形式等发生变化说转换，转身只指人的身体转向。"}, {"text": "他前年从部队转身了。", "explanation": "这里应该用〈转业〉。军人离开部队改做地方工作说转业，转身只指人的身体转向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转身", "is_correct": true, "explanation": "正确。“转身”表示身体转过去，与“看了看，没有人”衔接自然。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时无法看，与“看了看，没有人”矛盾。"}, {"text": "抬起", "is_correct": false, "explanation": "配价：“抬起”需要带宾语（如“抬起头”），“他抬起看了看”不完整。"}, {"text": "闭上", "is_correct": false, "explanation": "语义：闭上眼睛就无法看，与“看了看”矛盾。"}], "explanations": {"转身": "正确。“转身”表示身体转过去，与“看了看，没有人”衔接自然。", "睡觉": "语义：睡觉时无法看，与“看了看，没有人”矛盾。", "抬起": "配价：“抬起”需要带宾语（如“抬起头”），“他抬起看了看”不完整。", "闭上": "语义：闭上眼睛就无法看，与“看了看”矛盾。"}, "sentence_index": 6, "correct_answer": "转身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在路口转身，开向了学校。", "explanation": "这里应该用〈拐弯〉。车辆在路口改变方向说拐弯，转身只指人的身体转向。"}, {"text": "他上个学期转身换了一所学校。", "explanation": "这里应该用〈转学〉。学生换学校说转学，转身只指身体转向。"}, {"text": "出租车在前面转身回去了。", "explanation": "这里应该用〈掉头〉。车辆调转方向说掉头，转身只用于人的身体转向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到喊声，他转身起来看。", "corrected_sentence": "听到喊声，他转过身来看。", "error_description": "“转过身来”是正确的补语形式；“起来”不能接在“转身”后，应说“转过身来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他慢慢转身过，看着窗外。", "corrected_sentence": "他慢慢转过身，看着窗外。", "error_description": "“过”应紧跟“转”，说“转过身”，不能说“转身过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱与攻没有反义关系，不是这个义项的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "跳与攻没有反义关系，不是这个义项的反义词。"}, {"text": "写", "is_correct": false, "explanation": "写与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "唱": "唱与攻没有反义关系，不是这个义项的反义词。", "跳": "跳与攻没有反义关系，不是这个义项的反义词。", "写": "写与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗与攻没有反义关系，不是这个义项的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃与攻没有反义关系，不是这个义项的反义词。"}, {"text": "画", "is_correct": false, "explanation": "画与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "洗": "洗与攻没有反义关系，不是这个义项的反义词。", "吃": "吃与攻没有反义关系，不是这个义项的反义词。", "画": "画与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "攻是冲过去打对方，想打赢。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "我们攻，你们守。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "红队从左边攻，蓝队在右边守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上半场我们一直在攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别只会守，也要会攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们攻得很快，我们守不住。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队一拿到球，就马上攻对方的球门。", "target_word": "攻", "complexity_tier": "T3", "furigana": "wǒ men duì yī ná dào qiú jiù mǎ shàng gōng duì fāng de qiú mén", "sentence_source": "generated"}, {"text": "球队一直攻，可是没有进球。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方攻过来，我们马上往后退。", "target_word": "攻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，比赛时先守后攻最好。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里，我这一队从山上往下攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻了", "label": "体标"}, {"form": "攻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "比赛、游戏或战斗中主动冲向对方，想要取胜（与守相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指主动冲向对方进攻。"}, {"text": "刚", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献、进贡。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}], "explanations": {"攻": "攻 gōng，正确答案，指主动冲向对方进攻。", "刚": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。", "空": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献、进贡。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻是主动冲向对方，与「守」相对，句意通顺。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑不是与守相对的进攻动作，攻守对立的句意不成立。"}, {"text": "赢", "is_correct": false, "explanation": "语义：赢是结果，不是与守相对的主动进攻动作，不符合攻守对立的句意。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻是主动冲向对方，与「守」相对，句意通顺。", "跑": "语义：跑不是与守相对的进攻动作，攻守对立的句意不成立。", "赢": "语义：赢是结果，不是与守相对的主动进攻动作，不符合攻守对立的句意。", "送": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在下半场攻了两个球。", "explanation": "这里应该用〈进〉。得分要说「进球」，攻表示主动冲向对方的动作，不能表示得分。"}, {"text": "汽车攻上了电线杆，车头坏了。", "explanation": "这里应该用〈撞〉。撞表示物体相互碰撞，攻表示主动冲向对方的进攻，不能形容汽车撞上电线杆。"}, {"text": "他把钥匙攻进了锁眼。", "explanation": "这里应该用〈插〉。钥匙插入锁眼要用「插」，攻表示主动冲向对方，不能形容钥匙进入锁眼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指主动冲向对方进攻。"}, {"text": "供", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是供应、供给。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。"}, {"text": "钢", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}], "explanations": {"攻": "攻 gōng，正确答案，指主动冲向对方进攻。", "供": "gòng（第四声）与 gōng（第一声）声调不同，意思是供应、供给。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。", "钢": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻是主动进攻，句中球队一直进攻却没有进球，句意通顺。"}, {"text": "哭", "is_correct": false, "explanation": "语义：比赛语境中「一直哭」与「没有进球」的句意不合，不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡不是比赛动作，球队不会「一直睡」，句意荒谬。"}, {"text": "修", "is_correct": false, "explanation": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻是主动进攻，句中球队一直进攻却没有进球，句意通顺。", "哭": "语义：比赛语境中「一直哭」与「没有进球」的句意不合，不成立。", "睡": "语义：睡不是比赛动作，球队不会「一直睡」，句意荒谬。", "修": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们队终于攻得了冠军。", "explanation": "这里应该用〈夺〉。争得冠军要说「夺得」或「夺冠」，攻不能与「冠军」搭配。"}, {"text": "妈妈把碗攻在地上了，碎了一地。", "explanation": "这里应该用〈摔〉。摔表示物体掉落碰撞，攻表示主动进攻，不能形容碗掉在地上。"}, {"text": "他在中场攻到了球，马上传给队友。", "explanation": "这里应该用〈抢〉。拿到球要说「抢到」，攻表示主动进攻的动作，不说「攻到球」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们攻地很猛，我们只好往后退。", "corrected_sentence": "他们攻得很猛，我们只好往后退。", "error_description": "「攻」后面引出补语要用「得」，不能用「地」（「地」用在动词前）。应说「攻得很猛」，不能说「攻地很猛」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队攻着一次，没有成功。", "corrected_sentence": "我们队攻过一次，没有成功。", "error_description": "表示经历过某次动作要用「过」，「着」表示动作正在进行或持续，不能说「攻着一次」。应说「攻过一次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "游", "is_correct": false, "explanation": "游与攻没有反义关系，不是这个义项的反义词。"}, {"text": "画", "is_correct": false, "explanation": "画与攻没有反义关系，不是这个义项的反义词。"}, {"text": "读", "is_correct": false, "explanation": "读与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "游": "游与攻没有反义关系，不是这个义项的反义词。", "画": "画与攻没有反义关系，不是这个义项的反义词。", "读": "读与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "守", "is_correct": true, "explanation": "守与攻相对，指防守、不主动进攻，是反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗与攻没有反义关系，不是这个义项的反义词。"}, {"text": "笑", "is_correct": false, "explanation": "笑与攻没有反义关系，不是这个义项的反义词。"}, {"text": "煮", "is_correct": false, "explanation": "煮与攻没有反义关系，不是这个义项的反义词。"}], "correct_answer": "守", "explanations": {"守": "守与攻相对，指防守、不主动进攻，是反义关系。", "洗": "洗与攻没有反义关系，不是这个义项的反义词。", "笑": "笑与攻没有反义关系，不是这个义项的反义词。", "煮": "煮与攻没有反义关系，不是这个义项的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进攻；向对方发起进击。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "他们先守后攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我方队员一起往前攻。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "敌人从北边攻，我们在南边守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下半场红队开始攻，蓝队只能守。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，他们从三个方向一起攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你攻左边，我攻右边。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对手一攻，我们就退。", "target_word": "攻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个队很会守，也很会攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把球传到前面，大家一起往前攻。", "target_word": "攻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，主队就大胆地攻。", "target_word": "攻", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "攻了", "label": "体标"}, {"form": "攻过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向对方发起进击，进攻（与守相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指向对方发起进击。"}, {"text": "刚", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}], "explanations": {"攻": "攻 gōng，正确答案，指向对方发起进击。", "刚": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是刚才、刚刚。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻指向对方进击，与前面的「守」相对，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「先守后吃」不构成比赛或战斗的动作，句意荒谬。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与守、攻的语境不合，「先守后唱」句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}], "explanations": {"攻": "攻指向对方进击，与前面的「守」相对，句意通顺。", "吃": "语义：「先守后吃」不构成比赛或战斗的动作，句意荒谬。", "唱": "语义：唱与守、攻的语境不合，「先守后唱」句意不通。", "送": "配价：送需要带宾语（送什么），句中没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把信攻到了桌子底下。", "explanation": "这里应该用〈塞〉。把东西塞到某处要用「塞」，攻表示向对方发起进击，不能形容把信放到桌子底下。"}, {"text": "他把石头攻进了河里。", "explanation": "这里应该用〈扔〉。扔是把东西抛出去的动作，攻表示进攻，不能形容把石头扔进河里。"}, {"text": "我们的队员一脚攻中了门框。", "explanation": "这里应该用〈射中〉。射门击中门框要用「射」，攻不表示射门的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻 gōng，正确答案，指向对方发起进击。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。"}, {"text": "钢", "is_correct": false, "explanation": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}], "explanations": {"攻": "攻 gōng，正确答案，指向对方发起进击。", "空": "kōng 与 gōng 声母不同（送气的 k 与不送气的 g），意思是空的。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱手、拱起。", "钢": "gāng（第一声）与 gōng 韵母不同（a 与 o），意思是钢铁。"}, "sentence_index": null, "correct_answer": "攻"}, "level_3": {"options": [{"text": "攻", "is_correct": true, "explanation": "攻指向对方进击，与「退」相对应，句意通顺。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡不是进攻的动作，「对手一睡，我们就退」句意不成立。"}, {"text": "修", "is_correct": false, "explanation": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗与比赛或战斗的语境不合，「对手一洗」句意荒谬。"}], "explanations": {"攻": "攻指向对方进击，与「退」相对应，句意通顺。", "睡": "语义：睡不是进攻的动作，「对手一睡，我们就退」句意不成立。", "修": "配价：修需要宾语（修什么），句中没有宾语，句子不成立。", "洗": "语义：洗与比赛或战斗的语境不合，「对手一洗」句意荒谬。"}, "sentence_index": 6, "correct_answer": "攻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛一开始，主队就攻到了球。", "explanation": "这里应该用〈抢〉。拿到球要说「抢到」，攻表示主动进攻，不说「攻到球」。"}, {"text": "工人在地上攻了一个坑。", "explanation": "这里应该用〈挖〉。挖是用工具掘开土地的动作，攻表示进攻，不能形容挖坑。"}, {"text": "主队终于攻得了金牌。", "explanation": "这里应该用〈夺〉。争得金牌要说「夺得」，攻不能与「金牌」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们连续攻了三个，都没有成功。", "corrected_sentence": "我们连续攻了三次，都没有成功。", "error_description": "「攻」这类动作的动量词要用「次」，不能用「个」。应说「攻了三次」，不能说「攻了三个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对手曾经攻着我们的城。", "corrected_sentence": "对手曾经攻过我们的城。", "error_description": "「曾经」表示经历过的事，要用体标「过」，「着」表示进行或持续，与「曾经」不搭配。应说「曾经攻过我们的城」，不能说「攻着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
