INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灰是东西烧完以后剩下的很细的粉。", "primary_collocate": null, "pronunciation": "huī", "ipa": "xweɪ˥", "syllable_count": 1, "sentences": [{"text": "纸烧完以后，变成了灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头烧成灰，风一吹就散了。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把烟头上的灰弹掉了。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火炉里的灰要每天清理。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶烧完，只留下一点灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火旁边堆着一小堆灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那封信已经烧成了灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手摸了摸，灰还有点热。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烧过的草变成了黑色的灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把灰撒进了河里。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆灰", "label": "量词"}, {"form": "一层灰", "label": "量词"}], "register": "中性", "sense_fingerprint": "东西烧完后剩下的细粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98457, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灰", "is_correct": true, "explanation": "正确：灰 huī 指东西烧完后剩下的细粉。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 huī（第一声）声调不同，意思是毁。"}, {"text": "汇", "is_correct": false, "explanation": "huì（第四声）与 huī（第一声）声调不同，意思是汇。"}, {"text": "货", "is_correct": false, "explanation": "huò（第四声）与 huī（第一声）声调不同，意思是货。"}, {"text": "怀", "is_correct": false, "explanation": "huái 与 huī 韵母不同（ai 与 ui），意思是怀。"}], "explanations": {"灰": "正确：灰 huī 指东西烧完后剩下的细粉。", "毁": "huǐ（第三声）与 huī（第一声）声调不同，意思是毁。", "汇": "huì（第四声）与 huī（第一声）声调不同，意思是汇。", "货": "huò（第四声）与 huī（第一声）声调不同，意思是货。", "怀": "huái 与 huī 韵母不同（ai 与 ui），意思是怀。"}, "sentence_index": null, "correct_answer": "灰"}, "level_3": {"options": [{"text": "火焰", "is_correct": false, "explanation": "语义：纸烧完后不会变成火焰，火焰是燃烧时的火光。"}, {"text": "灰", "is_correct": true, "explanation": "正确：纸烧完后剩下的是灰，与“烧完以后”相符。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“纸张”是烧之前的材料，“变成了纸张”不符合“烧完”的结果。"}, {"text": "水", "is_correct": false, "explanation": "语义：纸烧完不会变成水，水不是燃烧的结果。"}], "explanations": {"火焰": "语义：纸烧完后不会变成火焰，火焰是燃烧时的火光。", "灰": "正确：纸烧完后剩下的是灰，与“烧完以后”相符。", "纸张": "搭配：“纸张”是烧之前的材料，“变成了纸张”不符合“烧完”的结果。", "水": "语义：纸烧完不会变成水，水不是燃烧的结果。"}, "sentence_index": 0, "correct_answer": "灰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一条灰放进了信封里。", "explanation": "灰是细粉末，应该用〈堆〉或〈点〉，不用〈条〉。"}, {"text": "天很冷，他点燃了一堆灰取暖。", "explanation": "灰已经燃烧过，不能再点燃取暖；这里把“灰”当成了〈柴〉。"}, {"text": "妈妈用灰给我做了一碗汤。", "explanation": "这里把“灰”当成了食材，灰是燃烧后的废物，不能用来做汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98457, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灰", "is_correct": true, "explanation": "正确：灰 huī 指东西烧完后剩下的细粉。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 huī（第一声）声调不同，意思是回。"}, {"text": "会", "is_correct": false, "explanation": "huì（第四声）与 huī（第一声）声调不同，意思是会。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huī（第一声）声调不同，意思是火。"}, {"text": "或", "is_correct": false, "explanation": "huò（第四声）与 huī（第一声）声调不同，意思是或。"}], "explanations": {"灰": "正确：灰 huī 指东西烧完后剩下的细粉。", "回": "huí（第二声）与 huī（第一声）声调不同，意思是回。", "会": "huì（第四声）与 huī（第一声）声调不同，意思是会。", "火": "huǒ（第三声）与 huī（第一声）声调不同，意思是火。", "或": "huò（第四声）与 huī（第一声）声调不同，意思是或。"}, "sentence_index": null, "correct_answer": "灰"}, "level_3": {"options": [{"text": "冰", "is_correct": false, "explanation": "语义：烧完的东西不会变成冰，冰是冷的。"}, {"text": "灰", "is_correct": true, "explanation": "正确：信烧完后变成灰，与“已经烧成了”相符。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“烧成了”多接灰、烟、炭等，不接雪。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是从天上落下的水，不是烧完的结果。"}], "explanations": {"冰": "语义：烧完的东西不会变成冰，冰是冷的。", "灰": "正确：信烧完后变成灰，与“已经烧成了”相符。", "雪": "搭配：“烧成了”多接灰、烟、炭等，不接雪。", "雨": "语义：雨是从天上落下的水，不是烧完的结果。"}, "sentence_index": 6, "correct_answer": "灰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把灰当成面粉，做了一锅饺子。", "explanation": "灰是废物，不能当面粉用，这里用法不对。"}, {"text": "他把灰当成笛子，吹出了一首曲子。", "explanation": "灰是烧完后的细粉，不能当乐器吹奏；这里把“灰”当成了〈笛子〉。"}, {"text": "他把灰当成了宝贝，天天抱着。", "explanation": "灰是烧完后的废物，不能当宝贝珍藏，这样用不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张纸已经烧成了一条灰。", "corrected_sentence": "这张纸已经烧成了灰。", "error_description": "错误在于“灰”的量词用了“条”。灰是细粉末，不用“条”计量，直接说“烧成了灰”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条灰已经凉了。", "corrected_sentence": "那堆灰已经凉了。", "error_description": "错误在于“灰”的量词用了“条”。灰是细粉末，应该用“堆”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
