INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体燃烧后剩下的粉末状东西；也指灰尘。", "primary_collocate": null, "pronunciation": "huī", "ipa": "xweɪ˥", "syllable_count": 1, "sentences": [{"text": "桌子上落了一层灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柴烧完了，只剩下一堆灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把炉子里的灰倒掉。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架很久没擦，上面都是灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弹了弹烟上的灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，地上的灰飞了起来。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灭了，灰还是热的。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进门时，鞋上沾了不少灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗台上积了很多灰，该擦了。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火熄了，地上留着白色的灰。", "target_word": "灰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层灰", "label": "量词"}, {"form": "一堆灰", "label": "量词"}], "register": "中性", "sense_fingerprint": "燃烧后的灰烬，也指落在物体上的灰尘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灰", "is_correct": true, "explanation": "正确：灰 huī 指燃烧后的粉末或灰尘。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 huī（第一声）声调不同，意思是回。"}, {"text": "会", "is_correct": false, "explanation": "huì（第四声）与 huī（第一声）声调不同，意思是会。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huī（第一声）声调不同，意思是火。"}, {"text": "或", "is_correct": false, "explanation": "huò（第四声）与 huī（第一声）声调不同，意思是或。"}], "explanations": {"灰": "正确：灰 huī 指燃烧后的粉末或灰尘。", "回": "huí（第二声）与 huī（第一声）声调不同，意思是回。", "会": "huì（第四声）与 huī（第一声）声调不同，意思是会。", "火": "huǒ（第三声）与 huī（第一声）声调不同，意思是火。", "或": "huò（第四声）与 huī（第一声）声调不同，意思是或。"}, "sentence_index": null, "correct_answer": "灰"}, "level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：灰尘会落在桌上，蛋糕不会从空中落下铺成一层。"}, {"text": "灰", "is_correct": true, "explanation": "正确：“落了一层”后接灰尘，与“桌子上”的语境相符。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“落了一层”多接灰尘、雪、叶子，“墨水”不这样搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是下落的水，不会积成一层留在桌上。"}], "explanations": {"蛋糕": "语义：灰尘会落在桌上，蛋糕不会从空中落下铺成一层。", "灰": "正确：“落了一层”后接灰尘，与“桌子上”的语境相符。", "墨水": "搭配：“落了一层”多接灰尘、雪、叶子，“墨水”不这样搭配。", "雨": "语义：雨是下落的水，不会积成一层留在桌上。"}, "sentence_index": 0, "correct_answer": "灰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上有一根灰。", "explanation": "灰是细粉末，应该用〈层〉或〈堆〉，不用〈根〉。"}, {"text": "他把灰折成了一架纸飞机。", "explanation": "这里把“灰”误当成了〈纸〉。灰是燃烧后的细粉，不能折叠，所以不能折成纸飞机。"}, {"text": "他脸色很灰，像是病了。", "explanation": "这里的〈灰〉是颜色（脸色发灰），不是燃烧后的粉末或灰尘，与本义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98458, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灰", "is_correct": true, "explanation": "正确：灰 huī 指燃烧后的粉末或灰尘。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 huī（第一声）声调不同，意思是毁。"}, {"text": "汇", "is_correct": false, "explanation": "huì（第四声）与 huī（第一声）声调不同，意思是汇。"}, {"text": "货", "is_correct": false, "explanation": "huò（第四声）与 huī（第一声）声调不同，意思是货。"}, {"text": "怀", "is_correct": false, "explanation": "huái 与 huī 韵母不同（ai 与 ui），意思是怀。"}], "explanations": {"灰": "正确：灰 huī 指燃烧后的粉末或灰尘。", "毁": "huǐ（第三声）与 huī（第一声）声调不同，意思是毁。", "汇": "huì（第四声）与 huī（第一声）声调不同，意思是汇。", "货": "huò（第四声）与 huī（第一声）声调不同，意思是货。", "怀": "huái 与 huī 韵母不同（ai 与 ui），意思是怀。"}, "sentence_index": null, "correct_answer": "灰"}, "level_3": {"options": [{"text": "冰", "is_correct": false, "explanation": "语义：火灭了以后剩下的不会是冰，而且冰不是热的。"}, {"text": "灰", "is_correct": true, "explanation": "正确：火灭后剩下的灰，还带着余热，与“还是热的”相符。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“热的”不与“雪”搭配，雪是冷的。"}, {"text": "露", "is_correct": false, "explanation": "语义：露是清晨的水珠，不会是热的。"}], "explanations": {"冰": "语义：火灭了以后剩下的不会是冰，而且冰不是热的。", "灰": "正确：火灭后剩下的灰，还带着余热，与“还是热的”相符。", "雪": "搭配：“热的”不与“雪”搭配，雪是冷的。", "露": "语义：露是清晨的水珠，不会是热的。"}, "sentence_index": 6, "correct_answer": "灰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把灰放进嘴里，觉得很甜。", "explanation": "这里把“灰”当成了可以入口的食物，灰是燃烧后的废物，不能吃。"}, {"text": "他把灰当作信物，送给了朋友。", "explanation": "这里把“灰”当成了〈礼物〉或信物，灰是烧完后剩下的细粉，不能当作信物送人。"}, {"text": "他把一根灰撒进了河里。", "explanation": "灰是细粉末，不用〈根〉计量；应说〈一把灰〉或〈一些灰〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上落了一根灰。", "corrected_sentence": "窗台上落了一层灰。", "error_description": "错误在于“灰”的量词用了“根”。灰是细粉末，应该用“层”，不用“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "炉子里还留着一条灰。", "corrected_sentence": "炉子里还留着一层灰。", "error_description": "错误在于“灰”的量词用了“条”。灰是细粉末，应该用“层”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
