INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "祝贺是别人有了高兴的事，你对他说好听的话。", "primary_collocate": null, "pronunciation": "zhù hè", "ipa": "ʈʂu˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你拿到奖学金了，我真心祝贺你。", "target_word": "祝贺", "complexity_tier": "T3", "furigana": "nǐ ná dào jiǎng xué jīn le, wǒ zhēn xīn zhù hè nǐ.", "sentence_source": "generated"}, {"text": "她考了第一名，我去祝贺她。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说你买了新房子，祝贺你！", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家围着他，祝贺他得奖。", "target_word": "祝贺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷八十岁生日，亲戚们都来祝贺。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我写了一张卡片，祝贺同事升职。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹收到了通知书，我们祝贺她。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都打电话祝贺他们。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司成立十年，客人们都来祝贺。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你赢了比赛，我真心祝贺你。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝贺了", "label": "体标"}, {"form": "祝贺过", "label": "体标"}, {"form": "祝贺祝贺", "label": "重叠"}, {"form": "祝賀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人遇到高兴的事，你对他说好听的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祝贺", "is_correct": true, "explanation": "“祝贺”表示对对方获得奖学金这一喜事表示高兴，句意通顺。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”含否定评价，与“拿到奖学金”这一喜事相矛盾。"}, {"text": "怜悯", "is_correct": false, "explanation": "语域：“怜悯”是书面用语，表示对不幸者的同情，与喜事的语境矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含嘲弄之意，与“真心”的表达相矛盾。"}], "explanations": {"祝贺": "“祝贺”表示对对方获得奖学金这一喜事表示高兴，句意通顺。", "批评": "语义：“批评”含否定评价，与“拿到奖学金”这一喜事相矛盾。", "怜悯": "语域：“怜悯”是书面用语，表示对不幸者的同情，与喜事的语境矛盾。", "嘲笑": "语义：“嘲笑”含嘲弄之意，与“真心”的表达相矛盾。"}, "sentence_index": 0, "correct_answer": "祝贺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他受伤了，大家都来祝贺他。", "explanation": "这里应该用〈安慰〉。“祝贺”针对对方的喜事，对方受伤要用“安慰”。"}, {"text": "爷爷病重住院，我们都祝贺他健康长寿。", "explanation": "这里应该用〈祝福〉。病重不是喜事，表示健康长寿的美好祝愿要用“祝福”；“祝贺”针对对方的喜事。"}, {"text": "他帮大家搬了东西，大家都来祝贺他。", "explanation": "这里应该用〈感谢〉。对方帮了忙，要说“感谢”；“祝贺”针对对方的喜事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祝贺", "is_correct": true, "explanation": "“祝贺”表示对收到通知书这件喜事表示高兴，符合句意。"}, {"text": "哀悼", "is_correct": false, "explanation": "语义：“哀悼”表示悲痛，与收到通知书的喜事不合。"}, {"text": "警告", "is_correct": false, "explanation": "语义：「警告」针对对方的过失或危险，与收到通知书这件喜事不合。"}, {"text": "吊唁", "is_correct": false, "explanation": "语域：“吊唁”是书面词，专用于丧事，与收到通知书的场合不符。"}], "explanations": {"祝贺": "“祝贺”表示对收到通知书这件喜事表示高兴，符合句意。", "哀悼": "语义：“哀悼”表示悲痛，与收到通知书的喜事不合。", "警告": "语义：「警告」针对对方的过失或危险，与收到通知书这件喜事不合。", "吊唁": "语域：“吊唁”是书面词，专用于丧事，与收到通知书的场合不符。"}, "sentence_index": 6, "correct_answer": "祝贺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的父亲去世了，我真心祝贺她。", "explanation": "这里应该用〈哀悼〉。“祝贺”针对对方的喜事，亲人去世要用“哀悼”。"}, {"text": "他摔断了腿，我真心祝贺他。", "explanation": "这里应该用〈慰问〉。“祝贺”针对喜事，对方受伤要用“慰问”。"}, {"text": "公司亏损严重，我真心祝贺你。", "explanation": "这里应该用〈同情〉。“祝贺”针对喜事，对方陷入困境时要表示“同情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她当上经理，同事们都祝贺着她。", "corrected_sentence": "她当上经理，同事们都祝贺了她。", "error_description": "体标错误：“祝贺”这里指已经完成的动作，应用“了”，说“祝贺了她”，不能用表示持续的“着”，说“祝贺着她”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹考上了研究生，我们都祝贺着她。", "corrected_sentence": "妹妹考上了研究生，我们都祝贺她。", "error_description": "体标错误：“祝贺”表示一次性的庆祝，不带“着”，应说“祝贺她”，不能说“祝贺着她”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
