INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人的喜事表示高兴并说吉利话。", "primary_collocate": null, "pronunciation": "zhù hè", "ipa": "ʈʂu˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "祝贺你考上大学！", "target_word": "祝贺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都来祝贺他结婚。", "target_word": "祝贺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我打电话祝贺姐姐生了女儿。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们一起祝贺他找到了新工作。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿到冠军，同学们都向他祝贺。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想当面祝贺王老师得奖。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，对手也来祝贺我们。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一进门，大家就祝贺他当爸爸。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "祝贺你们新婚，白头到老！", "target_word": "祝贺", "complexity_tier": "T3", "furigana": "zhù hè nǐ men xīn hūn, bái tóu dào lǎo!", "sentence_source": "generated"}, {"text": "老同学评上了教授，我发信息祝贺他。", "target_word": "祝贺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝贺了", "label": "体标"}, {"form": "祝贺过", "label": "体标"}, {"form": "祝贺祝贺", "label": "重叠"}, {"form": "祝賀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人有喜事时，表示高兴并说吉利话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祝贺", "is_correct": true, "explanation": "“祝贺”表示对“你考上大学”这一喜事表示高兴，填入句中意思通顺。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是为对方的帮助而致谢，“考上大学”不是对说话人的帮助，句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”含否定评价，与“考上大学”这一喜事相矛盾。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”后接尚未发生或不确定的事，“考上大学”已成定局，不能说“担心”。"}], "explanations": {"祝贺": "“祝贺”表示对“你考上大学”这一喜事表示高兴，填入句中意思通顺。", "感谢": "语义：“感谢”是为对方的帮助而致谢，“考上大学”不是对说话人的帮助，句意不通。", "批评": "语义：“批评”含否定评价，与“考上大学”这一喜事相矛盾。", "担心": "搭配：“担心”后接尚未发生或不确定的事，“考上大学”已成定局，不能说“担心”。"}, "sentence_index": 0, "correct_answer": "祝贺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一起祝贺国庆节。", "explanation": "这里应该用〈庆祝〉。“祝贺”针对他人的喜事，对象是人；庆祝节日、活动要用“庆祝”。"}, {"text": "他生病住院了，我们都祝贺他。", "explanation": "这里应该用〈同情〉。“祝贺”针对对方的喜事，对方生病是不幸的事，要表示“同情”。"}, {"text": "朋友们一起祝贺他帮了我们的忙。", "explanation": "这里应该用〈感谢〉。对方帮了我们的忙，要说“感谢”；“祝贺”针对对方的喜事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祝贺", "is_correct": true, "explanation": "“祝贺”表示对对方的喜事表示高兴，句中指对手赛后前来道贺，符合句意。"}, {"text": "打败", "is_correct": false, "explanation": "语义：比赛已经结束、胜负已定，“打败”与句中“比赛结束后”的时间背景相矛盾。"}, {"text": "围攻", "is_correct": false, "explanation": "语义：“围攻”含敌意，与赛后“也来”所表达的友好语境不合。"}, {"text": "咒骂", "is_correct": false, "explanation": "语域：“咒骂”语气激烈、带贬义，不适合赛后礼节性的场合。"}], "explanations": {"祝贺": "“祝贺”表示对对方的喜事表示高兴，句中指对手赛后前来道贺，符合句意。", "打败": "语义：比赛已经结束、胜负已定，“打败”与句中“比赛结束后”的时间背景相矛盾。", "围攻": "语义：“围攻”含敌意，与赛后“也来”所表达的友好语境不合。", "咒骂": "语域：“咒骂”语气激烈、带贬义，不适合赛后礼节性的场合。"}, "sentence_index": 6, "correct_answer": "祝贺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老同学的父亲去世了，我发信息祝贺他。", "explanation": "这里应该用〈哀悼〉。“祝贺”针对对方的喜事，对方的亲人去世要用“哀悼”。"}, {"text": "老同学家里遭了火灾，我发信息祝贺他。", "explanation": "这里应该用〈慰问〉。“祝贺”针对喜事，对方遭受灾祸要用“慰问”。"}, {"text": "老同学的公司破产了，我发信息祝贺他。", "explanation": "这里应该用〈安慰〉。“祝贺”针对喜事，对方遭遇挫折要用“安慰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他升职以后，我们都把祝贺了他。", "corrected_sentence": "他升职以后，我们都祝贺了他。", "error_description": "「祝贺」不是处置性动词，不能用「把」字句，「把」应去掉。应说「我们都祝贺了他」，不能说「我们都把祝贺了他」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拿到冠军，我们都祝贺给他。", "corrected_sentence": "他拿到冠军，我们都祝贺他。", "error_description": "“祝贺”是及物动词，直接带宾语“他”，不能像“送”那样在动词后加“给”，应说“祝贺他”，不能说“祝贺给他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
