INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指引是告诉你该往哪里走，该怎么做。", "primary_collocate": null, "pronunciation": "zhǐ yǐn", "ipa": "tʂɨ˨˩˦ in˨˩˦", "syllable_count": 2, "sentences": [{"text": "路牌指引我们走向出口。", "target_word": "指引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图指引我们找到了那家书店。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你指引我去火车站，好吗？", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保安指引客人走到停车场。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上的导航一直指引着我们前进。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光指引我们走进了山里的小屋。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他举着手电筒，指引大家往山下走。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用手指引我们往海边走。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "箭头指引着游客走向展览厅。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的工作人员指引我们去办理登机手续。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指引着", "label": "持续体"}, {"form": "指引了", "label": "完成体"}, {"form": "指引过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用路牌、地图、话语等告诉人该往哪里走、怎么走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98841, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”是告诉人该往哪里走、该怎么做，两个音节都是第三声。"}, {"text": "指印", "is_correct": false, "explanation": "指印（zhǐyìn）与指引（zhǐyǐn）第二音节声调不同（yìn 第四声），意思是手指按下的印迹。"}, {"text": "只因", "is_correct": false, "explanation": "只因（zhǐyīn）与指引（zhǐyǐn）第二音节声调不同（yīn 第一声），意思是“只是因为”。"}, {"text": "纸银", "is_correct": false, "explanation": "纸银（zhǐyín）与指引（zhǐyǐn）第二音节声调不同（yín 第二声），意思是烧给亡者的纸钱。"}, {"text": "致因", "is_correct": false, "explanation": "致因（zhìyīn）两个音节声调都与指引不同，意思是导致某种结果的原因。"}], "explanations": {"指引": "正确。“指引”是告诉人该往哪里走、该怎么做，两个音节都是第三声。", "指印": "指印（zhǐyìn）与指引（zhǐyǐn）第二音节声调不同（yìn 第四声），意思是手指按下的印迹。", "只因": "只因（zhǐyīn）与指引（zhǐyǐn）第二音节声调不同（yīn 第一声），意思是“只是因为”。", "纸银": "纸银（zhǐyín）与指引（zhǐyǐn）第二音节声调不同（yín 第二声），意思是烧给亡者的纸钱。", "致因": "致因（zhìyīn）两个音节声调都与指引不同，意思是导致某种结果的原因。"}, "sentence_index": null, "correct_answer": "指引"}, "level_3": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”指给出方向，路牌可以指引人走向出口。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是拦住不让走，与“走向出口”的指引方向相反。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”是去迎上来接人，与“走向出口”的方向不合。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要“送+人+到+处所”的格式，“路牌送我们走向出口”格式不对。"}], "explanations": {"指引": "正确。“指引”指给出方向，路牌可以指引人走向出口。", "阻止": "语义：“阻止”是拦住不让走，与“走向出口”的指引方向相反。", "迎接": "语义：“迎接”是去迎上来接人，与“走向出口”的方向不合。", "送": "配价：“送”需要“送+人+到+处所”的格式，“路牌送我们走向出口”格式不对。"}, "sentence_index": 0, "correct_answer": "指引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指引了我作文里的错别字。", "explanation": "这里应该用〈指出〉。指出错误、问题要说指出，指引表示告诉人往哪里走、怎么做。"}, {"text": "这个温度计指引室内温度是二十度。", "explanation": "这里应该用〈指示〉。仪器显示数值说指示，指引表示引导人往哪里走、该怎么做，不能用于温度计。"}, {"text": "他当众指引我的做法不对。", "explanation": "这里应该用〈指责〉。批评别人的做法要说指责，指引不能用来批评人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”是告诉大家往哪里走，与“往山下走”衔接自然。"}, {"text": "挥手", "is_correct": false, "explanation": "配价：“挥手”是不及物动词，不能直接带“大家”作宾语，需说“挥手让大家”。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”是避开，与带大家往山下走的意思相反。"}, {"text": "阻拦", "is_correct": false, "explanation": "语义：“阻拦”是拦住不让走，与带大家往山下走的指引方向相反。"}], "explanations": {"指引": "正确。“指引”是告诉大家往哪里走，与“往山下走”衔接自然。", "挥手": "配价：“挥手”是不及物动词，不能直接带“大家”作宾语，需说“挥手让大家”。", "躲避": "语义：“躲避”是避开，与带大家往山下走的意思相反。", "阻拦": "语义：“阻拦”是拦住不让走，与带大家往山下走的指引方向相反。"}, "sentence_index": 6, "correct_answer": "指引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校指引我当班长。", "explanation": "这里应该用〈指定〉。任命人选要说指定，指引表示告诉人往哪里走。"}, {"text": "他指引了我的发音错误。", "explanation": "这里应该用〈指正〉。指出并改正错误要说指正，指引表示引导方向。"}, {"text": "公司指引他去北京出差。", "explanation": "这里应该用〈指派〉。安排人员承担工作要说指派，指引不能表示安排任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "导游指引了了我们走向出口。", "corrected_sentence": "导游指引了我们走向出口。", "error_description": "“了”是完成体标记，只能用一个，应说“指引了我们”，不能重复写成“指引了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人指引了着我们往山下走。", "corrected_sentence": "老人指引着我们往山下走。", "error_description": "“着”是持续体标记，不能与完成体“了”同时出现，应说“指引着我们”，不能在“指引”后再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
