INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指点引导。", "primary_collocate": null, "pronunciation": "zhǐ yǐn", "ipa": "tʂɨ˨˩˦ in˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师指引我们学习的方向。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师会指引学生找到自己的路。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅耐心地指引年轻人学手艺。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话指引我选择了医学专业。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书指引许多年轻人走上了写作的道路。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用自己的经历指引后辈少走弯路。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信仰指引着他度过了最难的日子。", "target_word": "指引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理指引新同事熟悉公司的工作。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人指引，学生就不容易迷失方向。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想做一个能指引别人的好领导。", "target_word": "指引", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指引着", "label": "持续体"}, {"form": "指引了", "label": "完成体"}, {"form": "指引过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "老师、长辈、信仰等在方向、道路、做人做事上指点并引导别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”是指点引导，两个音节都是第三声。"}, {"text": "指印", "is_correct": false, "explanation": "指印（zhǐyìn）与指引（zhǐyǐn）第二音节声调不同（yìn 第四声），意思是手指按下的印迹。"}, {"text": "只因", "is_correct": false, "explanation": "只因（zhǐyīn）与指引（zhǐyǐn）第二音节声调不同（yīn 第一声），意思是“只是因为”。"}, {"text": "纸银", "is_correct": false, "explanation": "纸银（zhǐyín）与指引（zhǐyǐn）第二音节声调不同（yín 第二声），意思是烧给亡者的纸钱。"}, {"text": "致因", "is_correct": false, "explanation": "致因（zhìyīn）两个音节声调都与指引不同，意思是导致某种结果的原因。"}], "explanations": {"指引": "正确。“指引”是指点引导，两个音节都是第三声。", "指印": "指印（zhǐyìn）与指引（zhǐyǐn）第二音节声调不同（yìn 第四声），意思是手指按下的印迹。", "只因": "只因（zhǐyīn）与指引（zhǐyǐn）第二音节声调不同（yīn 第一声），意思是“只是因为”。", "纸银": "纸银（zhǐyín）与指引（zhǐyǐn）第二音节声调不同（yín 第二声），意思是烧给亡者的纸钱。", "致因": "致因（zhìyīn）两个音节声调都与指引不同，意思是导致某种结果的原因。"}, "sentence_index": null, "correct_answer": "指引"}, "level_3": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”指给出方向，与“我们学习的方向”搭配自然。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”是剪去多余的枝叶，与指点学习方向无关。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”与“学习的方向”搭配不合理，与指点的意思无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的宾语应是货物，不说“搬运学习的方向”。"}], "explanations": {"指引": "正确。“指引”指给出方向，与“我们学习的方向”搭配自然。", "修剪": "语义：“修剪”是剪去多余的枝叶，与指点学习方向无关。", "吃掉": "语义：“吃掉”与“学习的方向”搭配不合理，与指点的意思无关。", "搬运": "搭配：“搬运”的宾语应是货物，不说“搬运学习的方向”。"}, "sentence_index": 0, "correct_answer": "指引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只钟的指针指引十二点。", "explanation": "这里应该用〈指向〉。指针、箭头等朝某个方向或位置说指向，指引表示指点引导，不能用于指针。"}, {"text": "班主任指引他的做法不对。", "explanation": "这里应该用〈指责〉。批评别人的做法说指责，指引表示指点引导，不能表示批评。"}, {"text": "老板指引员工加班到深夜。", "explanation": "这里应该用〈指使〉。命令别人去做事要说指使，指引表示指点引导，不表示命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指引", "is_correct": true, "explanation": "正确。“指引”表示给出方向和力量，与“信仰……着他”搭配自然。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含讥讽的意味，与信仰给人支撑的语境相反。"}, {"text": "扔掉", "is_correct": false, "explanation": "体貌：“扔掉”表示结果，不能与“着”连用表示持续的状态。"}, {"text": "捆绑", "is_correct": false, "explanation": "语义：“捆绑”是束缚，与信仰给人力量的意思相反。"}], "explanations": {"指引": "正确。“指引”表示给出方向和力量，与“信仰……着他”搭配自然。", "嘲笑": "语义：“嘲笑”含讥讽的意味，与信仰给人支撑的语境相反。", "扔掉": "体貌：“扔掉”表示结果，不能与“着”连用表示持续的状态。", "捆绑": "语义：“捆绑”是束缚，与信仰给人力量的意思相反。"}, "sentence_index": 6, "correct_answer": "指引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司指引他负责这个项目。", "explanation": "这里应该用〈指定〉。安排人选负责某事要说指定，指引表示指点引导。"}, {"text": "目击者指引了小偷。", "explanation": "这里应该用〈指认〉。确认某人身份要说指认，指引表示指点引导。"}, {"text": "他指引了这场音乐会的演出。", "explanation": "这里应该用〈指挥〉。带领乐队演奏、统一调度说指挥，指引表示指点引导，不能用于演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师正在指引了我们学习的方向。", "corrected_sentence": "老师正在指引我们学习的方向。", "error_description": "错误：“正在”表示动作进行中，不能与完成标记“了”同用，应去掉“了”，说“正在指引”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经指引着许多年轻人。", "corrected_sentence": "他曾经指引过许多年轻人。", "error_description": "体标记错误：“曾经”表示过去的经历，应与经历体“过”搭配；“着”表示持续状态，不能与“曾经”连用，应说“指引过许多年轻人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
