INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98913, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注射是用针把药水打进身体里。", "primary_collocate": null, "pronunciation": "zhù shè", "ipa": "tʂu˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说我今天要注射一针。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明很勇敢，注射时一点儿也不哭。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院二楼可以注射疫苗。", "target_word": "注射", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "注射以后，你要在这里坐十分钟。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不怕注射，只怕吃苦药。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天到了，很多人去社区医院注射流感疫苗。", "target_word": "注射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士轻轻地给我注射，我几乎没有感觉。", "target_word": "注射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注射的时候，针很细，不太疼。", "target_word": "注射", "complexity_tier": "T3", "furigana": "zhù shè", "sentence_source": "generated"}, {"text": "奶奶有糖尿病，每天早上要注射一次。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天下午要去注射狂犬疫苗。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "注射了", "label": "完成体"}, {"form": "注射过", "label": "经历体"}, {"form": "注射器", "label": "复合词"}, {"form": "注射液", "label": "复合词"}], "register": "中性", "sense_fingerprint": "日常看病、防病时用针把药水打进身体里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "注射", "is_correct": true, "explanation": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。"}, {"text": "注释", "is_correct": false, "explanation": "第二音节韵母不同：shì 为 -i，shè 为 -e；注释意思是解释字词或文句。"}, {"text": "直射", "is_correct": false, "explanation": "第一音节声调不同：zhí 为第二声，zhù 为第四声；直射意思是光线笔直照射。"}, {"text": "祝贺", "is_correct": false, "explanation": "第二音节声母不同：hè 为 h，shè 为 sh；祝贺意思是庆贺。"}, {"text": "畜舍", "is_correct": false, "explanation": "第一音节声母不同：xù 为 x，zhù 为 zh；畜舍意思是养牲畜的房舍。"}], "explanations": {"注射": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。", "注释": "第二音节韵母不同：shì 为 -i，shè 为 -e；注释意思是解释字词或文句。", "直射": "第一音节声调不同：zhí 为第二声，zhù 为第四声；直射意思是光线笔直照射。", "祝贺": "第二音节声母不同：hè 为 h，shè 为 sh；祝贺意思是庆贺。", "畜舍": "第一音节声母不同：xù 为 x，zhù 为 zh；畜舍意思是养牲畜的房舍。"}, "sentence_index": null, "correct_answer": "注射"}, "level_3": {"options": [{"text": "量", "is_correct": false, "explanation": "搭配：“量”配体温、血压，不能说“量一针”。"}, {"text": "注射", "is_correct": true, "explanation": "注射：用针把药液打入体内，与“要……一针”的句意相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”配饮料、汤水，针剂不能喝。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹拭，与“要……一针”指打针的动作不符。"}], "explanations": {"量": "搭配：“量”配体温、血压，不能说“量一针”。", "注射": "注射：用针把药液打入体内，与“要……一针”的句意相合。", "喝": "搭配：“喝”配饮料、汤水，针剂不能喝。", "擦": "语义：“擦”是抹拭，与“要……一针”指打针的动作不符。"}, "sentence_index": 0, "correct_answer": "注射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把知识注射给学生。", "explanation": "这里应该用〈灌输〉。注射专指用针把药液打进人体，抽象的知识要用“灌输”。"}, {"text": "医生给他注射了血。", "explanation": "这里应该用〈输〉。注射指把药液打入体内，输血要用“输”，血液不能说注射。"}, {"text": "他把牛奶注射进了瓶子里。", "explanation": "这里应该用〈灌〉。注射只用于把药液打入人或动物体内，往瓶子里灌牛奶要用“灌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98913, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "注射", "is_correct": true, "explanation": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。"}, {"text": "注视", "is_correct": false, "explanation": "第二音节韵母不同：shì 为 -i，shè 为 -e；注视意思是凝视。"}, {"text": "猪舍", "is_correct": false, "explanation": "第一音节声调不同：zhū 为第一声，zhù 为第四声；猪舍意思是养猪的棚屋。"}, {"text": "注册", "is_correct": false, "explanation": "第二音节声母不同：cè 为 c，shè 为 sh；注册意思是登记。"}], "explanations": {"注射": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。", "注视": "第二音节韵母不同：shì 为 -i，shè 为 -e；注视意思是凝视。", "猪舍": "第一音节声调不同：zhū 为第一声，zhù 为第四声；猪舍意思是养猪的棚屋。", "注册": "第二音节声母不同：cè 为 c，shè 为 sh；注册意思是登记。"}, "sentence_index": null, "correct_answer": "注射"}, "level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿啃，与护士给人打针的动作不符。"}, {"text": "注射", "is_correct": true, "explanation": "注射：用针把药液打入身体，与“轻轻地”和“几乎没有感觉”的句意相合。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球或用脚的动作，不能用于针剂。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘取，与“轻轻地”给人打针的动作不符。"}], "explanations": {"咬": "语义：“咬”是用牙齿啃，与护士给人打针的动作不符。", "注射": "注射：用针把药液打入身体，与“轻轻地”和“几乎没有感觉”的句意相合。", "踢": "搭配：“踢”的对象是球或用脚的动作，不能用于针剂。", "挖": "语义：“挖”是掘取，与“轻轻地”给人打针的动作不符。"}, "sentence_index": 6, "correct_answer": "注射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大量的水注射进了水库。", "explanation": "这里应该用〈注入〉。注射专指把药液打进人体或动物体内，大量的水流入水库要用“注入”。"}, {"text": "他往碗里注射了一点汤。", "explanation": "这里应该用〈倒〉。注射只用于把药液送入体内，往碗里倒汤要用“倒”。"}, {"text": "工人在墙上注射了一层油漆。", "explanation": "这里应该用〈刷〉。注射只指把药水打进人或动物体内，往墙上涂油漆要用“刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士把药水注射了我的胳膊里。", "corrected_sentence": "护士把药水注射进了我的胳膊里。", "error_description": "错误：“注射”后漏掉了表示进入方向的补语“进”，应说“注射进了……里”，不能说“注射了……里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不注射过流感疫苗。", "corrected_sentence": "我没注射过流感疫苗。", "error_description": "错误：表示“从未有过经历”要用否定副词“没”，“不”不能与“过”搭配，应说“没注射过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
